struct pinned_stage_slot {
    void *host = nullptr;
    cudaEvent_t done = nullptr;
    cudaEvent_t copy_start = nullptr;
    cudaEvent_t copy_done = nullptr;
    size_t stage_trace_begin = SIZE_MAX;
    size_t stage_trace_count = 0;
    bool pending = false;
    bool timing_pending = false;
    bool q4_ram_hit_timing_pending = false;
    int q4_ram_hit_layer = -1;
    uint64_t q4_ram_hit_bytes = 0;
    q4_colibri_object_marker q4_object;
    uint64_t q4_object_used = 0;
    uint64_t q4_object_read_us = 0;
};

struct pinned_stage_ring {
    std::vector<pinned_stage_slot> slots;
    size_t slot_sz = 0;
    void *host_block = nullptr;
