    bool host_contiguous = false;
    bool host_pageable = false;
    size_t report_slot_sz = 0;
    size_t report_slots = 0;
    bool report_pageable = false;
    size_t next = 0;
    bool failed = false;
    bool report_registered = false;
#if defined(GGML_MOE_HAS_LIBURING) && !defined(_WIN32)
    io_uring *uring = nullptr;
    size_t uring_depth = 0;
    unsigned int uring_flags = 0;
    bool uring_fixed_buffers = false;
    bool uring_fixed_files = false;
    int uring_fixed_file_fd = -1;
#endif
    uint64_t copies = 0;
    uint64_t waits = 0;
