static constexpr int HARD1_ROLLING_V2_MARKOV_ORDER = 4;

struct hard1_rolling_v2_markov_key {
    int experts[HARD1_ROLLING_V2_MARKOV_ORDER];

    bool operator==(const hard1_rolling_v2_markov_key &other) const {
        for (int i = 0; i < HARD1_ROLLING_V2_MARKOV_ORDER; ++i) {
            if (experts[i] != other.experts[i]) return false;
        }
        return true;
    }
};

struct hard1_rolling_v2_markov_key_hash {
    size_t operator()(const hard1_rolling_v2_markov_key &key) const {
        size_t hash = (size_t)1469598103934665603ULL;
        for (int i = 0; i < HARD1_ROLLING_V2_MARKOV_ORDER; ++i) {
            hash ^= (size_t)(uint32_t)key.experts[i];
            hash *= (size_t)1099511628211ULL;
        }
        return hash;
    }
};

struct hard1_rolling_v2_markov_transition {
    std::unordered_map<int, uint32_t> counts;
    uint32_t total = 0;
};

struct hard1_rolling_v2_markov_layer {
    int history[HARD1_ROLLING_V2_MARKOV_ORDER] = {};
    int history_size = 0;
    std::unordered_map<
        hard1_rolling_v2_markov_key,
        hard1_rolling_v2_markov_transition,
        hard1_rolling_v2_markov_key_hash> transitions;
};

struct hard1_rolling_v2_spec_state {
    int previous_expert[128];
    int issued_expert[128];
    hard1_rolling_v2_markov_layer markov[128];

    hard1_rolling_v2_spec_state() {
        std::fill_n(previous_expert, 128, -1);
        std::fill_n(issued_expert, 128, -1);
    }

    void reset_markov() {
        std::fill_n(issued_expert, 128, -1);
        for (hard1_rolling_v2_markov_layer &layer : markov) {
            layer.history_size = 0;
            layer.transitions.clear();
        }
    }

    void observe_markov(int layer_index, int expert) {
        if (layer_index < 0 || layer_index >= 128 || expert < 0) return;
        hard1_rolling_v2_markov_layer &layer = markov[layer_index];
        if (layer.history_size == HARD1_ROLLING_V2_MARKOV_ORDER) {
            hard1_rolling_v2_markov_key key{};
            std::copy_n(
                layer.history, HARD1_ROLLING_V2_MARKOV_ORDER, key.experts);
            hard1_rolling_v2_markov_transition &transition =
                layer.transitions[key];
            ++transition.total;
            ++transition.counts[expert];
            std::move(
                layer.history + 1,
                layer.history + HARD1_ROLLING_V2_MARKOV_ORDER,
                layer.history);
            layer.history[HARD1_ROLLING_V2_MARKOV_ORDER - 1] = expert;
        } else {
            layer.history[layer.history_size++] = expert;
        }
    }

    int predict_markov(int layer_index, bool &trained_context) const {
        trained_context = false;
        if (layer_index < 0 || layer_index >= 128) return -1;
        const hard1_rolling_v2_markov_layer &layer = markov[layer_index];
        if (layer.history_size != HARD1_ROLLING_V2_MARKOV_ORDER) return -1;
        hard1_rolling_v2_markov_key key{};
        std::copy_n(
            layer.history, HARD1_ROLLING_V2_MARKOV_ORDER, key.experts);
        const auto found = layer.transitions.find(key);
        if (found == layer.transitions.end() || found->second.total < 3) return -1;
        trained_context = true;

        int best_expert = -1;
        uint32_t best_count = 0;
        bool tied = false;
        for (const auto &count : found->second.counts) {
            if (count.second > best_count) {
                best_expert = count.first;
                best_count = count.second;
                tied = false;
            } else if (count.second == best_count) {
                tied = true;
            }
        }
        if (tied || best_count * 4 < found->second.total * 3) return -1;
        return best_expert;
    }
};

