static size_t moe_stream_q8_1_row_bytes(int64_t ne00) {
    const int64_t ne00_padded = GGML_PAD(ne00, MATRIX_ROW_PADDING);
    return (size_t)ne00_padded * sizeof(block_q8_1) / QK8_1;
