static bool moe_phase_env_enabled(const char *name) {
    const char *env = std::getenv(name);
    return env && env[0] && env[0] != '0';
}

// Task 136 is split into independently measurable arms.  The cache and
// publication arms imply the merged provider arm, but not vice versa.
static bool hard1_structure_io_requested() {
    return moe_phase_env_enabled("GGML_MOE_STREAM_HARD1_STRUCTURE_IO") ||
        moe_phase_env_enabled("GGML_MOE_STREAM_HARD1_WHOLE_EXPERT_CACHE") ||
        moe_phase_env_enabled("GGML_MOE_STREAM_HARD1_LAYER_PUBLISH");
}

static bool hard1_whole_expert_cache_requested() {
    return moe_phase_env_enabled(
        "GGML_MOE_STREAM_HARD1_WHOLE_EXPERT_CACHE") ||
        moe_phase_env_enabled("GGML_MOE_STREAM_HARD1_LAYER_PUBLISH");
}



static uint64_t moe_phase_env_mib(const char *name, uint64_t fallback) {
    const char *env = std::getenv(name);
    if (!env || !env[0]) {
        return fallback;
    }
    char *end = nullptr;
    const unsigned long long value = std::strtoull(env, &end, 10);
    return end != env ? (uint64_t)value : fallback;
}

static size_t moe_phase_env_bytes(const char *name, size_t fallback) {
    const char *env = std::getenv(name);
    if (!env || !env[0]) {
        return fallback;
    }
    char *end = nullptr;
    const unsigned long long value = std::strtoull(env, &end, 10);
    return end != env && value > 0 ?
        (size_t)value : fallback;
}

static void moe_phase1_plan_release_resources_locked() {
    if (!g_moe_phase1_plan.resources_allocated) {
        return;
    }
    for (int bank = 0; bank < 2; ++bank) {
        if (g_moe_phase1_plan.bank_pending[bank] &&
                g_moe_phase1_plan.bank_done[bank]) {
            cudaEventSynchronize(g_moe_phase1_plan.bank_done[bank]);
        }
        g_moe_phase1_plan.bank_pending[bank] = false;
    }
    pinned_stage_release(g_batch.stage_ring_phase1);
    for (cudaEvent_t &event : g_moe_phase1_plan.bank_done) {
        if (event) {
            cudaEventDestroy(event);
            event = nullptr;
        }
    }
    if (g_moe_phase1_plan.host_workspace) {
        cudaFreeHost(g_moe_phase1_plan.host_workspace);
        g_moe_phase1_plan.host_workspace = nullptr;
    }
    if (g_moe_phase1_plan.device) {
        cudaFree(g_moe_phase1_plan.device);
        g_moe_phase1_plan.device = nullptr;
    }
    g_moe_phase1_plan.resources_allocated = false;
}

static bool moe_phase1_plan_allocate_resources_locked() {
    if (g_moe_phase1_plan.resources_allocated) {
        return true;
    }
    size_t cuda_free_before = 0;
    size_t cuda_total = 0;
    if (cudaMemGetInfo(&cuda_free_before, &cuda_total) != cudaSuccess) {
        cudaGetLastError();
        return false;
    }
    if (cudaMalloc(
                &g_moe_phase1_plan.device,
                g_moe_phase1_plan.device_bytes) != cudaSuccess) {
        cudaGetLastError();
        return false;
    }
    if (cudaHostAlloc(
                &g_moe_phase1_plan.host_workspace,
                g_moe_phase1_plan.host_workspace_bytes,
                cudaHostAllocDefault) != cudaSuccess) {
        cudaFree(g_moe_phase1_plan.device);
        g_moe_phase1_plan.device = nullptr;
        cudaGetLastError();
        return false;
    }
    if (!pinned_stage_ensure_slots(
                g_batch.stage_ring_phase1,
                g_moe_phase1_plan.host_slot_bytes,
                true,
                16,
                true,
                false)) {
        cudaFreeHost(g_moe_phase1_plan.host_workspace);
        g_moe_phase1_plan.host_workspace = nullptr;
        cudaFree(g_moe_phase1_plan.device);
        g_moe_phase1_plan.device = nullptr;
        return false;
    }
    g_moe_phase1_plan.resources_allocated = true;
    for (cudaEvent_t &event : g_moe_phase1_plan.bank_done) {
        if (cudaEventCreateWithFlags(&event, cudaEventDisableTiming) != cudaSuccess) {
            cudaGetLastError();
            moe_phase1_plan_release_resources_locked();
            return false;
        }
    }
    g_moe_phase1_plan.cuda_free_before_bytes = cuda_free_before;
    std::fprintf(stderr,
        "[moe_prefill_phase_workspace] event=provider_allocate capacity=%u "
        "device_bytes=%zu host_workspace_bytes=%zu host_ring_bytes=%zu "
        "cuda_free_before=%zu cuda_total=%zu\n",
        g_moe_phase1_plan.capacity,
        g_moe_phase1_plan.device_bytes,
        g_moe_phase1_plan.host_workspace_bytes,
        g_moe_phase1_plan.host_slot_bytes * (size_t)16,
        cuda_free_before,
        cuda_total);
    std::fflush(stderr);
    return true;
}

// Phase 0/1 planner.  The K3 coefficients come from the measured ubatch
// workspace curve recorded in the Task 24 screen.  Phase 0 remains a dry run;
// Phase 1 turns the selected capacity into an owned workspace and a fixed
// two-bank scratch resource before llama_context::sched_reserve().
extern "C" bool ggml_cuda_moe_prefill_phase01_plan(uint32_t n_ubatch, uint32_t n_expert_used) {
    const bool phase0 = moe_phase_env_enabled("GGML_MOE_PREFILL_PHASE0");
    const bool phase1 = moe_phase_env_enabled("GGML_MOE_PREFILL_PHASE1");
    if (!phase0 && !phase1) {
        return true;
    }

    static constexpr uint32_t capacities[] = {512, 1024, 1536, 2048, 4096, 8192};
    static constexpr uint64_t device_bytes_per_route = 93848;
    static constexpr uint64_t device_fixed_bytes = 8068;
    static constexpr uint64_t host_bytes_per_route = 57344;
    static constexpr size_t phase1_scratch_slots = 16;
    const size_t phase1_expert_bytes = moe_phase_env_bytes(
        "GGML_MOE_PREFILL_PHASE1_EXPERT_BYTES", 3612672);
    const uint64_t phase1_ring_bytes =
        (uint64_t)phase1_scratch_slots * (uint64_t)phase1_expert_bytes;
    const bool full_coverage = moe_phase_env_enabled("GGML_MOE_PREFILL_FULL_COVERAGE");
    const bool phase_sized = moe_phase_env_enabled("GGML_MOE_PREFILL_PHASE_SIZED_WORKSPACE");
    const uint64_t phase1_host_slot_bytes =
        (uint64_t)phase1_expert_bytes * (full_coverage ? 2ULL : 1ULL);
    const uint64_t phase1_host_ring_bytes =
        (uint64_t)phase1_scratch_slots * phase1_host_slot_bytes;
    const uint64_t mib = 1024ULL * 1024ULL;
    const uint64_t required = (uint64_t)n_ubatch * (uint64_t)n_expert_used;
    uint32_t selected = 0;
    for (uint32_t capacity : capacities) {
        const uint64_t device_bytes = device_bytes_per_route * capacity + device_fixed_bytes;
        const uint64_t host_bytes = host_bytes_per_route * capacity;
        std::fprintf(stderr,
            "[moe_prefill_plan] capacity=%u provider_device_bytes=%llu provider_device_mib=%.3f "
            "provider_host_bytes=%llu provider_host_mib=%.3f\n",
            capacity,
            (unsigned long long)device_bytes, (double)device_bytes / (double)mib,
            (unsigned long long)host_bytes, (double)host_bytes / (double)mib);
        if (selected == 0 && required <= capacity) {
            selected = capacity;
        }
    }

    const uint64_t device_budget_mib =
        moe_phase_env_mib("GGML_MOE_PREFILL_PHASE0_DEVICE_BUDGET_MIB", 768);
    const uint64_t host_budget_mib =
        moe_phase_env_mib("GGML_MOE_PREFILL_PHASE0_HOST_BUDGET_MIB", 512);
    const uint64_t selected_workspace_device = selected ?
        device_bytes_per_route * selected + device_fixed_bytes : UINT64_MAX;
    const uint64_t selected_device = selected && selected_workspace_device <= UINT64_MAX - phase1_ring_bytes ?
        selected_workspace_device + (phase1 ? phase1_ring_bytes : 0) : UINT64_MAX;
    const uint64_t selected_workspace_host = selected ?
        host_bytes_per_route * selected : UINT64_MAX;
    const uint64_t selected_host = selected && selected_workspace_host <= UINT64_MAX - phase1_host_ring_bytes ?
        host_bytes_per_route * selected + (phase1 ? phase1_host_ring_bytes : 0) : UINT64_MAX;
    const bool shape_ok = !phase1 ||
        ((n_ubatch == 16 ||
          (phase_sized && (n_ubatch == 32 || n_ubatch == 64 || n_ubatch == 96))) &&
         n_expert_used == 16);
    const char *phase1_mode = std::getenv("GGML_MOE_PREFILL_PHASE1_MODE");
    const bool mode_ok = !phase1 || (phase1_mode &&
        (std::strcmp(phase1_mode, "observe") == 0 ||
         std::strcmp(phase1_mode, "grouped_mmvq") == 0));
    const bool budget_ok = selected != 0 &&
        selected_device <= device_budget_mib * mib &&
        selected_host <= host_budget_mib * mib;

    std::fprintf(stderr,
        "[moe_prefill_plan] decision=%s n_ubatch=%u n_expert_used=%u required_routes=%llu "
        "selected_capacity=%u device_mib=%.3f workspace_device_mib=%.3f host_mib=%.3f "
        "phase1_device_ring_mib=%.3f phase1_host_ring_mib=%.3f expert_bytes=%zu "
        "device_budget_mib=%llu host_budget_mib=%llu shape_ok=%d mode_ok=%d "
        "phase_sized=%d\n",
        shape_ok && mode_ok && budget_ok ? "accept" : "reject",
        n_ubatch, n_expert_used, (unsigned long long)required, selected,
        selected ? (double)selected_device / (double)mib : -1.0,
        selected ? (double)selected_workspace_device / (double)mib : -1.0,
        selected ? (double)selected_host / (double)mib : -1.0,
        phase1 ? (double)phase1_ring_bytes / (double)mib : 0.0,
        phase1 ? (double)phase1_host_ring_bytes / (double)mib : 0.0,
        phase1_expert_bytes,
        (unsigned long long)device_budget_mib,
        (unsigned long long)host_budget_mib,
        shape_ok ? 1 : 0,
        mode_ok ? 1 : 0,
        phase_sized ? 1 : 0);
    std::fflush(stderr);
    if (!shape_ok || !mode_ok || !budget_ok || !phase1) {
        return shape_ok && mode_ok && budget_ok;
    }

    if (g_moe_phase1_plan.planned) {
        return !g_moe_phase1_plan.leased &&
            g_moe_phase1_plan.capacity == selected &&
            g_moe_phase1_plan.expert_bytes == phase1_expert_bytes &&
            g_moe_phase1_plan.host_slot_bytes == phase1_host_slot_bytes &&
            g_moe_phase1_plan.phase_sized == phase_sized;
    }

    size_t cuda_free_before = 0;
    size_t cuda_total = 0;
    if (cudaMemGetInfo(&cuda_free_before, &cuda_total) != cudaSuccess) {
        cudaGetLastError();
        return false;
    }

    g_moe_phase1_plan.planned = true;
    g_moe_phase1_plan.phase_sized = phase_sized;
    g_moe_phase1_plan.capacity = selected;
    g_moe_phase1_plan.expert_bytes = phase1_expert_bytes;
    g_moe_phase1_plan.host_slot_bytes = (size_t)phase1_host_slot_bytes;
    g_moe_phase1_plan.device_bytes = (size_t)selected_device;
    g_moe_phase1_plan.scratch_bytes = (size_t)phase1_ring_bytes;
    g_moe_phase1_plan.workspace_bytes = (size_t)selected_workspace_device;
    g_moe_phase1_plan.host_workspace_bytes = (size_t)selected_workspace_host;
    g_moe_phase1_plan.cuda_free_before_bytes = cuda_free_before;
    if (!phase_sized && !moe_phase1_plan_allocate_resources_locked()) {
        g_moe_phase1_plan.planned = false;
        return false;
    }
    std::fprintf(stderr,
        "[moe_prefill_plan] reserved=%d capacity=%u device_bytes=%zu scratch_slots=%zu "
        "scratch_bytes=%zu workspace_bytes=%zu host_workspace_bytes=%zu host_ring_bytes=%llu "
        "cuda_free_before=%zu cuda_total=%zu\n",
        phase_sized ? 0 : 1,
        selected,
        g_moe_phase1_plan.device_bytes,
        phase1_scratch_slots,
        g_moe_phase1_plan.scratch_bytes,
        g_moe_phase1_plan.workspace_bytes,
        g_moe_phase1_plan.host_workspace_bytes,
        (unsigned long long)phase1_host_ring_bytes,
        cuda_free_before,
        cuda_total);
    std::fflush(stderr);
    return true;
}

