static std::mutex & layer_gap_stream_registry_mutex() {
    static auto * mutex = new std::mutex();
    return *mutex;
}

static std::vector<layer_gap_stream_buffer *> & layer_gap_stream_registry() {
    static auto * registry = new std::vector<layer_gap_stream_buffer *>();
    return *registry;
}

static void layer_gap_stream_copy_field(char *dst, size_t dst_size, const char *src) {
    if (dst_size == 0) {
        return;
    }
    size_t out = 0;
    for (const char *p = src ? src : ""; *p && out + 1 < dst_size; ++p) {
        const char ch = *p;
        dst[out++] = ch == ',' || ch == '\n' || ch == '\r' ? ' ' : ch;
    }
    dst[out] = '\0';
}

static void layer_gap_stream_report_atexit() {
    if (!g_layer_gap_trace_enabled) {
        return;
    }
    const std::string path = std::string(g_layer_gap_trace_prefix) + ".stream.csv";
    FILE *file = std::fopen(path.c_str(), "w");
    if (!file) {
        std::fprintf(stderr, "[kimi_layer_gap] stream trace open failed: %s\n", path.c_str());
        return;
    }
    std::fprintf(file, "start_us,end_us,layer_index,expert_id,items,component,tensor\n");
    size_t rows = 0;
    {
        std::lock_guard<std::mutex> lock(layer_gap_stream_registry_mutex());
        for (const layer_gap_stream_buffer *buffer : layer_gap_stream_registry()) {
            for (const layer_gap_stream_entry &entry : buffer->entries) {
                std::fprintf(
                    file,
                    "%lu,%lu,%d,%d,%u,%s,%s\n",
                    (unsigned long)entry.start_us,
                    (unsigned long)entry.end_us,
                    entry.layer_index,
                    entry.expert_id,
                    entry.items,
                    entry.component,
                    entry.tensor);
                ++rows;
            }
        }
    }
    std::fclose(file);
    std::fprintf(stderr, "[kimi_layer_gap] stream trace written: %s (%zu rows)\n", path.c_str(), rows);
}

static layer_gap_stream_buffer & layer_gap_stream_thread_buffer() {
    static thread_local layer_gap_stream_buffer *buffer = nullptr;
    if (!buffer) {
        std::call_once(g_layer_gap_stream_init_once, []() {
            std::atexit(layer_gap_stream_report_atexit);
            std::fprintf(
                stderr,
                "[kimi_layer_gap] stream trace enabled: prefix=%s\n",
                g_layer_gap_trace_prefix);
        });
        buffer = new layer_gap_stream_buffer();
        buffer->entries.reserve(1U << 17);
        std::lock_guard<std::mutex> lock(layer_gap_stream_registry_mutex());
        layer_gap_stream_registry().push_back(buffer);
    }
    return *buffer;
}

class layer_gap_stream_scope {
public:
    layer_gap_stream_scope(
            const char *component,
            const char *tensor,
            int expert_id,
            uint32_t items = 1) :
        enabled(g_layer_gap_trace_enabled) {
        if (!enabled) {
            return;
        }
        entry.start_us = (uint64_t)ggml_time_us();
        entry.expert_id = expert_id;
        entry.items = items;
        char parsed_kind[12] = {};
        int layer = -1;
        batch_route_detail_parse_name(tensor, layer, parsed_kind, sizeof(parsed_kind));
        entry.layer_index = layer;
        layer_gap_stream_copy_field(entry.component, sizeof(entry.component), component);
        layer_gap_stream_copy_field(entry.tensor, sizeof(entry.tensor), tensor);
    }

    ~layer_gap_stream_scope() {
        finish();
    }

    void finish() {
        if (!enabled || finished) {
            return;
        }
        entry.end_us = (uint64_t)ggml_time_us();
        layer_gap_stream_thread_buffer().entries.push_back(entry);
        finished = true;
    }

    layer_gap_stream_scope(const layer_gap_stream_scope &) = delete;
    layer_gap_stream_scope & operator=(const layer_gap_stream_scope &) = delete;

private:
    bool enabled = false;
    bool finished = false;
    layer_gap_stream_entry entry;
};









static uint64_t stage_timeline_now_us() {
    return (uint64_t)ggml_time_us();
}

static void stage_timeline_report_atexit() {
    auto collect_ring = [](pinned_stage_ring &ring) {
        for (pinned_stage_slot &slot : ring.slots) {
            if (slot.stage_trace_begin == SIZE_MAX || slot.stage_trace_count == 0) {
                continue;
            }
            if (slot.pending && slot.done) {
                cudaEventSynchronize(slot.done);
                slot.pending = false;
            }
            pinned_stage_collect_timing(ring, slot);
        }
    };
    collect_ring(g_batch.stage_ring);
    collect_ring(g_batch.stage_ring_gate);
    collect_ring(g_batch.stage_ring_up_aux);
    collect_ring(g_batch.stage_ring_gate_aux);
    collect_ring(g_batch.stage_ring_down_aux);

    const size_t claimed = g_stage_timeline.next_entry.load(std::memory_order_acquire);
    const size_t count = std::min(claimed, g_stage_timeline.entries.size());
    if (!g_stage_timeline_path || !g_stage_timeline_path[0] || count == 0) {
        return;
    }

    FILE *f = std::fopen(g_stage_timeline_path, "w");
    if (!f) {
        std::fprintf(stderr, "[moe_stream_batch] stage timeline open failed: %s\n",
                     g_stage_timeline_path);
        return;
    }

    std::fprintf(f,
            "forward_pass_index,stage_call_index,stage_job_index,read_group_index,read_group_jobs,"
            "layer_index,tensor_kind,expert_id,bytes,source_index,offset,"
            "read_offset,read_bytes,call_start_us,call_end_rel_us,submit_rel_us,complete_rel_us,"
            "h2d_enqueue_rel_us,h2d_enqueue_done_rel_us,h2d_start_rel_us,h2d_complete_rel_us,"
            "h2d_wait_start_rel_us,h2d_wait_end_rel_us,op\n");
    for (size_t i = 0; i < count; ++i) {
        const stage_timeline_entry &entry = g_stage_timeline.entries[i];
        auto relative_us = [&](uint64_t timestamp_us) -> uint64_t {
            return timestamp_us >= entry.call_start_us && timestamp_us != 0 ?
                timestamp_us - entry.call_start_us : 0;
        };
        std::fprintf(f,
                "%u,%lu,%u,%u,%u,%d,%u,%d,%u,%d,%lu,%lu,%lu,"
                "%lu,%lu,%lu,%lu,%lu,%lu,%lu,%lu,%lu,%lu,%s\n",
                entry.forward_pass_index,
                (unsigned long)entry.stage_call_index,
                entry.stage_job_index,
                entry.read_group_index,
                entry.read_group_jobs,
                entry.layer_index,
                entry.tensor_kind,
                entry.expert_id,
                entry.bytes,
                entry.source_index,
                (unsigned long)entry.offset,
                (unsigned long)entry.read_offset,
                (unsigned long)entry.read_bytes,
                (unsigned long)entry.call_start_us,
                (unsigned long)relative_us(__atomic_load_n(&entry.call_end_us, __ATOMIC_RELAXED)),
                (unsigned long)relative_us(__atomic_load_n(&entry.submit_us, __ATOMIC_RELAXED)),
                (unsigned long)relative_us(__atomic_load_n(&entry.complete_us, __ATOMIC_RELAXED)),
                (unsigned long)relative_us(__atomic_load_n(&entry.h2d_enqueue_us, __ATOMIC_RELAXED)),
                (unsigned long)relative_us(__atomic_load_n(&entry.h2d_enqueue_done_us, __ATOMIC_RELAXED)),
                (unsigned long)relative_us(__atomic_load_n(&entry.h2d_start_us, __ATOMIC_RELAXED)),
                (unsigned long)relative_us(__atomic_load_n(&entry.h2d_complete_us, __ATOMIC_RELAXED)),
                (unsigned long)relative_us(__atomic_load_n(&entry.h2d_wait_start_us, __ATOMIC_RELAXED)),
                (unsigned long)relative_us(__atomic_load_n(&entry.h2d_wait_end_us, __ATOMIC_RELAXED)),
                entry.op);
    }
    std::fclose(f);

    const size_t dropped = g_stage_timeline.dropped_entries.load(std::memory_order_relaxed);
    std::fprintf(stderr,
            "[moe_stream_batch] stage timeline written: %s (%zu events, %zu dropped)\n",
            g_stage_timeline_path, count, dropped);
}

static void stage_timeline_init_once(cudaStream_t stream) {
    std::call_once(g_stage_timeline.init_once, [stream]() {
        g_stage_timeline.entries.resize(STAGE_TIMELINE_CAPACITY);
        if (cudaEventCreate(&g_stage_timeline.gpu_origin) != cudaSuccess ||
                cudaEventRecord(g_stage_timeline.gpu_origin, stream) != cudaSuccess ||
                cudaEventSynchronize(g_stage_timeline.gpu_origin) != cudaSuccess) {
            if (g_stage_timeline.gpu_origin) {
                cudaEventDestroy(g_stage_timeline.gpu_origin);
                g_stage_timeline.gpu_origin = nullptr;
            }
        } else {
            g_stage_timeline.gpu_origin_cpu_us = stage_timeline_now_us();
        }
        std::atexit(stage_timeline_report_atexit);
        std::fprintf(stderr,
                "[moe_stream_batch] stage timeline enabled: path=%s capacity=%zu gpu_clock=%d\n",
                g_stage_timeline_path,
                g_stage_timeline.entries.size(),
                g_stage_timeline.gpu_origin ? 1 : 0);
    });
}

static size_t stage_timeline_reserve(size_t count) {
    const size_t begin = g_stage_timeline.next_entry.fetch_add(count, std::memory_order_relaxed);
    const size_t capacity = g_stage_timeline.entries.size();
    if (begin >= capacity) {
        g_stage_timeline.dropped_entries.fetch_add(count, std::memory_order_relaxed);
        return SIZE_MAX;
    }
    if (count > capacity - begin) {
        g_stage_timeline.dropped_entries.fetch_add(count - (capacity - begin), std::memory_order_relaxed);
    }
    return begin;
}

static size_t stage_timeline_available(size_t begin, size_t requested) {
    if (begin == SIZE_MAX || begin >= g_stage_timeline.entries.size()) {
        return 0;
    }
    return std::min(requested, g_stage_timeline.entries.size() - begin);
}

static void stage_timeline_mark_submit(size_t begin, size_t count, uint64_t timestamp_us) {
    const size_t available = stage_timeline_available(begin, count);
    for (size_t i = 0; i < available; ++i) {
        uint64_t expected = 0;
        __atomic_compare_exchange_n(
                &g_stage_timeline.entries[begin + i].submit_us,
                &expected,
                timestamp_us,
                false,
                __ATOMIC_RELAXED,
                __ATOMIC_RELAXED);
    }
}

static void stage_timeline_mark_complete(size_t begin, size_t count, uint64_t timestamp_us) {
    const size_t available = stage_timeline_available(begin, count);
    for (size_t i = 0; i < available; ++i) {
        __atomic_store_n(
                &g_stage_timeline.entries[begin + i].complete_us,
                timestamp_us,
                __ATOMIC_RELAXED);
    }
}

static void stage_timeline_mark_call_end(size_t begin, size_t count, uint64_t timestamp_us) {
    const size_t available = stage_timeline_available(begin, count);
    for (size_t i = 0; i < available; ++i) {
        __atomic_store_n(
                &g_stage_timeline.entries[begin + i].call_end_us,
                timestamp_us,
                __ATOMIC_RELAXED);
    }
}

static void stage_timeline_mark_h2d_wait(
        size_t begin,
        size_t count,
        uint64_t start_us,
        uint64_t end_us) {
    const size_t available = stage_timeline_available(begin, count);
    for (size_t i = 0; i < available; ++i) {
        __atomic_store_n(
                &g_stage_timeline.entries[begin + i].h2d_wait_start_us,
                start_us,
                __ATOMIC_RELAXED);
        __atomic_store_n(
                &g_stage_timeline.entries[begin + i].h2d_wait_end_us,
                end_us,
                __ATOMIC_RELAXED);
    }
}

static void stage_timeline_collect_h2d(
        size_t begin,
        size_t count,
        cudaEvent_t start,
        cudaEvent_t complete) {
    if (!g_stage_timeline.gpu_origin || !start || !complete) {
        return;
    }
    float start_ms = 0.0f;
    float complete_ms = 0.0f;
    if (cudaEventElapsedTime(&start_ms, g_stage_timeline.gpu_origin, start) != cudaSuccess ||
            cudaEventElapsedTime(&complete_ms, g_stage_timeline.gpu_origin, complete) != cudaSuccess) {
        return;
    }

    const uint64_t start_us =
        g_stage_timeline.gpu_origin_cpu_us +
        (uint64_t)std::llround((double)start_ms * 1000.0);
    const uint64_t complete_us =
        g_stage_timeline.gpu_origin_cpu_us +
        (uint64_t)std::llround((double)complete_ms * 1000.0);
    const size_t available = stage_timeline_available(begin, count);
    for (size_t i = 0; i < available; ++i) {
        __atomic_store_n(
                &g_stage_timeline.entries[begin + i].h2d_start_us,
                start_us,
                __ATOMIC_RELAXED);
        __atomic_store_n(
                &g_stage_timeline.entries[begin + i].h2d_complete_us,
                complete_us,
                __ATOMIC_RELAXED);
    }
}







static int trace_prefetch_env_int(const char *name, int fallback, int lo, int hi) {
    const char *env = std::getenv(name);
    long value = (env && env[0]) ? std::atol(env) : fallback;
    if (value < lo) value = lo;
    if (value > hi) value = hi;
    return (int)value;
}

static char trace_prefetch_role_from_tensor(const char *tensor) {
    if (!tensor) return 'o';
    if (std::strstr(tensor, ".ffn_gate_exps.")) return 'g';
    if (std::strstr(tensor, ".ffn_up_exps.")) return 'u';
    if (std::strstr(tensor, ".ffn_down_exps.")) return 'd';
    return 'o';
}

static bool trace_prefetch_target_allows(const char *tensor) {
    if (!g_trace_prefetch.targets[0]) return true;
    const char role = trace_prefetch_role_from_tensor(tensor);
    for (const char *p = g_trace_prefetch.targets; *p; ++p) {
        if (*p == role) return true;
    }
    return false;
}

static void trim_csv_field_tail(char *s) {
    if (!s) return;
    size_t n = std::strlen(s);
    while (n > 0 && (s[n - 1] == '\r' || s[n - 1] == '\n')) {
        s[--n] = '\0';
    }
}

static bool load_route_trace_csv(const char *path, std::vector<batch_route_trace_entry> &trace, const char *label) {
    if (!path || !path[0]) return false;
    FILE *f = std::fopen(path, "r");
    if (!f) {
        std::fprintf(stderr, "[moe_stream_batch] %s: open failed: %s\n", label, path);
        return false;
    }
    char line[512];
    if (std::fgets(line, sizeof(line), f)) {
        while (std::fgets(line, sizeof(line), f)) {
            batch_route_trace_entry e;
            unsigned long long seq = 0;
            unsigned long long tensor_base = 0;
            if (std::sscanf(line, "%llu,%zu,0x%llx,%d,%127[^\n]",
                        &seq, &e.expert_bytes, &tensor_base, &e.expert_idx, e.tensor) == 5 &&
                    e.expert_idx >= 0 && e.expert_bytes > 0 && e.tensor[0]) {
                trim_csv_field_tail(e.tensor);
                e.seq = (uint64_t)seq;
                trace.push_back(e);
            }
        }
    }
    std::fclose(f);
    return !trace.empty();
}

static void trace_prefetch_report_atexit() {
    std::lock_guard<std::mutex> lk(g_trace_prefetch.mu);
    if (!g_trace_prefetch.enabled || g_trace_prefetch.calls == 0) return;
    std::fprintf(stderr,
        "[moe_stream_batch] trace prefetch: calls=%lu matched=%lu resync=%lu loads=%lu cached=%lu missing_tensor=%lu cache_unavailable=%lu reuse_skips=%lu cursor=%zu prefetch_cursor=%zu/%zu\n",
        g_trace_prefetch.calls,
        g_trace_prefetch.matched,
        g_trace_prefetch.resync,
        g_trace_prefetch.loads,
        g_trace_prefetch.cached,
        g_trace_prefetch.missing_tensor,
        g_trace_prefetch.cache_unavailable,
        g_trace_prefetch.reuse_skips,
        g_trace_prefetch.cursor,
        g_trace_prefetch.prefetch_cursor,
        g_trace_prefetch.trace.size());
}

static void trace_prefetch_init_once() {
    if (g_trace_prefetch.inited) return;
    std::lock_guard<std::mutex> lk(g_trace_prefetch.mu);
    if (g_trace_prefetch.inited) return;

    const char *path = std::getenv("GGML_MOE_TRACE_PREFETCH");
    if (!path || !path[0]) {
        g_trace_prefetch.inited = true;
        return;
    }

    load_route_trace_csv(path, g_trace_prefetch.trace, "trace prefetch");

    g_trace_prefetch.window = (size_t)trace_prefetch_env_int("GGML_MOE_TRACE_PREFETCH_WINDOW", 96, 1, 4096);
    g_trace_prefetch.max_loads = trace_prefetch_env_int("GGML_MOE_TRACE_PREFETCH_MAX_LOADS", 8, 1, 256);
    g_trace_prefetch.lead_events = (size_t)trace_prefetch_env_int("GGML_MOE_TRACE_PREFETCH_LEAD_EVENTS", 0, 0, 4096);
    g_trace_prefetch.min_future_uses = trace_prefetch_env_int("GGML_MOE_TRACE_PREFETCH_MIN_FUTURE_USES", 1, 1, 64);
    g_trace_prefetch.reuse_window = (size_t)trace_prefetch_env_int(
            "GGML_MOE_TRACE_PREFETCH_REUSE_WINDOW", (int)g_trace_prefetch.window, 1, 4096);
    const char *targets_env = std::getenv("GGML_MOE_TRACE_PREFETCH_TARGETS");
    if (targets_env && targets_env[0]) {
        size_t out = 0;
        for (const char *p = targets_env; *p && out + 1 < sizeof(g_trace_prefetch.targets); ++p) {
            if (*p == 'g' || *p == 'G') {
                g_trace_prefetch.targets[out++] = 'g';
            } else if (*p == 'u' || *p == 'U') {
                g_trace_prefetch.targets[out++] = 'u';
            } else if (*p == 'd' || *p == 'D') {
                g_trace_prefetch.targets[out++] = 'd';
            } else if (std::strncmp(p, "gate", 4) == 0) {
                g_trace_prefetch.targets[out++] = 'g';
                p += 3;
            } else if (std::strncmp(p, "up", 2) == 0) {
                g_trace_prefetch.targets[out++] = 'u';
                p += 1;
            } else if (std::strncmp(p, "down", 4) == 0) {
                g_trace_prefetch.targets[out++] = 'd';
                p += 3;
            }
        }
        g_trace_prefetch.targets[out] = '\0';
    }
    g_trace_prefetch.enabled = !g_trace_prefetch.trace.empty();
    g_trace_prefetch.inited = true;
    if (g_trace_prefetch.enabled) {
        std::atexit(trace_prefetch_report_atexit);
        std::fprintf(stderr,
            "[moe_stream_batch] trace prefetch: loaded %zu events from %s window=%zu max_loads=%d lead_events=%zu min_future_uses=%d reuse_window=%zu\n",
            g_trace_prefetch.trace.size(), path, g_trace_prefetch.window, g_trace_prefetch.max_loads,
            g_trace_prefetch.lead_events, g_trace_prefetch.min_future_uses, g_trace_prefetch.reuse_window);
        if (g_trace_prefetch.targets[0]) {
            std::fprintf(stderr, "[moe_stream_batch] trace prefetch: target roles=%s\n", g_trace_prefetch.targets);
        }
    }
}

static void trace_prefetch_on_hit(const char *tensor_name, int expert_idx, size_t expert_bytes);
static void host_prefetch_on_route(const char *tensor_name, int expert_idx, size_t expert_bytes);

static void batch_ttft_trace_report_atexit() {
    std::vector<batch_ttft_trace_entry> rows;
    {
        std::lock_guard<std::mutex> lk(g_ttft_trace_mu);
        rows = g_ttft_trace;
    }
    if (!g_ttft_trace_out || !g_ttft_trace_out[0] || rows.empty()) return;

    FILE *f = std::fopen(g_ttft_trace_out, "w");
    if (!f) {
        std::fprintf(stderr, "[moe_stream_batch] TTFT trace: open failed: %s\n", g_ttft_trace_out);
        return;
    }
    std::fprintf(f, "seq,t_ms,op,tensor,expert_idx,expert_bytes,cache_hit,pack_hit,ram_hit,copy_ms\n");
    for (const batch_ttft_trace_entry &e : rows) {
        std::fprintf(f, "%lu,%.3f,%s,%s,%d,%zu,%d,%d,%d,%.3f\n",
                     e.seq, e.t_ms, e.op, e.tensor, e.expert_idx, e.expert_bytes,
                     e.cache_hit, e.pack_hit, e.ram_hit, e.copy_ms);
    }
    std::fclose(f);
    std::fprintf(stderr, "[moe_stream_batch] TTFT trace written: %s (%zu events)\n",
                 g_ttft_trace_out, rows.size());
}

static bool batch_ttft_trace_enabled() {
    if (g_ttft_trace_inited.load(std::memory_order_acquire)) return g_ttft_trace_out && g_ttft_trace_out[0];
    std::lock_guard<std::mutex> lk(g_ttft_trace_mu);
    if (g_ttft_trace_inited.load(std::memory_order_acquire)) return g_ttft_trace_out && g_ttft_trace_out[0];
    g_ttft_trace_out = std::getenv("GGML_MOE_TTFT_TRACE_OUT");
    const char *cap_env = std::getenv("GGML_MOE_TTFT_TRACE_MAX_EVENTS");
    if (cap_env && cap_env[0]) {
        const long cap = std::atol(cap_env);
        if (cap > 0) g_ttft_trace_cap = (size_t)cap;
    }
    if (g_ttft_trace_out && g_ttft_trace_out[0]) {
        g_ttft_trace_start = std::chrono::steady_clock::now();
        std::atexit(batch_ttft_trace_report_atexit);
    }
    g_ttft_trace_inited.store(true, std::memory_order_release);
    return g_ttft_trace_out && g_ttft_trace_out[0];
}

static void batch_ttft_trace_record(
        const char *op,
        const char *tensor_name,
        int expert_idx,
        size_t expert_bytes,
        bool cache_hit,
        bool pack_hit,
        bool ram_hit,
        double copy_ms) {
    if (!batch_ttft_trace_enabled()) return;
    const auto now = std::chrono::steady_clock::now();
    std::lock_guard<std::mutex> lk(g_ttft_trace_mu);
    const bool is_marker = op && std::strncmp(op, "mark_", 5) == 0;
    if (!is_marker && g_ttft_trace.size() >= g_ttft_trace_cap) return;

    batch_ttft_trace_entry e;
    e.seq = ++g_ttft_trace_seq;
    e.t_ms = std::chrono::duration<double, std::milli>(now - g_ttft_trace_start).count();
    e.copy_ms = copy_ms;
    e.expert_idx = expert_idx;
    e.cache_hit = cache_hit ? 1 : 0;
    e.pack_hit = pack_hit ? 1 : 0;
    e.ram_hit = ram_hit ? 1 : 0;
    e.expert_bytes = expert_bytes;
    std::snprintf(e.op, sizeof(e.op), "%s", op ? op : "");
    std::snprintf(e.tensor, sizeof(e.tensor), "%s", tensor_name ? tensor_name : "");
    g_ttft_trace.push_back(e);
}

extern "C" void ggml_cuda_moe_ttft_trace_mark(const char *label) {
    if (ggml_moe::adapter_uses_common()) {
        ggml_cuda_moe_common_ttft_trace_mark(label);
        return;
    }
    char op[24] = {};
    std::snprintf(op, sizeof(op), "mark_%s", label ? label : "");
    batch_ttft_trace_record(op, "", -1, 0, false, false, false, 0.0);
}

extern "C" void ggml_cuda_moe_ttft_trace_event(
        const char *op,
        const char *tensor_name,
        int marker_value,
        size_t expert_bytes,
        double elapsed_ms) {
    if (ggml_moe::adapter_uses_common()) {
        ggml_cuda_moe_common_ttft_trace_event(
            op, tensor_name, marker_value, expert_bytes, elapsed_ms);
        return;
    }
    batch_ttft_trace_record(op, tensor_name, marker_value, expert_bytes, false, false, false, elapsed_ms);
}

struct batch_ttft_call_scope {
    const char *op = nullptr;
    const char *tensor = nullptr;
    int n_active = 0;
    size_t expert_bytes = 0;
    bool enabled = false;
    std::chrono::steady_clock::time_point start;

    batch_ttft_call_scope(const char *op_, const char *tensor_, int n_active_, size_t expert_bytes_)
        : op(op_), tensor(tensor_), n_active(n_active_), expert_bytes(expert_bytes_),
          enabled(batch_ttft_trace_enabled()),
          start(enabled ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{}) {
    }

    ~batch_ttft_call_scope() {
        if (!enabled) return;
        const auto end = std::chrono::steady_clock::now();
        batch_ttft_trace_record(
            op,
            tensor,
            n_active,
            expert_bytes,
            false,
            false,
            false,
            std::chrono::duration<double, std::milli>(end - start).count());
    }
};

static void batch_route_profile_hit(const char *tensor_name, int expert_idx, size_t expert_bytes) {
    batch_route_profile_init_once();
    if (!tensor_name || !tensor_name[0]) return;
    trace_prefetch_on_hit(tensor_name, expert_idx, expert_bytes);
    host_prefetch_on_route(tensor_name, expert_idx, expert_bytes);
    const bool profile_enabled = g_route_profile_out && g_route_profile_out[0];
    const bool trace_enabled = g_route_trace_out && g_route_trace_out[0];
    if (!profile_enabled && !trace_enabled) return;

    std::lock_guard<std::mutex> lk(g_route_profile_mu);
    if (profile_enabled) {
        bool found = false;
        for (batch_route_profile_entry &e : g_route_profile) {
            if (e.expert_idx == expert_idx && std::strcmp(e.tensor, tensor_name) == 0) {
                ++e.count;
                found = true;
                break;
            }
        }
        if (!found) {
            batch_route_profile_entry e;
            e.expert_idx = expert_idx;
            e.count = 1;
            e.expert_bytes = expert_bytes;
            std::snprintf(e.tensor, sizeof(e.tensor), "%s", tensor_name);
            g_route_profile.push_back(e);
        }
    }
    if (trace_enabled) {
        batch_route_trace_entry e;
        e.seq = ++g_route_trace_seq;
        e.expert_idx = expert_idx;
        e.expert_bytes = expert_bytes;
        std::snprintf(e.tensor, sizeof(e.tensor), "%s", tensor_name);
        g_route_trace.push_back(e);
    }
}

static void batch_cache_report_atexit() {
    uint64_t hits = 0;
    uint64_t misses = 0;
    uint64_t preloads = 0;
    uint64_t pinned = 0;
    uint64_t down_prefetch_loads = 0;
    uint64_t down_prefetch_hits = 0;
    uint64_t down_prefetch_evicted = 0;
    uint64_t async_prefetch_waits = 0;
    for (batch_vram_cache &c : g_bcaches) {
        hits += c.hits;
        misses += c.misses;
        preloads += c.preloads;
        pinned += c.pinned;
        down_prefetch_loads += c.down_prefetch_loads;
        down_prefetch_hits += c.down_prefetch_hits;
        down_prefetch_evicted += c.down_prefetch_evicted;
        async_prefetch_waits += c.async_prefetch_waits;
    }
    const uint64_t total = hits + misses;
    if (total == 0) return;
    if (pinned > 0) {
        std::fprintf(stderr, "[moe_stream_batch] VRAM cache: hits=%lu misses=%lu preloads=%lu pinned=%lu hit_rate=%.1f%%\n",
                     hits, misses, preloads, pinned, 100.0 * hits / total);
    } else {
        std::fprintf(stderr, "[moe_stream_batch] VRAM cache: hits=%lu misses=%lu preloads=%lu hit_rate=%.1f%%\n",
                     hits, misses, preloads, 100.0 * hits / total);
    }
    for (int ic = 0; ic < 2; ++ic) {
        const batch_vram_cache &c = g_bcaches[ic];
        const uint64_t c_total = c.hits + c.misses;
        if (c_total == 0) continue;
        const char *label = ic == 1 ? "upgate" : "down";
        std::fprintf(stderr,
            "[moe_stream_batch] VRAM cache %s: slots=%d slot=%.2f MiB "
            "hits=%lu misses=%lu preloads=%lu pinned=%lu hit_rate=%.1f%%\n",
            label, c.n_slots, c.slot_sz / (1024.0 * 1024.0),
            c.hits, c.misses, c.preloads, c.pinned, 100.0 * c.hits / c_total);
    }
    if (down_prefetch_loads > 0) {
        std::fprintf(stderr, "[moe_stream_batch] down prefetch: loads=%lu hits=%lu evicted_unused=%lu useful_rate=%.1f%%\n",
                     down_prefetch_loads, down_prefetch_hits, down_prefetch_evicted,
                     100.0 * down_prefetch_hits / down_prefetch_loads);
    }
    if (async_prefetch_waits > 0) {
        std::fprintf(stderr, "[moe_stream_batch] async prefetch waits=%lu\n", async_prefetch_waits);
    }
}

static bool profile_protect_enabled() {
    const char *env = std::getenv("GGML_MOE_VRAM_PROFILE_PROTECT");
    return env && env[0] && env[0] != '0';
}

static void profile_pinned_key_record(uint64_t key) {
    if (key == 0) return;
    std::lock_guard<std::mutex> lk(g_profile_pinned_mu);
    g_profile_pinned_keys.insert(key);
}

static bool profile_pinned_key_contains(uint64_t key) {
    if (key == 0) return false;
    std::lock_guard<std::mutex> lk(g_profile_pinned_mu);
    return g_profile_pinned_keys.find(key) != g_profile_pinned_keys.end();
}

static size_t profile_reserve_slots(const batch_vram_cache *c) {
    if (!c || c->n_slots <= 1) return 0;

    const char *slots_env = std::getenv("GGML_MOE_VRAM_PROFILE_RESERVE_SLOTS");
    if (slots_env && slots_env[0]) {
        long reserve = std::atol(slots_env);
        if (reserve < 0) reserve = 0;
        if (reserve >= c->n_slots) reserve = c->n_slots - 1;
        return (size_t)reserve;
    }

    const char *pct_env = std::getenv("GGML_MOE_VRAM_PROFILE_RESERVE_PCT");
    long pct = (pct_env && pct_env[0]) ? std::atol(pct_env) : 20;
    if (pct < 0) pct = 0;
    if (pct > 95) pct = 95;

    size_t reserve = ((size_t)c->n_slots * (size_t)pct + 99) / 100;
    if (reserve >= (size_t)c->n_slots) reserve = (size_t)c->n_slots - 1;
    return reserve;
}

static size_t profile_preload_slot_budget(const batch_vram_cache *c) {
    if (!c || c->n_slots <= 0) return 0;
    if (!profile_protect_enabled()) return (size_t)c->n_slots;
    const size_t reserve = profile_reserve_slots(c);
    return (size_t)c->n_slots > reserve ? (size_t)c->n_slots - reserve : 1;
}

static size_t prompt_profile_preload_scan_budget(const batch_vram_cache *c) {
    const char *env = std::getenv("GGML_MOE_VRAM_PROFILE_PROMPT_MAX_ENTRIES");
    if (env && env[0]) {
        long max_entries = std::atol(env);
        if (max_entries > 0) return (size_t)max_entries;
    }
    return profile_preload_slot_budget(c);
}

