    const char *env = std::getenv("GGML_MOE_VRAM_PROFILE_PRELOAD_EVICT");
    return env && env[0] && env[0] != '0';
}

static bool profile_preload_enabled() {
    const char *env = std::getenv("GGML_MOE_VRAM_PROFILE_PRELOAD");
    return !env || !env[0] || env[0] != '0';
}

static bool profile_protect_profile_only_enabled() {
    const char *env = std::getenv("GGML_MOE_VRAM_PROFILE_PROTECT_PROFILE_ONLY");
    return env && env[0] && env[0] != '0';
}

static bool profile_pin_on_insert_enabled() {
    const char *env = std::getenv("GGML_MOE_VRAM_PROFILE_PIN_ON_INSERT");
    return env && env[0] && env[0] != '0';
}

static uint32_t profile_pin_min_count() {
    const char *env = std::getenv("GGML_MOE_VRAM_PROFILE_PIN_MIN_COUNT");
    if (!env || !env[0]) return 1;
    const unsigned long value = std::strtoul(env, nullptr, 10);
    return value > UINT32_MAX ? UINT32_MAX : (uint32_t)value;
}

static uint64_t batch_key_hash(const char *name, int expert_idx) {
    uint64_t h = 1469598103934665603ULL;
    if (name) {
        for (const unsigned char *p = (const unsigned char *)name; *p; ++p) {
            h ^= (uint64_t)*p;
            h *= 1099511628211ULL;
        }
    }
    h ^= (uint64_t)(uint32_t)expert_idx + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
    return h ? h : 1;
}

static void profile_lookup_name(const char *name, char *out, size_t out_sz) {
    if (!name || out_sz == 0) return;
    std::snprintf(out, out_sz, "%s", name);
    char *p = std::strstr(out, ".ffn_up_exps.");
    if (!p) p = std::strstr(out, ".ffn_gate_exps.");
    if (p) {
        char tail[96];
        std::snprintf(tail, sizeof(tail), "%s", p + std::strlen(".ffn_up_exps."));
        if (std::strstr(p, ".ffn_gate_exps.")) {
            std::snprintf(tail, sizeof(tail), "%s", p + std::strlen(".ffn_gate_exps."));
        }
        *p = '\0';
        std::snprintf(out + std::strlen(out), out_sz - std::strlen(out), ".ffn_down_exps.%s", tail);
    }
}

static bool tensor_already_preloaded(const char *name) {
    if (!name || !name[0]) return true;
    for (int i = 0; i < g_n_preloaded_tensors; ++i) {
        if (std::strcmp(g_preloaded_tensors[i], name) == 0) return true;
    }
    static bool max_inited = false;
    static long max_tensors = 0;
    if (!max_inited) {
        const char *max_env = std::getenv("GGML_MOE_VRAM_PROFILE_PRELOAD_MAX_TENSORS");
        max_tensors = (max_env && max_env[0]) ? std::atol(max_env) : 0;
        max_inited = true;
    }
    if (max_tensors > 0 && g_n_preloaded_tensors >= max_tensors) return true;
    if (g_n_preloaded_tensors < (int)(sizeof(g_preloaded_tensors) / sizeof(g_preloaded_tensors[0]))) {
        std::snprintf(g_preloaded_tensors[g_n_preloaded_tensors++], sizeof(g_preloaded_tensors[0]), "%s", name);
    }
    return false;
}

static bool profile_has_tensor_locked(const std::vector<profile_entry> &entries, const char *name) {
    if (!name || !name[0]) return false;
    for (const profile_entry &e : entries) {
        if (std::strcmp(e.tensor, name) == 0) return true;
    }
    return false;
}

static bool load_profile_file(const char *path, std::vector<profile_entry> &entries, const char *label) {
    if (!path || !path[0]) {
        return false;
    }
    FILE *f = std::fopen(path, "r");
    if (!f) {
        std::fprintf(stderr, "[moe_stream_batch] %s preload: open failed: %s\n", label, path);
        return false;
    }
    char line[512];
    if (!std::fgets(line, sizeof(line), f)) {
        std::fclose(f);
        return false;
    }
    while (std::fgets(line, sizeof(line), f)) {
        profile_entry e;
        unsigned long long rank = 0, count = 0, cumulative = 0, tensor_base = 0;
        size_t expert_bytes = 0;
        if (std::sscanf(line, "%llu,%llu,%zu,%llu,0x%llx,%d,%127[^\n]",
                    &rank, &count, &expert_bytes, &cumulative, &tensor_base, &e.expert_idx, e.tensor) == 7 &&
                e.expert_idx >= 0 && e.tensor[0]) {
            trim_csv_field_tail(e.tensor);
            e.count = (uint64_t)count;
            e.expert_bytes = expert_bytes;
            entries.push_back(e);
        }
    }
    std::fclose(f);
    if (!entries.empty()) {
        std::fprintf(stderr, "[moe_stream_batch] %s preload: loaded %zu entries from %s\n",
                     label, entries.size(), path);
    }
    return !entries.empty();
}

static void rebuild_profile_count_index_locked() {
    g_profile_counts.clear();
    for (const profile_entry &e : g_profile) {
        const uint64_t count = e.count > UINT32_MAX ? UINT32_MAX : e.count;
        g_profile_counts[batch_key_hash(e.tensor, e.expert_idx)] = (uint32_t)count;
    }
}

static uint32_t profile_count_for_key(uintptr_t key) {
    std::lock_guard<std::mutex> lk(g_profile_mu);
    ++g_cache_policy_diag.profile_count_lookups;
    const auto it = g_profile_counts.find((uint64_t)key);
    if (it == g_profile_counts.end()) return 0;
    ++g_cache_policy_diag.profile_count_hits;
    return it->second;
}

static void load_profile_once() {
    if (g_profile_loaded) return;
    std::lock_guard<std::mutex> lk(g_profile_mu);
    if (g_profile_loaded) return;
    const char *path = std::getenv("GGML_MOE_VRAM_PROFILE");
    g_profile_enabled = load_profile_file(path, g_profile, "profile");
    if (g_profile_enabled) {
        rebuild_profile_count_index_locked();
    }
    g_profile_loaded = true;
}

static void load_prompt_profile_once() {
    if (g_prompt_profile_loaded) return;
    std::lock_guard<std::mutex> lk(g_profile_mu);
    if (g_prompt_profile_loaded) return;
    const char *path = std::getenv("GGML_MOE_VRAM_PROFILE_PROMPT");
    g_prompt_profile_enabled = load_profile_file(path, g_prompt_profile, "prompt profile");
    g_prompt_profile_loaded = true;
}

static int batch_cache_id_for_size(size_t expert_sz) {
    const char *fused_env = std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE");
    const char *split_env = std::getenv("GGML_MOE_VRAM_CACHE_SPLIT");
    const char *split_max_env = std::getenv("GGML_MOE_VRAM_CACHE_SPLIT_MAX_MIB");
    size_t split_max_mib = 4;
    if (split_max_env && split_max_env[0]) {
        split_max_mib = (size_t)std::strtoull(split_max_env, nullptr, 10);
        if (split_max_mib < 1) split_max_mib = 1;
        if (split_max_mib > 64) split_max_mib = 64;
    }
    if (fused_env && fused_env[0] && fused_env[0] != '0' &&
            split_env && split_env[0] && split_env[0] != '0' &&
            expert_sz <= split_max_mib*1024ULL*1024ULL) {
        return 1;
    }
    if (fused_env && fused_env[0] && fused_env[0] != '0' && expert_sz <= 2ULL*1024ULL*1024ULL) {
        return 1;
    }
    return 0;
}

static bool batch_cache_role_split_enabled() {
    const char *env = std::getenv("GGML_MOE_VRAM_CACHE_ROLE_SPLIT");
    return env && env[0] && env[0] != '0';
}

static int batch_cache_id_for_tensor(const char *tensor_name, size_t expert_sz) {
    if (hard1_whole_expert_cache_requested()) {
        // All three roles must share one allocation so an expert occupies
        // three adjacent role-sized slots.
        return 0;
    }
    if (batch_cache_role_split_enabled() && tensor_name && tensor_name[0]) {
        if (std::strstr(tensor_name, ".ffn_down_exps.")) {
            return 0;
        }
        if (std::strstr(tensor_name, ".ffn_up_exps.") ||
                std::strstr(tensor_name, ".ffn_gate_exps.")) {
            return 1;
        }
    }
    return batch_cache_id_for_size(expert_sz);
}

static size_t batch_cache_budget_mib_for_id(size_t budget_mib, int cid) {
    if (hard1_whole_expert_cache_requested()) {
        return cid == 0 ? budget_mib : 0;
    }
    const char *fused_env = std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE");
    const bool fused = fused_env && fused_env[0] && fused_env[0] != '0';
    const char *split_env = std::getenv("GGML_MOE_VRAM_CACHE_SPLIT");
    const bool split = batch_cache_role_split_enabled() ||
        (fused && split_env && split_env[0] && split_env[0] != '0');

    if (split) {
        const char *upgate_mib_env = std::getenv("GGML_MOE_VRAM_CACHE_UPGATE_MIB");
        if (upgate_mib_env && upgate_mib_env[0]) {
            size_t upgate_mib = (size_t)std::strtoull(upgate_mib_env, nullptr, 10);
            if (upgate_mib >= budget_mib) upgate_mib = budget_mib > 1 ? budget_mib - 1 : 1;
            if (cid == 1) return upgate_mib > 0 ? upgate_mib : 1;
            return budget_mib > upgate_mib ? budget_mib - upgate_mib : 1;
        }
        const char *pct_env = std::getenv("GGML_MOE_VRAM_CACHE_UPGATE_PCT");
        long upgate_pct = (pct_env && pct_env[0]) ? std::atol(pct_env) : 63;
        if (upgate_pct < 1) upgate_pct = 1;
        if (upgate_pct > 99) upgate_pct = 99;
        const size_t upgate_mib = (budget_mib * (size_t)upgate_pct) / 100ULL;
        if (cid == 1) return upgate_mib > 0 ? upgate_mib : 1;
        return budget_mib > upgate_mib ? budget_mib - upgate_mib : 1;
    }

    if (fused && budget_mib > 8192 && cid == 1) {
        return 8192;
    }
    return budget_mib;
}

static int kimi_dense_prefetch_upgate_reserve_slots() {
    static const int slots = []() {
        const char * layers = std::getenv("GGML_KIMI_DENSE_PREFETCH_LAYERS");
        const char * env = std::getenv("GGML_KIMI_DENSE_PREFETCH_CACHE_UPGATE_SLOTS");
        if (layers == nullptr || layers[0] == '\0' || env == nullptr || env[0] == '\0') {
            return 0;
        }
        char * end = nullptr;
        errno = 0;
        const long value = std::strtol(env, &end, 10);
        if (errno != 0 || end == env || *end != '\0' || value < 0 || value > 100) {
            std::fprintf(stderr,
                "[moe_stream_batch] ignoring invalid "
                "GGML_KIMI_DENSE_PREFETCH_CACHE_UPGATE_SLOTS=%s (expected 0..100)\n",
                env);
            return 0;
        }
        return (int) value;
    }();
    return slots;
}

static size_t env_mib_or_default(const char *name, size_t fallback) {
    const char *env = std::getenv(name);
    if (!env || !env[0]) return fallback;
    return (size_t)std::strtoull(env, nullptr, 10);
}

static size_t batch_cache_effective_budget_mib(size_t requested_mib) {
    static bool inited = false;
    static size_t effective_mib = 0;
    if (inited) return effective_mib;

    effective_mib = requested_mib;
    size_t free_bytes = 0;
    size_t total_bytes = 0;
    const cudaError_t info_err = cudaMemGetInfo(&free_bytes, &total_bytes);
    if (info_err != cudaSuccess) {
        std::fprintf(stderr,
            "[moe_stream_batch] VRAM cache budget: requested=%zu MiB actual=%zu MiB cudaMemGetInfo failed: %s\n",
            requested_mib, effective_mib, cudaGetErrorString(info_err));
        cudaGetLastError();
        inited = true;
        return effective_mib;
    }

    const size_t free_mib = free_bytes / (1024ULL * 1024ULL);
    const size_t total_mib = total_bytes / (1024ULL * 1024ULL);
    size_t sizing_free_mib = free_mib;
    size_t phase1_decode_graph_mib = 0;
    if (g_moe_phase1_plan.planned && g_moe_phase1_plan.cuda_free_before_bytes > 0) {
        phase1_decode_graph_mib = env_mib_or_default(
            "GGML_MOE_PREFILL_PHASE1_DECODE_GRAPH_MIB", 46);
        const size_t free_before_mib =
            g_moe_phase1_plan.cuda_free_before_bytes / (1024ULL * 1024ULL);
        const size_t decode_free_mib = free_before_mib > phase1_decode_graph_mib ?
            free_before_mib - phase1_decode_graph_mib : 0;
        if (decode_free_mib > sizing_free_mib) {
            sizing_free_mib = decode_free_mib;
        }
    }
    const size_t graph_reserve_mib = env_mib_or_default("GGML_MOE_VRAM_CACHE_GRAPH_RESERVE_MIB", 0);
    const size_t safety_mib = env_mib_or_default("GGML_MOE_VRAM_CACHE_SAFETY_MIB", graph_reserve_mib > 0 ? 128 : 0);
    const char *clamp_env = std::getenv("GGML_MOE_VRAM_CACHE_AUTO_CLAMP");
    const bool clamp = (clamp_env && clamp_env[0] && clamp_env[0] != '0') || graph_reserve_mib > 0;

    if (clamp) {
        const size_t reserved_mib = graph_reserve_mib + safety_mib;
        const size_t max_cache_mib = sizing_free_mib > reserved_mib ? sizing_free_mib - reserved_mib : 0;
        if (effective_mib > max_cache_mib) {
            effective_mib = max_cache_mib;
        }
    }

    std::fprintf(stderr,
        "[moe_stream_batch] VRAM cache budget: requested=%zu MiB actual=%zu MiB free=%zu MiB sizing_free=%zu MiB "
        "total=%zu MiB graph_reserve=%zu MiB safety=%zu MiB phase1_decode_graph=%zu MiB clamp=%d\n",
        requested_mib, effective_mib, free_mib, sizing_free_mib, total_mib,
        graph_reserve_mib, safety_mib, phase1_decode_graph_mib, clamp ? 1 : 0);
    inited = true;
    return effective_mib;
}

static batch_vram_cache * batch_cache_get_for_id(size_t expert_sz, int cid) {
    if (g_bcache_inited[cid]) {
        batch_vram_cache *c = &g_bcaches[cid];
        if (c->pool && expert_sz <= c->slot_sz) return c;
        if (!c->pool || expert_sz <= c->slot_sz) return nullptr;

        cudaFree(c->pool);
        c->pool = nullptr;
        c->slot_sz = 0;
        c->n_slots = 0;
        c->key_to_slot.clear();
        std::fill_n(c->slot_key, 16384, (uintptr_t)0);
        std::fill_n(c->slot_used, 16384, (uint64_t)0);
        std::fill_n(c->slot_hits, 16384, (uint32_t)0);
        std::fill_n(c->slot_profile_count, 16384, (uint32_t)0);
        std::fill_n(c->slot_pack_entry, 16384, SIZE_MAX);
        for (char (&name)[128] : c->slot_tensor) {
            name[0] = '\0';
        }
        std::fill_n(c->slot_expert, 16384, -1);
        std::fill_n(c->slot_layer, 16384, -1);
        std::fill_n(c->slot_pinned, 16384, false);
        std::fill_n(c->slot_prefetch_down, 16384, false);
        std::fill_n(c->slot_q4_pilot, 16384, false);
        std::fill_n(c->slot_rolling_spec, 16384, false);
        std::fill_n(c->slot_rolling_role, 16384, false);
        std::fill_n(c->slot_dynamic_admitted, 16384, false);
        std::fill_n(c->slot_filling, 16384, false);
        for (cudaEvent_t &ev : c->slot_ready) {
            if (ev) {
                cudaEventDestroy(ev);
                ev = nullptr;
            }
        }
        std::fill_n(c->slot_pending, 16384, false);
        c->clock = 1;
        c->hits = 0;
        c->misses = 0;
        c->preloads = 0;
        c->pinned = 0;
        c->down_prefetch_loads = 0;
        c->down_prefetch_hits = 0;
        c->down_prefetch_evicted = 0;
        c->async_prefetch_waits = 0;
        g_bcache_inited[cid] = false;
    }
    const char *env = std::getenv("GGML_MOE_VRAM_CACHE_GB");
    const size_t budget_gb = env ? (size_t)std::atoi(env) : 16;
    const char *env_mib = std::getenv("GGML_MOE_VRAM_CACHE_MIB");
    size_t budget_mib = env_mib && env_mib[0] ? (size_t)std::strtoull(env_mib, nullptr, 10) : budget_gb * 1024ULL;
    if (budget_mib == 0) {
        g_bcache_inited[cid] = true;
        return nullptr;
    }
    budget_mib = batch_cache_effective_budget_mib(budget_mib);
    size_t this_budget_mib = batch_cache_budget_mib_for_id(budget_mib, cid);
    const size_t budget = this_budget_mib * 1024ULL * 1024ULL;
    batch_vram_cache *c = &g_bcaches[cid];
    c->slot_sz = expert_sz;
    c->n_slots = (int)(budget / expert_sz);
    if (c->n_slots > 16384) c->n_slots = 16384;
    if (hard1_whole_expert_cache_requested() && cid == 0) {
        c->n_slots -= c->n_slots % 3;
    }
    if (cid == 1) {
        const int reserve_slots = kimi_dense_prefetch_upgate_reserve_slots();
        if (reserve_slots > 0 && c->n_slots > reserve_slots) {
            c->n_slots -= reserve_slots;
            std::fprintf(stderr,
                "[moe_stream_batch] dense prefetch reserve: upgate_slots=%d bytes=%zu remaining_slots=%d\n",
                reserve_slots, (size_t) reserve_slots * expert_sz, c->n_slots);
        }
    }
    if (c->n_slots < 1) {
        g_bcache_inited[cid] = true;
        return nullptr;
    }
    c->key_to_slot.clear();
    c->key_to_slot.reserve((size_t)c->n_slots * 2);
    batch_vram_accounting_record("batch_cache_alloc_before", cid, c);
    int alloc_slots = c->n_slots;
    size_t alloc = (size_t)alloc_slots * expert_sz;
    cudaError_t alloc_err = cudaMalloc(&c->pool, alloc);
    if (alloc_err != cudaSuccess) {
        std::fprintf(stderr, "[moe_stream_batch] VRAM cache: cudaMalloc %.1f GiB FAILED; retrying smaller pool\n",
                     alloc / (1024.0*1024.0*1024.0));
        cudaGetLastError();
        const char *retry_env = std::getenv("GGML_MOE_VRAM_CACHE_ALLOC_RETRY");
        const bool retry = !retry_env || !retry_env[0] || retry_env[0] != '0';
        while (retry && alloc_slots > 1) {
            int next_slots = (alloc_slots * 7) / 8;
            if (next_slots >= alloc_slots) next_slots = alloc_slots - 1;
            alloc_slots = next_slots;
            alloc = (size_t)alloc_slots * expert_sz;
            alloc_err = cudaMalloc(&c->pool, alloc);
            if (alloc_err == cudaSuccess) break;
            cudaGetLastError();
        }
        if (alloc_err != cudaSuccess) {
            std::fprintf(stderr, "[moe_stream_batch] VRAM cache: cudaMalloc retry failed; disabling %s cache\n",
                         cid == 1 ? "upgate" : "down");
            c->n_slots = 0;
            g_bcache_inited[cid] = true;
            batch_vram_accounting_record("batch_cache_alloc_failed", cid, c);
            return nullptr;
        }
        c->n_slots = alloc_slots;
    }
    batch_vram_accounting_record("batch_cache_alloc_after", cid, c);
    for (char (&name)[128] : c->slot_tensor) {
        name[0] = '\0';
    }
    std::fill_n(c->slot_pack_entry, 16384, SIZE_MAX);
    std::fill_n(c->slot_expert, 16384, -1);
    std::fill_n(c->slot_layer, 16384, -1);
    std::fill_n(c->slot_dynamic_admitted, 16384, false);
    std::fprintf(stderr, "[moe_stream_batch] VRAM cache[%s]: %.1f GiB, %d slots (%.2f MiB each)%s\n",
                 cid == 1 ? "upgate" : "down", alloc / (1024.0*1024.0*1024.0), c->n_slots,
                 expert_sz / (1024.0*1024.0),
                 hard1_whole_expert_cache_requested() && cid == 0 ?
                    " task136 whole-expert groups" : "");
    std::atexit(batch_cache_report_atexit);
    g_bcache_inited[cid] = true;
    return c;
}

static batch_vram_cache * batch_cache_get_for_tensor(const char *tensor_name, size_t expert_sz) {
    return batch_cache_get_for_id(expert_sz, batch_cache_id_for_tensor(tensor_name, expert_sz));
}

static bool batch_cache_wait_slot_ready(batch_vram_cache *c, int slot) {
    if (!c || slot < 0 || slot >= c->n_slots || !c->slot_pending[slot]) return true;
    const q4_colibri_slot_marker expected{
        c->slot_key[slot], c->slot_generation[slot], c->slot_payload_bytes[slot],
    };
    const q4_colibri_slot_marker ready = c->slot_ready_marker[slot];
    if (ready.generation != 0) {
        if (ready.generation != expected.generation) {
            ++g_expert_pack.q4_pipe_stale_generation;
            return false;
        }
        if (ready.key != expected.key) {
            ++g_expert_pack.q4_pipe_key_mismatch;
            return false;
        }
    }
    if (c->slot_ready[slot]) {
        const auto wait_start = std::chrono::steady_clock::now();
        if (cudaEventSynchronize(c->slot_ready[slot]) != cudaSuccess) {
            return false;
        }
        g_expert_pack.q4_cache_pending_wait_us.fetch_add(
            (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                std::chrono::steady_clock::now() - wait_start).count(), std::memory_order_relaxed);
    }
    c->slot_pending[slot] = false;
    ++c->async_prefetch_waits;
    ++g_expert_pack.q4_cache_pending_wait_calls;
    ++g_expert_pack.q4_cache_pending_wait_slots;
    return true;
}

static int batch_cache_lookup_slot(batch_vram_cache *c, uintptr_t key) {
    if (!c || !c->pool || c->n_slots == 0) return -1;
    auto it = c->key_to_slot.find(key);
    if (it != c->key_to_slot.end()) {
        const int slot = it->second;
        if (slot >= 0 && slot < c->n_slots && c->slot_key[slot] == key) {
            if (c->slot_state[slot] == q4_colibri_slot_state::failed) return -1;
            if (c->slot_filling[slot]) {
                const bool rolling_role = c->slot_rolling_role[slot];
                const auto wait_start = rolling_role ?
                    std::chrono::steady_clock::now() :
                    std::chrono::steady_clock::time_point{};
                if (rolling_role && !c->slot_pending[slot]) {
                    std::unique_lock<std::mutex> ready_lock(
                        g_hard1_rolling_role_ready_mu);
                    g_hard1_rolling_role_ready_cv.wait(
                        ready_lock, [&] {
                            return c->slot_pending[slot] ||
                                c->slot_state[slot] ==
                                    q4_colibri_slot_state::failed ||
                                !c->slot_filling[slot];
                        });
                }
                if (c->slot_state[slot] ==
                        q4_colibri_slot_state::failed) {
                    return -1;
                }
                if ((!c->slot_rolling_spec[slot] && !rolling_role) ||
                        !c->slot_pending[slot] ||
                        !batch_cache_wait_slot_ready(c, slot)) {
                    return -1;
                }
                if (rolling_role) {
                    ++g_hard1_rolling_v2.role_consumer_waits;
                    g_hard1_rolling_v2.role_consumer_wait_us.fetch_add(
                        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                            std::chrono::steady_clock::now() - wait_start).count());
                }
                c->slot_filling[slot] = false;
                c->slot_rolling_spec[slot] = false;
                c->slot_rolling_role[slot] = false;
                c->slot_state[slot] = q4_colibri_slot_state::h2d_ready;
            }
            if (!batch_cache_wait_slot_ready(c, slot)) return -1;
            c->slot_rolling_spec[slot] = false;
            c->slot_rolling_role[slot] = false;
            c->slot_used[slot] = c->clock++;
            if (c->slot_hits[slot] != UINT32_MAX) {
                ++c->slot_hits[slot];
            }
            ++c->hits;
            if (c->slot_prefetch_down[slot]) {
                ++c->down_prefetch_hits;
                c->slot_prefetch_down[slot] = false;
            }
            if (c->slot_q4_pilot[slot]) {
                ++g_expert_pack.q4_pilot_prefetch_used_roles;
                c->slot_q4_pilot[slot] = false;
            }
            return slot;
        }
        c->key_to_slot.erase(it);
    }
    for (int slot = 0; slot < c->n_slots; ++slot) {
        if (c->slot_key[slot] == key) {
            c->key_to_slot[key] = slot;
            if (c->slot_state[slot] == q4_colibri_slot_state::failed) return -1;
            if (c->slot_filling[slot]) {
                const bool rolling_role = c->slot_rolling_role[slot];
                const auto wait_start = rolling_role ?
                    std::chrono::steady_clock::now() :
                    std::chrono::steady_clock::time_point{};
                if (rolling_role && !c->slot_pending[slot]) {
                    std::unique_lock<std::mutex> ready_lock(
                        g_hard1_rolling_role_ready_mu);
                    g_hard1_rolling_role_ready_cv.wait(
                        ready_lock, [&] {
                            return c->slot_pending[slot] ||
                                c->slot_state[slot] ==
                                    q4_colibri_slot_state::failed ||
                                !c->slot_filling[slot];
                        });
                }
                if (c->slot_state[slot] ==
                        q4_colibri_slot_state::failed) {
                    return -1;
                }
                if ((!c->slot_rolling_spec[slot] && !rolling_role) ||
                        !c->slot_pending[slot] ||
                        !batch_cache_wait_slot_ready(c, slot)) {
                    return -1;
                }
                if (rolling_role) {
                    ++g_hard1_rolling_v2.role_consumer_waits;
                    g_hard1_rolling_v2.role_consumer_wait_us.fetch_add(
                        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                            std::chrono::steady_clock::now() - wait_start).count());
                }
                c->slot_filling[slot] = false;
                c->slot_rolling_spec[slot] = false;
                c->slot_rolling_role[slot] = false;
                c->slot_state[slot] = q4_colibri_slot_state::h2d_ready;
            }
            if (!batch_cache_wait_slot_ready(c, slot)) return -1;
            c->slot_rolling_spec[slot] = false;
            c->slot_rolling_role[slot] = false;
            c->slot_used[slot] = c->clock++;
            if (c->slot_hits[slot] != UINT32_MAX) {
                ++c->slot_hits[slot];
            }
            ++c->hits;
            if (c->slot_prefetch_down[slot]) {
                ++c->down_prefetch_hits;
                c->slot_prefetch_down[slot] = false;
            }
            if (c->slot_q4_pilot[slot]) {
                ++g_expert_pack.q4_pilot_prefetch_used_roles;
                c->slot_q4_pilot[slot] = false;
            }
            return slot;
        }
    }
    return -1;
}

static bool batch_cache_contains_slot(const batch_vram_cache *c, uintptr_t key) {
    if (!c || !c->pool || c->n_slots == 0) return false;
    auto it = c->key_to_slot.find(key);
    if (it != c->key_to_slot.end()) {
        const int slot = it->second;
        return slot >= 0 && slot < c->n_slots && c->slot_key[slot] == key &&
            c->slot_state[slot] != q4_colibri_slot_state::failed;
    }
    for (int slot = 0; slot < c->n_slots; ++slot) {
        if (c->slot_key[slot] == key && c->slot_state[slot] != q4_colibri_slot_state::failed) return true;
    }
    return false;
}

static void batch_cache_clear_slot(batch_vram_cache *c, int slot) {
    if (!c || slot < 0 || slot >= c->n_slots) return;
    batch_cache_wait_slot_ready(c, slot);
    unified_dynamic_vram_slot_cleared(c, slot);
    const uintptr_t old_key = c->slot_key[slot];
    if (old_key != 0) {
        auto it = c->key_to_slot.find(old_key);
        if (it != c->key_to_slot.end() && it->second == slot) {
            c->key_to_slot.erase(it);
        }
    }
    c->slot_key[slot] = 0;
    c->slot_used[slot] = 0;
    c->slot_hits[slot] = 0;
    c->slot_profile_count[slot] = 0;
    c->slot_pack_entry[slot] = SIZE_MAX;
    c->slot_tensor[slot][0] = '\0';
    c->slot_expert[slot] = -1;
    c->slot_layer[slot] = -1;
    if (c->slot_pinned[slot] && c->pinned > 0) {
        --c->pinned;
    }
    c->slot_pinned[slot] = false;
    c->slot_prefetch_down[slot] = false;
    c->slot_q4_pilot[slot] = false;
    c->slot_rolling_spec[slot] = false;
    c->slot_rolling_role[slot] = false;
    c->slot_dynamic_admitted[slot] = false;
    c->slot_filling[slot] = false;
    c->slot_pending[slot] = false;
    ++c->slot_generation[slot];
    c->slot_payload_bytes[slot] = 0;
    c->slot_ready_marker[slot] = {};
    c->slot_state[slot] = q4_colibri_slot_state::free;
}

struct moe_phase_cache_workspace_state {
    bool active = false;
    bool shrunken = false;
    bool pack_slot_graph_budget_applied = false;
    uint32_t ubatch = 0;
    int baseline_slots[2] = {};
    int phase_slots[2] = {};
    size_t slot_bytes[2] = {};
    size_t release_bytes = 0;
    uint64_t last_shrink_us = 0;
    uint64_t last_restore_us = 0;
    uint64_t begins = 0;
    uint64_t ends = 0;
    uint64_t failures = 0;
};

static moe_phase_cache_workspace_state g_moe_phase_cache_workspace;

static void batch_cache_reset_storage_locked(int cid) {
    batch_vram_cache *cache = &g_bcaches[cid];
    for (int slot = 0; slot < cache->n_slots; ++slot) {
        batch_cache_clear_slot(cache, slot);
    }
    if (cache->pool) {
        cudaFree(cache->pool);
        cache->pool = nullptr;
    }
    for (int slot = 0; slot < 16384; ++slot) {
        if (cache->slot_ready[slot]) {
            cudaEventDestroy(cache->slot_ready[slot]);
            cache->slot_ready[slot] = nullptr;
        }
        cache->slot_key[slot] = 0;
        cache->slot_used[slot] = 0;
        cache->slot_hits[slot] = 0;
        cache->slot_profile_count[slot] = 0;
        cache->slot_pack_entry[slot] = SIZE_MAX;
        cache->slot_tensor[slot][0] = '\0';
        cache->slot_expert[slot] = -1;
        cache->slot_layer[slot] = -1;
        cache->slot_pinned[slot] = false;
        cache->slot_prefetch_down[slot] = false;
        cache->slot_q4_pilot[slot] = false;
        cache->slot_rolling_spec[slot] = false;
        cache->slot_rolling_role[slot] = false;
        cache->slot_dynamic_admitted[slot] = false;
        cache->slot_pending[slot] = false;
        cache->slot_filling[slot] = false;
        cache->slot_generation[slot] = 0;
        cache->slot_payload_bytes[slot] = 0;
        cache->slot_ready_marker[slot] = {};
        cache->slot_state[slot] = q4_colibri_slot_state::free;
    }
    cache->key_to_slot.clear();
    cache->slot_sz = 0;
    cache->n_slots = 0;
    cache->clock = 1;
    cache->hits = 0;
    cache->misses = 0;
    cache->preloads = 0;
    cache->pinned = 0;
    cache->down_prefetch_loads = 0;
    cache->down_prefetch_hits = 0;
    cache->down_prefetch_evicted = 0;
    cache->async_prefetch_waits = 0;
    g_bcache_inited[cid] = true;
}

static bool batch_cache_allocate_exact_locked(
        int cid,
        size_t slot_bytes,
        int slots,
        const char *event) {
    batch_vram_cache *cache = &g_bcaches[cid];
    if (cache->pool || cache->n_slots != 0) {
        batch_cache_reset_storage_locked(cid);
    }
    if (slot_bytes == 0 || slots <= 0 || slots > 16384) {
        return false;
    }
    cache->slot_sz = slot_bytes;
    cache->n_slots = slots;
    cache->key_to_slot.reserve((size_t)slots * 2);
    const size_t bytes = slot_bytes * (size_t)slots;
    if (cudaMalloc(&cache->pool, bytes) != cudaSuccess) {
        cudaGetLastError();
        cache->slot_sz = 0;
        cache->n_slots = 0;
        cache->pool = nullptr;
        return false;
    }
    char detail[96];
    std::snprintf(detail, sizeof(detail), "phase_slots=%d bytes=%zu", slots, bytes);
    batch_vram_accounting_record(event, cid, cache, detail);
    std::fprintf(stderr,
        "[moe_prefill_phase_workspace] event=%s cache=%s slots=%d "
        "slot_bytes=%zu pool_bytes=%zu\n",
        event,
        cid == 1 ? "upgate" : "down",
        slots,
        slot_bytes,
        bytes);
    return true;
}

static bool moe_phase_cache_restore_locked() {
    if (!g_moe_phase_cache_workspace.shrunken) {
        return true;
    }
    const auto restore_start = std::chrono::steady_clock::now();
    batch_cache_reset_storage_locked(0);
    batch_cache_reset_storage_locked(1);
    bool ok = batch_cache_allocate_exact_locked(
        0,
        g_moe_phase_cache_workspace.slot_bytes[0],
        g_moe_phase_cache_workspace.baseline_slots[0],
        "restore");
    ok = batch_cache_allocate_exact_locked(
        1,
        g_moe_phase_cache_workspace.slot_bytes[1],
        g_moe_phase_cache_workspace.baseline_slots[1],
        "restore") && ok;
    ok = ok &&
        g_bcaches[0].n_slots == g_moe_phase_cache_workspace.baseline_slots[0] &&
        g_bcaches[1].n_slots == g_moe_phase_cache_workspace.baseline_slots[1];
    g_moe_phase_cache_workspace.shrunken = false;
    g_moe_phase_cache_workspace.last_restore_us =
        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - restore_start).count();
    std::fprintf(stderr,
        "[moe_prefill_phase_workspace] event=cache_restore status=%s "
        "down_slots=%d upgate_slots=%d elapsed_us=%llu\n",
        ok ? "pass" : "fail",
        g_bcaches[0].n_slots,
        g_bcaches[1].n_slots,
        (unsigned long long)g_moe_phase_cache_workspace.last_restore_us);
    return ok;
}

static bool moe_phase_cache_shrink_locked() {
    if (hard1_whole_expert_cache_requested()) {
        // The phase workspace assumes independent down/upgate pools and may
        // resize them at different granularities.  Decode already owns the
        // fixed 103 MiB whole-expert pool; preserve it and let the established
        // exact prefill fallback run, as it does for the champion baseline.
        static std::atomic<int> first_whole_expert_skip{0};
        if (first_whole_expert_skip.fetch_add(1) == 0) {
            std::fprintf(stderr,
                "[moe_prefill_phase_workspace] task136 whole-expert cache: "
                "preserving decode pool; phase shrink skipped\n");
        }
        return false;
    }
    const auto shrink_start = std::chrono::steady_clock::now();
    const size_t expert_bytes = g_moe_phase1_plan.expert_bytes;
    const bool preserve_pack_slots =
        moe_phase_env_enabled("GGML_MOE_VRAM_CACHE_PRESERVE_PACK_SLOTS");
    bool existing_pack_slots = preserve_pack_slots &&
        g_bcache_inited[0] && g_bcache_inited[1] &&
        g_bcaches[0].pool && g_bcaches[1].pool &&
        g_bcaches[0].n_slots > 0 && g_bcaches[1].n_slots > 0 &&
        g_bcaches[0].slot_sz == g_bcaches[1].slot_sz &&
        g_bcaches[0].slot_sz < expert_bytes &&
        g_expert_pack.enabled && !g_expert_pack.entries.empty();
    bool saw_exact_pack_slot = false;
    for (const expert_pack_entry & entry : g_expert_pack.entries) {
        if (!existing_pack_slots) {
            break;
        }
        if (entry.nbytes == 0 || entry.nbytes > g_bcaches[0].slot_sz) {
            existing_pack_slots = false;
            break;
        }
        saw_exact_pack_slot = saw_exact_pack_slot ||
            entry.nbytes == g_bcaches[0].slot_sz;
    }
    existing_pack_slots = existing_pack_slots && saw_exact_pack_slot;
    if (!existing_pack_slots) {
        if (!batch_cache_get_for_id(expert_bytes, 0) ||
                !batch_cache_get_for_id(expert_bytes, 1)) {
            return false;
        }
    } else {
        const int dense_reserve_source_slots =
            kimi_dense_prefetch_upgate_reserve_slots();
        const size_t pack_slot_bytes = g_bcaches[0].slot_sz;
        const size_t dense_reserve_bytes =
            (size_t)dense_reserve_source_slots * expert_bytes;
        const int dense_reserve_pack_slots = dense_reserve_source_slots > 0 ?
            (int)((dense_reserve_bytes + pack_slot_bytes - 1) /
                pack_slot_bytes) : 0;
        const int extra_reserve_slots = std::max(
            0, dense_reserve_pack_slots - dense_reserve_source_slots);
        const int original_down_slots = g_bcaches[0].n_slots;
        const int original_upgate_slots = g_bcaches[1].n_slots;
        const int target_upgate_slots = std::max(
            32, original_upgate_slots - extra_reserve_slots);
        if (!g_moe_phase_cache_workspace.pack_slot_graph_budget_applied &&
                target_upgate_slots < original_upgate_slots) {
            batch_cache_reset_storage_locked(0);
            batch_cache_reset_storage_locked(1);
            const bool resized = batch_cache_allocate_exact_locked(
                0, pack_slot_bytes, original_down_slots,
                "pack_slot_graph_budget") &&
                batch_cache_allocate_exact_locked(
                    1, pack_slot_bytes, target_upgate_slots,
                    "pack_slot_graph_budget");
            if (!resized) {
                return false;
            }
        }
        g_moe_phase_cache_workspace.pack_slot_graph_budget_applied = true;
        static std::atomic<int> first_preserved_pack_slots{0};
        if (first_preserved_pack_slots.fetch_add(1) == 0) {
            std::fprintf(stderr,
                "[moe_prefill_phase_workspace] preserving expert-pack cache slot size: "
                "pack_slot_bytes=%zu source_stride_bytes=%zu down_slots=%d upgate_slots=%d "
                "dense_reserve_bytes=%zu dense_reserve_pack_slots=%d\n",
                g_bcaches[0].slot_sz, expert_bytes,
                g_bcaches[0].n_slots, g_bcaches[1].n_slots,
                dense_reserve_bytes, dense_reserve_pack_slots);
        }
    }
    for (int cid = 0; cid < 2; ++cid) {
        g_moe_phase_cache_workspace.baseline_slots[cid] = g_bcaches[cid].n_slots;
        g_moe_phase_cache_workspace.slot_bytes[cid] = g_bcaches[cid].slot_sz;
    }
    const int baseline_total =
        g_moe_phase_cache_workspace.baseline_slots[0] +
        g_moe_phase_cache_workspace.baseline_slots[1];
    if (baseline_total <= 48) {
        return false;
    }
    size_t cuda_free = 0;
    size_t cuda_total = 0;
    if (cudaMemGetInfo(&cuda_free, &cuda_total) != cudaSuccess) {
        cudaGetLastError();
        return false;
    }
    const uint64_t mib = 1024ULL * 1024ULL;
    const uint64_t graph_mib = moe_phase_env_mib(
        "GGML_MOE_PREFILL_PHASE_WORKSPACE_MIB", 3123);
    const uint64_t safety_mib = moe_phase_env_mib(
        "GGML_MOE_PREFILL_PHASE_WORKSPACE_SAFETY_MIB", 256);
    const uint64_t required_free =
        graph_mib * mib + safety_mib * mib +
        (uint64_t)g_moe_phase1_plan.device_bytes;
    uint64_t release_bytes = required_free > cuda_free ?
        required_free - cuda_free : 0;
    const size_t down_slot_bytes = g_moe_phase_cache_workspace.slot_bytes[0];
    const size_t upgate_slot_bytes = g_moe_phase_cache_workspace.slot_bytes[1];
    if (down_slot_bytes == 0 || upgate_slot_bytes == 0) {
        return false;
    }
    const bool heterogeneous_slots = down_slot_bytes != upgate_slot_bytes;
    if (heterogeneous_slots &&
            !moe_phase_env_enabled("GGML_MOE_PREFILL_DECODE_CACHE_HANDOVER")) {
        return false;
    }

    int phase_down = 0;
    int phase_upgate = 0;
    if (!heterogeneous_slots) {
        int release_slots = (int)((release_bytes + down_slot_bytes - 1) /
            down_slot_bytes);
        release_slots = std::max(0, std::min(release_slots, baseline_total - 48));
        const int keep_total = baseline_total - release_slots;
        phase_down = (int)((int64_t)keep_total *
            g_moe_phase_cache_workspace.baseline_slots[0] / baseline_total);
        phase_upgate = keep_total - phase_down;
        phase_down = std::max(16, phase_down);
        phase_upgate = std::max(32, phase_upgate);
        while (phase_down + phase_upgate > keep_total) {
            if (phase_down > 16 && phase_down >= phase_upgate) {
                --phase_down;
            } else if (phase_upgate > 32) {
                --phase_upgate;
            } else {
                return false;
            }
        }
    } else {
        const uint64_t baseline_down_bytes =
            (uint64_t)g_moe_phase_cache_workspace.baseline_slots[0] * down_slot_bytes;
        const uint64_t baseline_upgate_bytes =
            (uint64_t)g_moe_phase_cache_workspace.baseline_slots[1] * upgate_slot_bytes;
        const uint64_t baseline_bytes = baseline_down_bytes + baseline_upgate_bytes;
        const uint64_t minimum_bytes = 16ULL * down_slot_bytes +
            32ULL * upgate_slot_bytes;
        if (baseline_bytes <= minimum_bytes) {
            return false;
        }
        release_bytes = std::min<uint64_t>(
            release_bytes, baseline_bytes - minimum_bytes);
        const uint64_t keep_bytes = baseline_bytes - release_bytes;
        phase_down = std::max<int>(16,
            (int)((uint64_t)g_moe_phase_cache_workspace.baseline_slots[0] *
                keep_bytes / baseline_bytes));
        phase_upgate = std::max<int>(32,
            (int)((uint64_t)g_moe_phase_cache_workspace.baseline_slots[1] *
                keep_bytes / baseline_bytes));
        uint64_t phase_bytes =
            (uint64_t)phase_down * down_slot_bytes +
            (uint64_t)phase_upgate * upgate_slot_bytes;
        while (phase_bytes > keep_bytes) {
            if (phase_down > 16 &&
                    (phase_upgate == 32 || down_slot_bytes >= upgate_slot_bytes)) {
                --phase_down;
                phase_bytes -= down_slot_bytes;
            } else if (phase_upgate > 32) {
                --phase_upgate;
                phase_bytes -= upgate_slot_bytes;
            } else {
                return false;
            }
        }
    }
    g_moe_phase_cache_workspace.phase_slots[0] = phase_down;
    g_moe_phase_cache_workspace.phase_slots[1] = phase_upgate;
    g_moe_phase_cache_workspace.release_bytes =
        (size_t)g_moe_phase_cache_workspace.baseline_slots[0] * down_slot_bytes +
        (size_t)g_moe_phase_cache_workspace.baseline_slots[1] * upgate_slot_bytes -
        (size_t)phase_down * down_slot_bytes -
        (size_t)phase_upgate * upgate_slot_bytes;

    batch_cache_reset_storage_locked(0);
    batch_cache_reset_storage_locked(1);
    g_moe_phase_cache_workspace.shrunken = true;
    bool ok = batch_cache_allocate_exact_locked(
        0, down_slot_bytes, phase_down, "shrink");
    ok = batch_cache_allocate_exact_locked(
        1, upgate_slot_bytes, phase_upgate, "shrink") && ok;
    if (!ok) {
        ++g_moe_phase_cache_workspace.failures;
        moe_phase_cache_restore_locked();
        return false;
    }
    g_moe_phase_cache_workspace.last_shrink_us =
        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - shrink_start).count();
    std::fprintf(stderr,
        "[moe_prefill_phase_workspace] event=cache_shrink status=pass "
        "baseline_down=%d baseline_upgate=%d phase_down=%d phase_upgate=%d "
        "down_slot_bytes=%zu upgate_slot_bytes=%zu heterogeneous=%d "
        "release_bytes=%zu graph_mib=%llu safety_mib=%llu "
        "cuda_free_before=%zu cuda_total=%zu elapsed_us=%llu\n",
        g_moe_phase_cache_workspace.baseline_slots[0],
        g_moe_phase_cache_workspace.baseline_slots[1],
        phase_down,
        phase_upgate,
        down_slot_bytes,
        upgate_slot_bytes,
        heterogeneous_slots ? 1 : 0,
        g_moe_phase_cache_workspace.release_bytes,
        (unsigned long long)graph_mib,
        (unsigned long long)safety_mib,
        cuda_free,
        cuda_total,
        (unsigned long long)g_moe_phase_cache_workspace.last_shrink_us);
    std::fflush(stderr);
    return true;
}

extern "C" bool ggml_cuda_moe_prefill_phase_workspace_begin(uint32_t n_ubatch) {
    if (!moe_phase_env_enabled("GGML_MOE_PREFILL_PHASE_SIZED_WORKSPACE")) {
        return true;
    }
    std::lock_guard<std::mutex> lock(g_batch_mu);
    if (!g_moe_phase1_plan.planned || !g_moe_phase1_plan.phase_sized ||
            n_ubatch == 0 ||
            (uint64_t)n_ubatch * 16ULL > g_moe_phase1_plan.capacity) {
        return false;
    }
    if (g_moe_phase_cache_workspace.active) {
        return g_moe_phase_cache_workspace.ubatch == n_ubatch;
    }
    if (cudaDeviceSynchronize() != cudaSuccess) {
        cudaGetLastError();
        ++g_moe_phase_cache_workspace.failures;
        return false;
    }
    g_moe_phase_cache_workspace.last_shrink_us = 0;
    g_moe_phase_cache_workspace.last_restore_us = 0;
    g_moe_phase_cache_workspace.ubatch = n_ubatch;
    const bool need_shrink = n_ubatch > 16;
    if (need_shrink && !moe_phase_cache_shrink_locked()) {
        ++g_moe_phase_cache_workspace.failures;
        return false;
    }
    if (!moe_phase1_plan_allocate_resources_locked()) {
        ++g_moe_phase_cache_workspace.failures;
        moe_phase_cache_restore_locked();
        return false;
    }
    g_moe_phase_cache_workspace.active = true;
    ++g_moe_phase_cache_workspace.begins;
    std::fprintf(stderr,
        "[moe_prefill_phase_workspace] event=begin status=pass ubatch=%u "
        "capacity=%u down_slots=%d upgate_slots=%d shrunken=%d "
        "cache_shrink_us=%llu begins=%llu\n",
        n_ubatch,
        g_moe_phase1_plan.capacity,
        g_bcaches[0].n_slots,
        g_bcaches[1].n_slots,
        g_moe_phase_cache_workspace.shrunken ? 1 : 0,
        (unsigned long long)g_moe_phase_cache_workspace.last_shrink_us,
        (unsigned long long)g_moe_phase_cache_workspace.begins);
    std::fflush(stderr);
    return true;
}

extern "C" bool ggml_cuda_moe_prefill_phase_workspace_end(void) {
    if (!moe_phase_env_enabled("GGML_MOE_PREFILL_PHASE_SIZED_WORKSPACE")) {
        return true;
    }
    std::lock_guard<std::mutex> lock(g_batch_mu);
    if (!g_moe_phase_cache_workspace.active &&
            !g_moe_phase_cache_workspace.shrunken &&
            !g_moe_phase1_plan.resources_allocated) {
        return true;
    }
    moe_phase1_plan_release_resources_locked();
    const bool restored = moe_phase_cache_restore_locked();
    g_moe_phase_cache_workspace.active = false;
    g_moe_phase_cache_workspace.ubatch = 0;
    ++g_moe_phase_cache_workspace.ends;
    size_t cuda_free = 0;
    size_t cuda_total = 0;
    if (cudaMemGetInfo(&cuda_free, &cuda_total) != cudaSuccess) {
        cudaGetLastError();
        cuda_free = 0;
        cuda_total = 0;
    }
    std::fprintf(stderr,
        "[moe_prefill_phase_workspace] event=end status=%s down_slots=%d "
        "upgate_slots=%d provider_allocated=%d cuda_free=%zu cuda_total=%zu "
        "cache_restore_us=%llu ends=%llu failures=%llu\n",
        restored ? "pass" : "fail",
        g_bcaches[0].n_slots,
        g_bcaches[1].n_slots,
        g_moe_phase1_plan.resources_allocated ? 1 : 0,
        cuda_free,
        cuda_total,
        (unsigned long long)g_moe_phase_cache_workspace.last_restore_us,
        (unsigned long long)g_moe_phase_cache_workspace.ends,
        (unsigned long long)g_moe_phase_cache_workspace.failures);
    std::fflush(stderr);
    return restored;
}

static int batch_cache_find_slot(batch_vram_cache *c, uintptr_t key) {
    if (!c || !c->pool || c->n_slots == 0) return -1;
    auto it = c->key_to_slot.find(key);
    if (it != c->key_to_slot.end()) {
        const int slot = it->second;
        if (slot >= 0 && slot < c->n_slots && c->slot_key[slot] == key) {
            return c->slot_state[slot] != q4_colibri_slot_state::failed ? slot : -1;
        }
        c->key_to_slot.erase(it);
    }
    for (int slot = 0; slot < c->n_slots; ++slot) {
        if (c->slot_key[slot] == key) {
            c->key_to_slot[key] = slot;
            return c->slot_state[slot] != q4_colibri_slot_state::failed ? slot : -1;
        }
    }
    return -1;
}

static bool q4_batch_pending_wait_enabled() {
    const char *env = std::getenv("GGML_MOE_Q4_BATCH_PENDING_WAIT");
    return env && env[0] && env[0] != '0';
}

static bool q4_batch_pending_wait_role_allowed(size_t role_idx) {
    const char *env = std::getenv("GGML_MOE_Q4_BATCH_PENDING_WAIT_ROLES");
    if (!env || !env[0] || std::strcmp(env, "upgate") == 0 || std::strcmp(env, "gateup") == 0) {
        return role_idx == 0 || role_idx == 1;
    }
    if (std::strcmp(env, "all") == 0 || std::strcmp(env, "*") == 0) {
        return role_idx < 3;
    }
    if (std::strcmp(env, "gate") == 0) return role_idx == 0;
    if (std::strcmp(env, "up") == 0) return role_idx == 1;
    if (std::strcmp(env, "down") == 0) return role_idx == 2;
    return role_idx == 0 || role_idx == 1;
}

static bool batch_cache_pending_slot_marker_valid(batch_vram_cache *c, int slot) {
    const q4_colibri_slot_marker expected{
        c->slot_key[slot], c->slot_generation[slot], c->slot_payload_bytes[slot],
    };
    const q4_colibri_slot_marker ready = c->slot_ready_marker[slot];
    if (ready.generation == 0) return true;
    if (ready.generation != expected.generation) {
        ++g_expert_pack.q4_pipe_stale_generation;
        return false;
    }
    if (ready.key != expected.key) {
        ++g_expert_pack.q4_pipe_key_mismatch;
        return false;
    }
    return true;
}

static bool batch_cache_wait_pending_slots_for_active(
        batch_vram_cache *c,
        const char *const role_names[3],
        int64_t n_as,
        const int64_t *matrix_row_counts) {
    if (!q4_batch_pending_wait_enabled()) return true;
    if (!c || !role_names || n_as <= 0 || !matrix_row_counts) return true;

    std::vector<int> pending_slots;
    pending_slots.reserve(64);
    for (int64_t expert = 0; expert < n_as; ++expert) {
        if (matrix_row_counts[expert] <= 0) continue;
        for (size_t role_idx = 0; role_idx < 3; ++role_idx) {
            if (!q4_batch_pending_wait_role_allowed(role_idx)) continue;
            const char *role_name = role_names[role_idx];
            if (!role_name || !role_name[0]) continue;
            const int slot = batch_cache_find_slot(c, batch_key_hash(role_name, (int)expert));
            if (slot < 0 || slot >= c->n_slots || !c->slot_pending[slot]) continue;
            bool seen = false;
            for (int existing : pending_slots) {
                if (existing == slot) {
                    seen = true;
                    break;
                }
            }
            if (!seen) pending_slots.push_back(slot);
        }
    }
    if (pending_slots.empty()) return true;

    for (int slot : pending_slots) {
        if (!batch_cache_pending_slot_marker_valid(c, slot)) {
            return false;
        }
    }

    const auto wait_start = std::chrono::steady_clock::now();
    int representative = -1;
    for (int slot : pending_slots) {
        if (c->slot_ready[slot]) representative = slot;
    }
    if (representative >= 0) {
        if (cudaEventSynchronize(c->slot_ready[representative]) != cudaSuccess) {
            return false;
        }
        ++g_expert_pack.q4_cache_pending_batch_wait_representative_syncs;
    }

    uint64_t extra_syncs = 0;
    for (int slot : pending_slots) {
        if (slot == representative || !c->slot_ready[slot]) continue;
        const cudaError_t query = cudaEventQuery(c->slot_ready[slot]);
        if (query == cudaSuccess) continue;
        if (query != cudaErrorNotReady) return false;
        if (cudaEventSynchronize(c->slot_ready[slot]) != cudaSuccess) {
            return false;
        }
        ++extra_syncs;
    }

    const uint64_t wait_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - wait_start).count();
    for (int slot : pending_slots) {
        c->slot_pending[slot] = false;
        ++c->async_prefetch_waits;
    }
    ++g_expert_pack.q4_cache_pending_wait_calls;
    g_expert_pack.q4_cache_pending_wait_slots.fetch_add(pending_slots.size(), std::memory_order_relaxed);
    g_expert_pack.q4_cache_pending_wait_us.fetch_add(wait_us, std::memory_order_relaxed);
    ++g_expert_pack.q4_cache_pending_batch_wait_calls;
    g_expert_pack.q4_cache_pending_batch_wait_slots.fetch_add(pending_slots.size(), std::memory_order_relaxed);
    g_expert_pack.q4_cache_pending_batch_wait_us.fetch_add(wait_us, std::memory_order_relaxed);
    g_expert_pack.q4_cache_pending_batch_wait_extra_syncs.fetch_add(extra_syncs, std::memory_order_relaxed);
    return true;
}

