static bool q4_tier_reuse_protect_fast_in_range(int layer, int expert) {
    return layer >= 0 && layer < 128 && expert >= 0 && expert < Q4_TIER_REUSE_PROTECT_MAX_EXPERTS;
}

static void q4_tier_reuse_protect_set_locked(int layer, int expert, uint64_t until_epoch) {
    if (q4_tier_reuse_protect_fast_in_range(layer, expert)) {
        g_q4_tier_overlap_diag.vram_reuse_protect_until_fast[layer][expert].store(
                until_epoch, std::memory_order_release);
        return;
    }
    g_q4_tier_overlap_diag.vram_reuse_protect_until_epoch[
        q4_tier_diag_object_key(layer, expert)] = until_epoch;
}

static void q4_tier_reuse_protect_clear_locked(const std::string &key, int layer, int expert) {
    if (q4_tier_reuse_protect_fast_in_range(layer, expert)) {
        g_q4_tier_overlap_diag.vram_reuse_protect_until_fast[layer][expert].store(
                0, std::memory_order_release);
    }
    g_q4_tier_overlap_diag.vram_reuse_protect_until_epoch.erase(key);
}

static bool q4_tier_diag_cache_has_ready_key(const batch_vram_cache &cache, uintptr_t key) {
    if (!cache.pool || cache.n_slots <= 0 || key == 0) return false;
    auto indexed = cache.key_to_slot.find(key);
    if (indexed != cache.key_to_slot.end()) {
        const int slot = indexed->second;
        if (slot >= 0 && slot < cache.n_slots && cache.slot_key[slot] == key) {
            if (cache.slot_state[slot] == q4_colibri_slot_state::failed ||
                    cache.slot_state[slot] == q4_colibri_slot_state::free ||
                    cache.slot_state[slot] == q4_colibri_slot_state::reserved ||
                    cache.slot_state[slot] == q4_colibri_slot_state::reading ||
                    cache.slot_filling[slot]) {
                return false;
            }
            return cache.slot_payload_bytes[slot] > 0;
        }
    }
    for (int slot = 0; slot < cache.n_slots; ++slot) {
        if (cache.slot_key[slot] != key) continue;
        if (cache.slot_state[slot] == q4_colibri_slot_state::failed ||
                cache.slot_state[slot] == q4_colibri_slot_state::free ||
                cache.slot_state[slot] == q4_colibri_slot_state::reserved ||
                cache.slot_state[slot] == q4_colibri_slot_state::reading ||
                cache.slot_filling[slot]) {
            return false;
        }
        return cache.slot_payload_bytes[slot] > 0;
    }
    return false;
}

static int q4_tier_diag_cache_ready_slot(const batch_vram_cache &cache, uintptr_t key) {
    if (!cache.pool || cache.n_slots <= 0 || key == 0) return -1;
    auto indexed = cache.key_to_slot.find(key);
    if (indexed != cache.key_to_slot.end()) {
        const int slot = indexed->second;
        if (slot >= 0 && slot < cache.n_slots && cache.slot_key[slot] == key) {
            if (cache.slot_state[slot] == q4_colibri_slot_state::failed ||
                    cache.slot_state[slot] == q4_colibri_slot_state::free ||
                    cache.slot_state[slot] == q4_colibri_slot_state::reserved ||
                    cache.slot_state[slot] == q4_colibri_slot_state::reading ||
                    cache.slot_filling[slot] || cache.slot_pending[slot] ||
                    cache.slot_payload_bytes[slot] == 0) {
                return -1;
            }
            return slot;
        }
    }
    for (int slot = 0; slot < cache.n_slots; ++slot) {
        if (cache.slot_key[slot] != key) continue;
        if (cache.slot_state[slot] == q4_colibri_slot_state::failed ||
                cache.slot_state[slot] == q4_colibri_slot_state::free ||
                cache.slot_state[slot] == q4_colibri_slot_state::reserved ||
                cache.slot_state[slot] == q4_colibri_slot_state::reading ||
                cache.slot_filling[slot] || cache.slot_pending[slot] ||
                cache.slot_payload_bytes[slot] == 0) {
            return -1;
        }
        return slot;
    }
    return -1;
}

static int q4_tier_diag_vram_roles_for_object(int layer, int expert) {
    if (layer < 0 || expert < 0) return 0;
    char gate_name[128];
    char up_name[128];
    char down_name[128];
    std::snprintf(gate_name, sizeof(gate_name), "blk.%d.ffn_gate_exps.weight", layer);
    std::snprintf(up_name, sizeof(up_name), "blk.%d.ffn_up_exps.weight", layer);
    std::snprintf(down_name, sizeof(down_name), "blk.%d.ffn_down_exps.weight", layer);
    const char *role_names[3] = {gate_name, up_name, down_name};
    int roles = 0;
    for (const char *role_name : role_names) {
        const uintptr_t key = batch_key_hash(role_name, expert);
        bool found = false;
        for (int cid = 0; cid < 2 && !found; ++cid) {
            if (q4_tier_diag_cache_has_ready_key(g_bcaches[cid], key)) {
                found = true;
            }
        }
        if (found) ++roles;
    }
    return roles;
}

static int q4_tier_diag_vram_roles_for_object(const q4_colibri_object_marker &marker) {
    return q4_tier_diag_vram_roles_for_object(marker.layer_idx, marker.expert_idx);
}

static bool q4_tier_role_family_names(
        const char *role_name,
        std::string &gate_name,
        std::string &up_name,
        std::string &down_name) {
    if (!role_name || !role_name[0]) return false;
    gate_name = role_name;
    const char *needles[3] = {
        ".ffn_gate_exps.",
        ".ffn_up_exps.",
        ".ffn_down_exps.",
    };
    size_t pos = std::string::npos;
    const char *matched = nullptr;
    for (const char *needle : needles) {
        pos = gate_name.find(needle);
        if (pos != std::string::npos) {
            matched = needle;
            break;
        }
    }
    if (!matched) return false;
    gate_name.replace(pos, std::strlen(matched), ".ffn_gate_exps.");
    up_name = gate_name;
    down_name = gate_name;
    up_name.replace(pos, std::strlen(".ffn_gate_exps."), ".ffn_up_exps.");
    down_name.replace(pos, std::strlen(".ffn_gate_exps."), ".ffn_down_exps.");
    return true;
}

static uint64_t q4_tier_diag_observe_layer_locked(int layer) {
    if (layer >= 0) {
        if (g_q4_tier_overlap_diag.last_layer >= 0 && layer < g_q4_tier_overlap_diag.last_layer) {
            ++g_q4_tier_overlap_diag.token_epoch;
        }
        g_q4_tier_overlap_diag.last_layer = layer;
        g_q4_tier_overlap_diag.token_epoch_public.store(
                g_q4_tier_overlap_diag.token_epoch, std::memory_order_release);
    }
    return g_q4_tier_overlap_diag.token_epoch;
}

static int q4_tier_diag_current_layer_snapshot() {
    std::lock_guard<std::mutex> lock(g_q4_tier_overlap_diag.mu);
    return g_q4_tier_overlap_diag.last_layer;
}

static void q4_tier_diag_observe_object_request(const q4_colibri_object_marker &marker) {
    ++g_q4_tier_overlap_diag.object_demands;
    q4_tier_layer_add(g_q4_tier_overlap_diag.tier_layer_object_demands, marker.layer_idx);
    std::lock_guard<std::mutex> lock(g_q4_tier_overlap_diag.mu);
    const uint64_t epoch = q4_tier_diag_observe_layer_locked(marker.layer_idx);
    q4_cache_locality_maybe_sample(marker.layer_idx);
    const std::string key = q4_tier_diag_object_key(marker);
    auto it = g_q4_tier_overlap_diag.vram_evicted_epoch.find(key);
    if (it == g_q4_tier_overlap_diag.vram_evicted_epoch.end()) return;
    const uint64_t age = epoch >= it->second ? epoch - it->second : 0;
    if (age <= (uint64_t)q4_tier_diag_window_tokens()) {
        if (g_q4_tier_overlap_diag.vram_evicted_reuse_counted.insert(key).second) {
            ++g_q4_tier_overlap_diag.vram_evicted_reused_within_window;
            q4_tier_layer_add(g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_within_window, marker.layer_idx);
            if (q4_tier_reuse_window_profile_enabled()) {
                for (int wi = 0; wi < Q4_TIER_REUSE_WINDOW_COUNT; ++wi) {
                    if (age <= (uint64_t)Q4_TIER_REUSE_WINDOWS[wi]) {
                        ++g_q4_tier_overlap_diag.vram_evicted_reused_by_window[wi];
                        q4_tier_layer_add(
                                g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_by_window[wi],
                                marker.layer_idx);
                    }
                }
            }
            if (q4_tier_vram_reuse_protect_enabled()) {
                if (!q4_tier_vram_reuse_protect_layer_allowed(marker.layer_idx)) {
                    ++g_q4_tier_overlap_diag.vram_reuse_protect_layer_skips;
                    return;
                }
                q4_tier_reuse_protect_set_locked(
                        marker.layer_idx,
                        marker.expert_idx,
                        epoch + (uint64_t)q4_tier_vram_reuse_protect_window_tokens());
                ++g_q4_tier_overlap_diag.vram_reuse_protect_marks;
            }
        }
    } else {
        g_q4_tier_overlap_diag.vram_evicted_epoch.erase(it);
        g_q4_tier_overlap_diag.vram_evicted_reuse_counted.erase(key);
        q4_tier_reuse_protect_clear_locked(key, marker.layer_idx, marker.expert_idx);
    }
}

static bool q4_tier_diag_vram_reuse_protected(int layer, int expert) {
    if (!q4_tier_vram_reuse_protect_enabled() || layer < 0 || expert < 0) return false;
    if (!q4_tier_vram_reuse_protect_layer_allowed(layer)) return false;
    if (q4_tier_reuse_protect_fast_in_range(layer, expert)) {
        const uint64_t until =
            g_q4_tier_overlap_diag.vram_reuse_protect_until_fast[layer][expert].load(
                    std::memory_order_acquire);
        if (until == 0) return false;
        const uint64_t epoch =
            g_q4_tier_overlap_diag.token_epoch_public.load(std::memory_order_acquire);
        if (epoch <= until) return true;
        uint64_t expected = until;
        if (g_q4_tier_overlap_diag.vram_reuse_protect_until_fast[layer][expert].compare_exchange_strong(
                    expected, 0, std::memory_order_acq_rel)) {
            ++g_q4_tier_overlap_diag.vram_reuse_protect_expired;
        }
        return false;
    }
    std::lock_guard<std::mutex> lock(g_q4_tier_overlap_diag.mu);
    const std::string key = q4_tier_diag_object_key(layer, expert);
    auto it = g_q4_tier_overlap_diag.vram_reuse_protect_until_epoch.find(key);
    if (it == g_q4_tier_overlap_diag.vram_reuse_protect_until_epoch.end()) return false;
    if (g_q4_tier_overlap_diag.token_epoch <= it->second) return true;
    g_q4_tier_overlap_diag.vram_reuse_protect_until_epoch.erase(it);
    ++g_q4_tier_overlap_diag.vram_reuse_protect_expired;
    return false;
}

static void q4_tier_diag_record_vram_eviction(int layer, int expert) {
    if (layer < 0 || expert < 0) return;
    std::lock_guard<std::mutex> lock(g_q4_tier_overlap_diag.mu);
    const uint64_t epoch = g_q4_tier_overlap_diag.token_epoch;
    const std::string key = q4_tier_diag_object_key(layer, expert);
    g_q4_tier_overlap_diag.vram_evicted_epoch[key] = epoch;
    g_q4_tier_overlap_diag.vram_evicted_reuse_counted.erase(key);
    q4_tier_reuse_protect_clear_locked(key, layer, expert);
    ++g_q4_tier_overlap_diag.vram_evictions;
    q4_tier_layer_add(g_q4_tier_overlap_diag.tier_layer_vram_evictions, layer);
}

static void q4_tier_diag_record_ram_eviction(const q4_colibri_object_marker &marker) {
    const int vram_roles = q4_tier_diag_vram_roles_for_object(marker);
    if (vram_roles < 3) return;
    std::lock_guard<std::mutex> lock(g_q4_tier_overlap_diag.mu);
    const uint64_t epoch = g_q4_tier_overlap_diag.token_epoch;
    g_q4_tier_overlap_diag.covered_ram_evicted_epoch[q4_tier_diag_object_key(marker)] = epoch;
    ++g_q4_tier_overlap_diag.covered_ram_evictions;
    q4_tier_layer_add(g_q4_tier_overlap_diag.tier_layer_covered_ram_evictions, marker.layer_idx);
}

static void q4_tier_diag_record_ram_miss(const q4_colibri_object_marker &marker) {
    std::lock_guard<std::mutex> lock(g_q4_tier_overlap_diag.mu);
    const uint64_t epoch = g_q4_tier_overlap_diag.token_epoch;
    const std::string key = q4_tier_diag_object_key(marker);
    auto it = g_q4_tier_overlap_diag.covered_ram_evicted_epoch.find(key);
    if (it == g_q4_tier_overlap_diag.covered_ram_evicted_epoch.end()) return;
    const uint64_t age = epoch >= it->second ? epoch - it->second : 0;
    if (age <= (uint64_t)q4_tier_diag_window_tokens()) {
        ++g_q4_tier_overlap_diag.covered_ram_eviction_misses_within_window;
        q4_tier_layer_add(
                g_q4_tier_overlap_diag.tier_layer_covered_ram_eviction_misses_within_window,
                marker.layer_idx);
    }
    g_q4_tier_overlap_diag.covered_ram_evicted_epoch.erase(it);
}

static void q4_tier_diag_record_ram_hit(const q4_colibri_object_marker &marker) {
    const int vram_roles = q4_tier_diag_vram_roles_for_object(marker);
    if (vram_roles == 3) {
        ++g_q4_tier_overlap_diag.ram_hit_vram_full_overlap;
        q4_tier_layer_add(g_q4_tier_overlap_diag.tier_layer_ram_hit_vram_full_overlap, marker.layer_idx);
    } else if (vram_roles > 0) {
        g_q4_tier_overlap_diag.ram_hit_vram_partial_overlap_roles.fetch_add(
                (uint64_t)vram_roles, std::memory_order_relaxed);
        q4_tier_layer_add(
                g_q4_tier_overlap_diag.tier_layer_ram_hit_vram_partial_overlap_roles,
                marker.layer_idx,
                (uint64_t)vram_roles);
    }
    std::lock_guard<std::mutex> lock(g_q4_tier_overlap_diag.mu);
    const uint64_t epoch = g_q4_tier_overlap_diag.token_epoch;
    const std::string key = q4_tier_diag_object_key(marker);
    auto it = g_q4_tier_overlap_diag.vram_evicted_epoch.find(key);
    if (it == g_q4_tier_overlap_diag.vram_evicted_epoch.end()) return;
    ++g_q4_tier_overlap_diag.ram_hits_after_vram_eviction;
    q4_tier_layer_add(g_q4_tier_overlap_diag.tier_layer_ram_hits_after_vram_eviction, marker.layer_idx);
    const uint64_t age = epoch >= it->second ? epoch - it->second : 0;
    if (age <= (uint64_t)q4_tier_diag_window_tokens()) {
        ++g_q4_tier_overlap_diag.ram_hits_after_vram_eviction_within_window;
        q4_tier_layer_add(
                g_q4_tier_overlap_diag.tier_layer_ram_hits_after_vram_eviction_within_window,
                marker.layer_idx);
    }
}

static void batch_cache_touch_slot(batch_vram_cache *c, int slot) {
    if (!c || slot < 0 || slot >= c->n_slots || c->slot_key[slot] == 0) return;
    if (c->slot_state[slot] == q4_colibri_slot_state::failed || c->slot_filling[slot]) return;
    c->slot_used[slot] = c->clock++;
    if (c->slot_hits[slot] != UINT32_MAX) {
        ++c->slot_hits[slot];
    }
}



static bool batch_cache_promote_profile_slot(batch_vram_cache *c, int slot, uint64_t profile_count) {
    if (!c || slot < 0 || slot >= c->n_slots || c->slot_key[slot] == 0) return false;
    if (c->slot_pinned[slot]) {
        if (profile_count > 0) {
            c->slot_profile_count[slot] = profile_count > UINT32_MAX ? UINT32_MAX : (uint32_t)profile_count;
        }
        return true;
    }
    if (c->pinned >= profile_preload_slot_budget(c)) return false;
    c->slot_pinned[slot] = true;
    ++c->pinned;
    c->slot_profile_count[slot] = profile_count > UINT32_MAX ? UINT32_MAX : (uint32_t)profile_count;
    return true;
}

static bool batch_slot_is_avoided(int slot, const int *avoid_slots, int n_avoid_slots) {
    if (!avoid_slots || n_avoid_slots <= 0) return false;
    for (int i = 0; i < n_avoid_slots; ++i) {
        if (avoid_slots[i] == slot) return true;
    }
    return false;
}

