static bool trace_entry_matches(const batch_route_trace_entry &e, const char *tensor_name, int expert_idx, size_t expert_bytes);
static bool expert_pack_direct_read_entry_to_host(const expert_pack_entry *entry, void *dst, size_t sz);

static uint64_t host_prefetch_key(const char *tensor_name, int expert_idx, size_t nbytes) {
    uint64_t h = 1469598103934665603ULL;
    if (tensor_name) {
        for (const unsigned char *p = (const unsigned char *)tensor_name; *p; ++p) {
            h ^= (uint64_t)(*p);
            h *= 1099511628211ULL;
        }
    }
    h ^= (uint64_t)(uint32_t)expert_idx;
    h *= 1099511628211ULL;
    h ^= (uint64_t)nbytes;
    h *= 1099511628211ULL;
    return h;
}

static void host_prefetch_report_atexit() {
    std::lock_guard<std::mutex> lk(g_host_prefetch.mu);
    if (!g_host_prefetch.enabled) return;
    std::fprintf(stderr,
        "[moe_stream_batch] host prefetch: calls=%lu matched=%lu resync=%lu submitted=%lu hits=%lu misses=%lu "
        "empty_misses=%lu ready=%lu evicted=%lu read_failures=%lu alloc_failures=%lu duplicate_skips=%lu profile_pinned_skips=%lu reserved_skips=%lu no_slot=%lu "
        "planned_enqueued=%lu planned_dequeued=%lu planned_duplicate_skips=%lu scan_passes=%lu "
        "cursor=%zu produce_cursor=%zu/%zu skip=%zu used=%.2f MiB slots=%zu\n",
        g_host_prefetch.calls,
        g_host_prefetch.matched,
        g_host_prefetch.resync,
        g_host_prefetch.submitted,
        g_host_prefetch.hits,
        g_host_prefetch.misses,
        (unsigned long)g_host_prefetch.empty_misses.load(),
        (unsigned long)g_host_prefetch.ready_count.load(),
        g_host_prefetch.evicted,
        g_host_prefetch.read_failures,
        g_host_prefetch.alloc_failures,
        g_host_prefetch.duplicate_skips,
        g_host_prefetch.profile_pinned_skips,
        g_host_prefetch.reserved_skips,
        g_host_prefetch.no_slot,
        g_host_prefetch.planned_enqueued,
        g_host_prefetch.planned_dequeued,
        g_host_prefetch.planned_duplicate_skips,
        g_host_prefetch.scan_passes,
        g_host_prefetch.cursor,
        g_host_prefetch.produce_cursor,
        g_host_prefetch.trace.size(),
        g_host_prefetch.skip_events,
        g_host_prefetch.used_bytes / (1024.0 * 1024.0),
        g_host_prefetch.slots.size());
}

static int host_prefetch_env_int(const char *name, int fallback, int lo, int hi) {
    const char *env = std::getenv(name);
    long value = (env && env[0]) ? std::atol(env) : fallback;
    if (value < lo) value = lo;
    if (value > hi) value = hi;
    return (int)value;
}

static size_t host_prefetch_env_mib(const char *name, size_t fallback_mib, size_t lo_mib, size_t hi_mib) {
    const char *env = std::getenv(name);
    size_t value = (env && env[0]) ? (size_t)std::strtoull(env, nullptr, 10) : fallback_mib;
    if (value < lo_mib) value = lo_mib;
    if (value > hi_mib) value = hi_mib;
    return value * 1024ULL * 1024ULL;
}

static bool predictive_host_prefetch_requested() {
    const char *env = std::getenv("GGML_MOE_PREDICTIVE_HOST_PREFETCH");
    return env && env[0] && env[0] != '0';
}

static bool host_prefetch_slot_alloc(host_prefetch_slot &slot, size_t nbytes) {
    if (slot.capacity >= nbytes && slot.host) return true;
    if (slot.host) {
        cudaFreeHost(slot.host);
        slot.host = nullptr;
        slot.capacity = 0;
    }
    const size_t alloc_sz = (size_t)align_up_u64((uint64_t)nbytes, (uint64_t)expert_pack_direct_alignment());
    if (cudaHostAlloc(&slot.host, alloc_sz, cudaHostAllocDefault) != cudaSuccess) {
        slot.host = nullptr;
        slot.capacity = 0;
        return false;
    }
    if (!slot.done && cudaEventCreateWithFlags(&slot.done, cudaEventDisableTiming) != cudaSuccess) {
        cudaFreeHost(slot.host);
        slot.host = nullptr;
        slot.capacity = 0;
        return false;
    }
    slot.capacity = alloc_sz;
    return true;
}

static int host_prefetch_find_free_slot_locked(size_t nbytes) {
    int best = -1;
    for (size_t i = 0; i < g_host_prefetch.slots.size(); ++i) {
        const host_prefetch_slot &slot = g_host_prefetch.slots[i];
        if (slot.in_use) continue;
        if (slot.reserved) continue;
        if (!slot.ready) {
            best = (int)i;
            break;
        }
        if (best < 0) best = (int)i;
    }
    if (best >= 0 && g_host_prefetch.slots[(size_t)best].ready) {
        host_prefetch_slot &slot = g_host_prefetch.slots[(size_t)best];
        g_host_prefetch.ready.erase(host_prefetch_key(slot.tensor, slot.expert_idx, slot.nbytes));
        slot.ready = false;
        slot.reserved = false;
        slot.entry = nullptr;
        uint64_t ready = g_host_prefetch.ready_count.load(std::memory_order_relaxed);
        while (ready > 0 && !g_host_prefetch.ready_count.compare_exchange_weak(
                ready, ready - 1, std::memory_order_relaxed, std::memory_order_relaxed)) {
        }
        ++g_host_prefetch.evicted;
    }
    const size_t alloc_sz = (size_t)align_up_u64((uint64_t)nbytes, (uint64_t)expert_pack_direct_alignment());
    const size_t cur_capacity = best >= 0 ? g_host_prefetch.slots[(size_t)best].capacity : 0;
    const size_t extra = alloc_sz > cur_capacity ? alloc_sz - cur_capacity : 0;
    if (best >= 0 && g_host_prefetch.used_bytes + extra > g_host_prefetch.max_bytes) {
        return -1;
    }
    return best;
}

static void host_prefetch_worker() {
    while (true) {
        batch_route_trace_entry e;
        size_t slot_idx = SIZE_MAX;
        const expert_pack_entry *entry = nullptr;
        {
            std::unique_lock<std::mutex> lk(g_host_prefetch.mu);
            g_host_prefetch.cv.wait(lk, [] {
                return g_host_prefetch.stop ||
                    (g_host_prefetch.enabled &&
                     (!g_host_prefetch.planned.empty() ||
                      g_host_prefetch.cursor < g_host_prefetch.trace.size()));
            });
            if (g_host_prefetch.stop) break;

            ++g_host_prefetch.scan_passes;
            if (!g_host_prefetch.planned.empty()) {
                e = g_host_prefetch.planned.front();
                g_host_prefetch.planned.pop_front();
                const uint64_t key = host_prefetch_key(e.tensor, e.expert_idx, e.expert_bytes);
                g_host_prefetch.planned_queued.erase(key);
                ++g_host_prefetch.planned_dequeued;
            } else {
                const size_t start = std::max(g_host_prefetch.cursor, g_host_prefetch.skip_events);
                const size_t end = std::min(g_host_prefetch.trace.size(), start + g_host_prefetch.lead_events);
                size_t selected = SIZE_MAX;
                for (size_t i = start; i < end; ++i) {
                    const batch_route_trace_entry &candidate = g_host_prefetch.trace[i];
                    const uint64_t key = host_prefetch_key(candidate.tensor, candidate.expert_idx, candidate.expert_bytes);
                    if (profile_pinned_key_contains(batch_key_hash(candidate.tensor, candidate.expert_idx))) {
                        ++g_host_prefetch.profile_pinned_skips;
                        continue;
                    }
                    auto it = g_host_prefetch.ready.find(key);
                    if (it != g_host_prefetch.ready.end()) {
                        const host_prefetch_slot &slot = g_host_prefetch.slots[it->second];
                        if (slot.ready) {
                            ++g_host_prefetch.duplicate_skips;
                        } else {
                            ++g_host_prefetch.reserved_skips;
                        }
                        continue;
                    }
                    selected = i;
                    break;
                }
                if (selected == SIZE_MAX) {
                    g_host_prefetch.cv.wait_for(lk, std::chrono::milliseconds(1));
                    continue;
                }

                e = g_host_prefetch.trace[selected];
                g_host_prefetch.produce_cursor = selected + 1;
            }
            const uint64_t key = host_prefetch_key(e.tensor, e.expert_idx, e.expert_bytes);
            entry = expert_pack_lookup(e.tensor, e.expert_idx, e.expert_bytes);
            if (!entry) {
                ++g_host_prefetch.read_failures;
                continue;
            }
            const int free_slot = host_prefetch_find_free_slot_locked(e.expert_bytes);
            if (free_slot < 0) {
                ++g_host_prefetch.no_slot;
                continue;
            }
            slot_idx = (size_t)free_slot;
            host_prefetch_slot &slot = g_host_prefetch.slots[slot_idx];
            slot.in_use = true;
            slot.reserved = true;
            slot.ready = false;
            slot.nbytes = e.expert_bytes;
            slot.expert_idx = e.expert_idx;
            std::snprintf(slot.tensor, sizeof(slot.tensor), "%s", e.tensor);
            g_host_prefetch.ready[key] = slot_idx;
        }

        bool ok = false;
        host_prefetch_slot *slot_ptr = &g_host_prefetch.slots[slot_idx];
        const size_t old_capacity = slot_ptr->capacity;
        if (host_prefetch_slot_alloc(*slot_ptr, e.expert_bytes)) {
            if (slot_ptr->done) {
                cudaEventSynchronize(slot_ptr->done);
            }
            const expert_pack_source *source = expert_pack_source_for_entry(entry);
            if (source && source->fd_direct >= 0) {
                const bool profile_direct = direct_read_site_profile_path() != nullptr;
                const auto direct_start = profile_direct ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
                ok = expert_pack_direct_read_entry_to_host(entry, slot_ptr->host, e.expert_bytes);
                if (profile_direct) {
                    const auto direct_end = std::chrono::steady_clock::now();
                    direct_read_site_profile_record(
                            "host_prefetch", e.tensor, e.expert_bytes, ok,
                            std::chrono::duration<double, std::milli>(direct_end - direct_start).count());
                }
            } else if (source && source->file) {
                std::lock_guard<std::mutex> lk(g_expert_pack.mu);
                ok = ::fseeko(source->file, (off_t)entry->offset, SEEK_SET) == 0 &&
                    expert_pack_read_exact(source->file, slot_ptr->host, e.expert_bytes);
            }
        } else {
            std::lock_guard<std::mutex> lk(g_host_prefetch.mu);
            ++g_host_prefetch.alloc_failures;
        }

        {
            std::lock_guard<std::mutex> lk(g_host_prefetch.mu);
            host_prefetch_slot &slot = g_host_prefetch.slots[slot_idx];
            if (slot.capacity > old_capacity) {
                g_host_prefetch.used_bytes += slot.capacity - old_capacity;
            } else if (slot.capacity < old_capacity) {
                const size_t delta = old_capacity - slot.capacity;
                g_host_prefetch.used_bytes = delta < g_host_prefetch.used_bytes ? g_host_prefetch.used_bytes - delta : 0;
            }
            if (ok) {
                slot.entry = entry;
                slot.nbytes = e.expert_bytes;
                slot.expert_idx = e.expert_idx;
                std::snprintf(slot.tensor, sizeof(slot.tensor), "%s", e.tensor);
                slot.reserved = false;
                slot.ready = true;
                g_host_prefetch.ready[host_prefetch_key(slot.tensor, slot.expert_idx, slot.nbytes)] = slot_idx;
                g_host_prefetch.ready_count.fetch_add(1, std::memory_order_release);
                ++g_host_prefetch.submitted;
            } else {
                slot.ready = false;
                slot.reserved = false;
                slot.entry = nullptr;
                g_host_prefetch.ready.erase(host_prefetch_key(e.tensor, e.expert_idx, e.expert_bytes));
                ++g_host_prefetch.read_failures;
            }
            slot.in_use = false;
        }
    }
}

static void host_prefetch_shutdown() {
    {
        std::lock_guard<std::mutex> lk(g_host_prefetch.mu);
        g_host_prefetch.stop = true;
        g_host_prefetch.cv.notify_all();
    }
    if (g_host_prefetch.worker.joinable()) {
        g_host_prefetch.worker.join();
    }
    for (host_prefetch_slot &slot : g_host_prefetch.slots) {
        if (slot.host) {
            if (slot.done) {
                cudaEventSynchronize(slot.done);
            }
            cudaFreeHost(slot.host);
            slot.host = nullptr;
        }
        if (slot.done) {
            cudaEventDestroy(slot.done);
            slot.done = nullptr;
        }
    }
}

static void host_prefetch_init_once() {
    if (g_host_prefetch.inited) return;
    std::lock_guard<std::mutex> lk(g_host_prefetch.mu);
    if (g_host_prefetch.inited) return;
    const char *path = std::getenv("GGML_MOE_HOST_PREFETCH");
    const char *planned_env = std::getenv("GGML_MOE_PLANNED_HOST_PREFETCH");
    const bool predictive_env = predictive_host_prefetch_requested();
    g_host_prefetch.planned_enabled = planned_env && planned_env[0] && planned_env[0] != '0';
    if ((!path || !path[0]) && !g_host_prefetch.planned_enabled && !predictive_env) {
        g_host_prefetch.inited = true;
        return;
    }
    if (path && path[0] && !load_route_trace_csv(path, g_host_prefetch.trace, "host prefetch")) {
        g_host_prefetch.inited = true;
        return;
    }
    const int slots = host_prefetch_env_int("GGML_MOE_HOST_PREFETCH_SLOTS", 64, 1, 512);
    g_host_prefetch.lead_events = (size_t)host_prefetch_env_int("GGML_MOE_HOST_PREFETCH_LEAD_EVENTS", 2048, 1, 32768);
    g_host_prefetch.skip_events = (size_t)host_prefetch_env_int("GGML_MOE_HOST_PREFETCH_SKIP_EVENTS", 0, 0, 100000000);
    if (g_host_prefetch.skip_events > g_host_prefetch.trace.size()) {
        g_host_prefetch.skip_events = g_host_prefetch.trace.size();
    }
    g_host_prefetch.produce_cursor = g_host_prefetch.skip_events;
    g_host_prefetch.max_bytes = host_prefetch_env_mib("GGML_MOE_HOST_PREFETCH_MAX_MIB", 512, 16, 8192);
    g_host_prefetch.slots.resize((size_t)slots);
    g_host_prefetch.enabled = true;
    g_host_prefetch.inited = true;
    std::atexit(host_prefetch_report_atexit);
    std::atexit(host_prefetch_shutdown);
    g_host_prefetch.worker = std::thread(host_prefetch_worker);
    g_host_prefetch.cv.notify_all();
    std::fprintf(stderr,
        "[moe_stream_batch] host prefetch: loaded %zu events from %s lead_events=%zu skip_events=%zu slots=%d max=%.2f MiB planned=%d predictive=%d\n",
        g_host_prefetch.trace.size(), (path && path[0]) ? path : "(none)",
        g_host_prefetch.lead_events, g_host_prefetch.skip_events, slots,
        g_host_prefetch.max_bytes / (1024.0 * 1024.0),
        g_host_prefetch.planned_enabled ? 1 : 0,
        predictive_env ? 1 : 0);
}

static void host_prefetch_on_route(const char *tensor_name, int expert_idx, size_t expert_bytes) {
    host_prefetch_init_once();
    if (!g_host_prefetch.enabled || !tensor_name || !tensor_name[0]) return;
    std::lock_guard<std::mutex> lk(g_host_prefetch.mu);
    ++g_host_prefetch.calls;
    if (g_host_prefetch.cursor < g_host_prefetch.trace.size() &&
            trace_entry_matches(g_host_prefetch.trace[g_host_prefetch.cursor], tensor_name, expert_idx, expert_bytes)) {
        ++g_host_prefetch.cursor;
        ++g_host_prefetch.matched;
    } else {
        const size_t scan_end = std::min(g_host_prefetch.trace.size(), g_host_prefetch.cursor + (size_t)128);
        for (size_t i = g_host_prefetch.cursor; i < scan_end; ++i) {
            if (trace_entry_matches(g_host_prefetch.trace[i], tensor_name, expert_idx, expert_bytes)) {
                g_host_prefetch.cursor = i + 1;
                ++g_host_prefetch.matched;
                ++g_host_prefetch.resync;
                break;
            }
        }
    }
    if (g_host_prefetch.produce_cursor < g_host_prefetch.cursor) {
        g_host_prefetch.produce_cursor = g_host_prefetch.cursor;
    }
    g_host_prefetch.cv.notify_one();
}









static bool predictive_prefetch_parse_layer_list(const char *env, bool *layers_all, bool layer_enabled[128]) {
    if (!env || !env[0]) return false;
    if (std::strcmp(env, "all") == 0 || std::strcmp(env, "*") == 0) {
        *layers_all = true;
        return true;
    }
    char buf[512];
    std::snprintf(buf, sizeof(buf), "%s", env);
    bool any = false;
    char *save = nullptr;
    for (char *tok = ::strtok_r(buf, ",;:", &save); tok; tok = ::strtok_r(nullptr, ",;:", &save)) {
        while (*tok == ' ' || *tok == '\t') ++tok;
        if (!*tok) continue;
        char *end = nullptr;
        long layer = std::strtol(tok, &end, 10);
        if (end == tok || layer < 0 || layer >= 128) continue;
        layer_enabled[layer] = true;
        any = true;
    }
    return any;
}





struct predictive_prefetch_candidate {
    int expert = -1;
    int count = 0;
    int recent = 0;
};









static bool host_prefetch_copy_h2d(
        const expert_pack_entry *pack_entry,
        const char *tensor_name,
        int expert_idx,
        void *dst,
        size_t sz,
        cudaStream_t st) {
    host_prefetch_init_once();
    if (!g_host_prefetch.enabled || !pack_entry || !tensor_name || !tensor_name[0]) return false;
    if (g_host_prefetch.ready_count.load(std::memory_order_acquire) == 0) {
        g_host_prefetch.empty_misses.fetch_add(1, std::memory_order_relaxed);
        return false;
    }
    void *host = nullptr;
    size_t slot_idx = SIZE_MAX;
    {
        std::lock_guard<std::mutex> lk(g_host_prefetch.mu);
        const uint64_t key = host_prefetch_key(tensor_name, expert_idx, sz);
        auto it = g_host_prefetch.ready.find(key);
        if (it == g_host_prefetch.ready.end()) {
            ++g_host_prefetch.misses;
            return false;
        }
        host_prefetch_slot &slot = g_host_prefetch.slots[it->second];
        if (!slot.ready || slot.nbytes != sz || !slot.host) {
            if (slot.reserved) {
                ++g_host_prefetch.reserved_skips;
            } else {
                g_host_prefetch.ready.erase(it);
            }
            ++g_host_prefetch.misses;
            return false;
        }
        slot_idx = it->second;
        host = slot.host;
        slot.in_use = true;
        slot.ready = false;
        slot.reserved = false;
        slot.entry = nullptr;
        g_host_prefetch.ready.erase(it);
        uint64_t ready = g_host_prefetch.ready_count.load(std::memory_order_relaxed);
        while (ready > 0 && !g_host_prefetch.ready_count.compare_exchange_weak(
                ready, ready - 1, std::memory_order_acquire, std::memory_order_relaxed)) {
        }
        ++g_host_prefetch.hits;
    }
    const bool ok = host && cudaMemcpyAsync(dst, host, sz, cudaMemcpyHostToDevice, st) == cudaSuccess;
    {
        std::lock_guard<std::mutex> lk(g_host_prefetch.mu);
        if (slot_idx < g_host_prefetch.slots.size()) {
            if (ok && g_host_prefetch.slots[slot_idx].done) {
                cudaEventRecord(g_host_prefetch.slots[slot_idx].done, st);
            }
            g_host_prefetch.slots[slot_idx].in_use = false;
        }
    }
    return ok;
}

static std::once_flag g_ram_tier_once;

static bool expert_pack_direct_read_entry_to_host(const expert_pack_entry *entry, void *dst, size_t sz);

static bool ram_tier_dynamic_requested() {
    return expert_pack_env_bool("GGML_MOE_RAM_TIER_DYNAMIC", false);
}

static bool ram_tier_dynamic_profile_seed_requested() {
    return expert_pack_env_bool(
            "GGML_MOE_STREAM_HARD1_ROLLING_V2_RAM_TIER_PROFILE_SEED",
            false);
}

static bool ram_tier_dynamic_profile_seed_read(
        size_t slot,
        size_t entry_idx,
        bool reload) {
    if (slot >= g_expert_pack.ram_tier_dynamic_slot_entry.size() ||
            entry_idx >= g_expert_pack.entries.size() ||
            g_expert_pack.ram_tier_base == nullptr ||
            g_expert_pack.ram_tier_dynamic_slot_bytes == 0) {
        ++g_expert_pack.ram_tier_dynamic_profile_seed_read_failures;
        return false;
    }

    const expert_pack_entry &entry = g_expert_pack.entries[entry_idx];
    if (entry.nbytes == 0 ||
            entry.nbytes > g_expert_pack.ram_tier_dynamic_slot_bytes) {
        ++g_expert_pack.ram_tier_dynamic_profile_seed_read_failures;
        return false;
    }
    void *dst = (char *)g_expert_pack.ram_tier_base +
        slot * g_expert_pack.ram_tier_dynamic_slot_bytes;
    if (expert_pack_direct_read_entry_to_host(
                &entry, dst, (size_t)entry.nbytes)) {
        g_expert_pack.ram_tier_dynamic_profile_seed_direct_bytes.fetch_add(
                (uint64_t)entry.nbytes);
        if (reload) {
            g_expert_pack.ram_tier_dynamic_profile_seed_reload_bytes.fetch_add(
                    (uint64_t)entry.nbytes);
        }
        return true;
    }

    expert_pack_source *source = expert_pack_source_for_entry(&entry);
    bool buffered_ok = false;
    if (source && source->file) {
        std::lock_guard<std::mutex> lk(g_expert_pack.mu);
        buffered_ok = ::fseeko(source->file, (off_t)entry.offset, SEEK_SET) == 0 &&
            expert_pack_read_exact(source->file, dst, (size_t)entry.nbytes);
    }
    if (buffered_ok) {
        g_expert_pack.ram_tier_dynamic_profile_seed_buffered_bytes.fetch_add(
                (uint64_t)entry.nbytes);
        if (reload) {
            g_expert_pack.ram_tier_dynamic_profile_seed_reload_bytes.fetch_add(
                    (uint64_t)entry.nbytes);
        }
        return true;
    }

    ++g_expert_pack.ram_tier_dynamic_profile_seed_read_failures;
    return false;
}

static void ram_tier_dynamic_profile_seed_init() {
    if (!ram_tier_dynamic_profile_seed_requested()) {
        return;
    }

    std::vector<profile_entry> seed_profile;
    const char *profile_path = std::getenv("GGML_MOE_RAM_TIER_PROFILE");
    if (profile_path && profile_path[0]) {
        (void)load_profile_file(
                profile_path, seed_profile, "dynamic RAM tier profile seed");
    } else {
        load_profile_once();
        std::lock_guard<std::mutex> lk(g_profile_mu);
        seed_profile = g_profile;
    }

    const size_t n_slots =
        g_expert_pack.ram_tier_dynamic_slot_entry.size();
    g_expert_pack.ram_tier_dynamic_profile_seed_entry.assign(
            n_slots, SIZE_MAX);
    g_expert_pack.ram_tier_dynamic_profile_seed_dirty.assign(n_slots, 0);
    if (seed_profile.empty()) {
        std::fprintf(stderr,
                "[moe_stream_batch] dynamic RAM tier profile seed: no profile rows, skipping\n");
        return;
    }

    // The unified cache deliberately gives host slots only to up/gate entries;
    // do the same for the seed so no slot is occupied by an unreachable down
    // entry.  Profile order is hottest first.
    const bool upgate_only = expert_pack_env_bool(
            "GGML_MOE_UNIFIED_DYNAMIC_CACHE", false);
    std::unordered_set<size_t> selected;
    selected.reserve(n_slots);
    size_t loaded = 0;
    uint64_t loaded_bytes = 0;
    for (const profile_entry &pe : seed_profile) {
        if (loaded >= n_slots) {
            break;
        }
        if (upgate_only &&
                std::strstr(pe.tensor, ".ffn_up_exps.") == nullptr &&
                std::strstr(pe.tensor, ".ffn_gate_exps.") == nullptr) {
            continue;
        }
        const expert_pack_entry *entry =
            expert_pack_lookup_any_size(pe.tensor, pe.expert_idx);
        if (!entry || entry->nbytes == 0 ||
                entry->nbytes > g_expert_pack.ram_tier_dynamic_slot_bytes) {
            continue;
        }
        const size_t entry_idx = (size_t)(entry - g_expert_pack.entries.data());
        if (entry_idx >= g_expert_pack.entries.size() ||
                !selected.insert(entry_idx).second) {
            continue;
        }
        if (!ram_tier_dynamic_profile_seed_read(
                    loaded, entry_idx, false)) {
            continue;
        }

        const size_t offset =
            loaded * g_expert_pack.ram_tier_dynamic_slot_bytes;
        g_expert_pack.ram_tier_dynamic_profile_seed_entry[loaded] =
            entry_idx;
        g_expert_pack.ram_tier_dynamic_slot_entry[loaded] = entry_idx;
        g_expert_pack.ram_tier_index[entry_idx] = {
            offset, (size_t)entry->nbytes};
        loaded_bytes += (uint64_t)entry->nbytes;
        ++loaded;
    }

    for (size_t slot = 0; slot < loaded; ++slot) {
        g_expert_pack.ram_tier_dynamic_slot_used[slot] = loaded - slot;
    }
    g_expert_pack.ram_tier_dynamic_clock = loaded;
    g_expert_pack.ram_tier_dynamic_next_empty = loaded;
    g_expert_pack.ram_tier_dynamic_profile_seed_entries.store(loaded);
    std::fprintf(stderr,
            "[moe_stream_batch] dynamic RAM tier profile seed: enabled "
            "entries=%zu bytes=%lu slots=%zu upgate_only=%d failures=%lu\n",
            loaded,
            (unsigned long)loaded_bytes,
            n_slots,
            upgate_only ? 1 : 0,
            (unsigned long)g_expert_pack.
                ram_tier_dynamic_profile_seed_read_failures.load());
}

static bool ram_tier_dynamic_init(size_t budget) {
    if (g_expert_pack.q4_colibri || g_expert_pack.entries.empty()) {
        std::fprintf(stderr,
                "[moe_stream_batch] dynamic RAM tier: legacy tensor pack required, skipping\n");
        return false;
    }

    size_t slot_bytes = 0;
    size_t min_entry_bytes = SIZE_MAX;
    for (const expert_pack_entry &entry : g_expert_pack.entries) {
        if (entry.nbytes == 0) {
            std::fprintf(stderr,
                    "[moe_stream_batch] dynamic RAM tier: invalid expert entry size, skipping\n");
            return false;
        }
        const size_t entry_bytes = (size_t)entry.nbytes;
        slot_bytes = std::max(slot_bytes, entry_bytes);
        min_entry_bytes = std::min(min_entry_bytes, entry_bytes);
    }

    const bool whole_expert = hard1_structure_io_requested();
    if (whole_expert) {
        if (slot_bytes > SIZE_MAX / 3 || min_entry_bytes > SIZE_MAX / 3) {
            return false;
        }
        slot_bytes *= 3;
        min_entry_bytes *= 3;
    }

    const size_t n_slots = budget / slot_bytes;
    if (n_slots == 0 || n_slots > SIZE_MAX / slot_bytes) {
        std::fprintf(stderr,
                "[moe_stream_batch] dynamic RAM tier: budget %zu MiB is smaller than one tensor\n",
                budget / (1024 * 1024));
        return false;
    }
    const size_t mapped_bytes = n_slots * slot_bytes;
    void *region = ::mmap(nullptr, mapped_bytes, PROT_READ | PROT_WRITE,
                          MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (region == MAP_FAILED) {
        std::fprintf(stderr,
                "[moe_stream_batch] dynamic RAM tier: mmap %zu MiB failed\n",
                mapped_bytes / (1024 * 1024));
        return false;
    }

    g_expert_pack.ram_tier_index.assign(
            g_expert_pack.entries.size(), expert_pack_state::ram_tier_entry{});
    g_expert_pack.ram_tier_dynamic_slot_entry.assign(n_slots, SIZE_MAX);
    g_expert_pack.ram_tier_dynamic_whole_expert_entry.assign(
            n_slots, expert_pack_state::ram_tier_whole_expert_entry{});
    g_expert_pack.ram_tier_dynamic_slot_used.assign(n_slots, 0);
    g_expert_pack.ram_tier_dynamic_slot_done.assign(n_slots, nullptr);
    g_expert_pack.ram_tier_dynamic_slot_external_done.assign(
            n_slots, nullptr);
    g_expert_pack.ram_tier_dynamic_slot_pending.assign(n_slots, 0);
    g_expert_pack.ram_tier_dynamic_frequency.assign(g_expert_pack.entries.size(), 0);
    if (expert_pack_env_bool(
            "GGML_MOE_PREFILL_CACHE_HANDOFF", false)) {
        g_expert_pack.ram_tier_dynamic_handoff_frequency.assign(
                g_expert_pack.entries.size(), 0);
    }
    g_expert_pack.ram_tier_dynamic_observed_miss_pending.assign(
            g_expert_pack.entries.size(), 0);
    g_expert_pack.ram_tier_dynamic_vram_slot.assign(
            g_expert_pack.entries.size(), -1);
    g_expert_pack.ram_tier_dynamic_slot_bytes = slot_bytes;
    g_expert_pack.ram_tier_dynamic_next_empty = 0;
    g_expert_pack.ram_tier_dynamic_clock = 0;
    g_expert_pack.ram_tier_base = region;
    g_expert_pack.ram_tier_bytes = mapped_bytes;
    g_expert_pack.ram_tier_dynamic = true;
    g_expert_pack.ram_tier_dynamic_whole_expert = whole_expert;

    const char *pin_mib_env = std::getenv("GGML_MOE_RAM_TIER_PIN_MIB");
    const bool pin_budget_set = pin_mib_env && pin_mib_env[0];
    const size_t pin_budget = pin_budget_set ?
        (size_t)std::atol(pin_mib_env) * 1024ULL * 1024ULL : mapped_bytes;
    size_t pin_bytes = 0;
    if (expert_pack_env_bool("GGML_MOE_RAM_TIER_PIN", true)) {
        pin_bytes = std::min(mapped_bytes, (pin_budget / slot_bytes) * slot_bytes);
        if (pin_bytes > 0) {
            const cudaError_t err =
                cudaHostRegister(region, pin_bytes, cudaHostRegisterDefault);
            if (err == cudaSuccess) {
                g_expert_pack.ram_tier_pinned_bytes = pin_bytes;
                std::fprintf(stderr,
                        "[moe_stream_batch] dynamic RAM tier: cudaHostRegister "
                        "succeeded (%.2f MiB pinned prefix, %zu slots, %.2f MiB resident)\n",
                        pin_bytes / (1024.0 * 1024.0),
                        pin_bytes / slot_bytes,
                        mapped_bytes / (1024.0 * 1024.0));
            } else {
                pin_bytes = 0;
                std::fprintf(stderr,
                        "[moe_stream_batch] dynamic RAM tier: cudaHostRegister "
                        "failed (%s), using unpinned path\n",
                        cudaGetErrorString(err));
            }
        } else {
            std::fprintf(stderr,
                    "[moe_stream_batch] dynamic RAM tier: cudaHostRegister "
                    "prefix budget is 0, using unpinned path (%.2f MiB)\n",
                    mapped_bytes / (1024.0 * 1024.0));
        }
    } else {
        std::fprintf(stderr,
                "[moe_stream_batch] dynamic RAM tier: cudaHostRegister "
                "disabled, using unpinned path (%.2f MiB)\n",
                mapped_bytes / (1024.0 * 1024.0));
    }

    if (!whole_expert) {
        ram_tier_dynamic_profile_seed_init();
    }

    std::fprintf(stderr,
            "[moe_stream_batch] dynamic RAM tier: enabled slots=%zu slot=%.2f MiB min_entry=%.2f MiB "
            "capacity=%.2f MiB admission=%u aging_passes=%u "
            "pinned=%.2f MiB pinned_slots=%zu unpinned=%d whole_expert=%d\n",
            n_slots,
            slot_bytes / (1024.0 * 1024.0),
            min_entry_bytes / (1024.0 * 1024.0),
            mapped_bytes / (1024.0 * 1024.0),
            ram_tier_dynamic_host_admission_threshold(),
            RAM_TIER_DYNAMIC_AGING_PASSES,
            g_expert_pack.ram_tier_pinned_bytes / (1024.0 * 1024.0),
            g_expert_pack.ram_tier_pinned_bytes / slot_bytes,
            g_expert_pack.ram_tier_pinned_bytes == 0 ? 1 : 0,
            whole_expert ? 1 : 0);
    return true;
}

static bool unified_dynamic_cache_requested() {
    return expert_pack_env_bool("GGML_MOE_UNIFIED_DYNAMIC_CACHE", false);
}

static bool unified_dynamic_cache_enabled() {
    return unified_dynamic_cache_requested() &&
        g_expert_pack.ram_tier_dynamic;
}

static bool unified_dynamic_host_inclusive_enabled() {
    static const bool enabled = expert_pack_env_bool(
        "GGML_MOE_STREAM_HARD1_ROLLING_V2_RAM_TIER_INCLUSIVE", false);
    if (enabled) {
        static std::atomic<bool> reported{false};
        if (!reported.exchange(true)) {
            std::fprintf(stderr,
                    "[moe_stream_batch] unified dynamic RAM tier keeps inclusive VRAM copies\n");
        }
    }
    return enabled;
}

static bool unified_dynamic_upgate_tensor(const char *tensor_name) {
    return tensor_name &&
        (std::strstr(tensor_name, ".ffn_up_exps.") ||
         std::strstr(tensor_name, ".ffn_gate_exps."));
}

static int unified_dynamic_cache_id_for_tensor(
        const char *tensor_name) {
    if (tensor_name &&
            std::strstr(tensor_name, ".ffn_down_exps.")) {
        return 0;
    }
    return unified_dynamic_upgate_tensor(tensor_name) ? 1 : -1;
}

static bool unified_dynamic_upgate_entry(const expert_pack_entry *entry) {
    return entry && unified_dynamic_upgate_tensor(entry->tensor);
}

static size_t unified_dynamic_entry_index(
        const char *tensor_name,
        int expert_idx,
        size_t expert_bytes) {
    if (!unified_dynamic_cache_enabled() ||
            unified_dynamic_cache_id_for_tensor(tensor_name) < 0) {
        return SIZE_MAX;
    }
    const expert_pack_entry *entry =
        expert_pack_lookup_impl(tensor_name, expert_idx, expert_bytes, false);
    if (!entry) {
        return SIZE_MAX;
    }
    return (size_t)(entry - g_expert_pack.entries.data());
}

static size_t unified_dynamic_vram_scratch_slots(
        const batch_vram_cache *cache) {
    if (!cache || cache->n_slots <= 1) {
        return 0;
    }
    const char *env =
        std::getenv("GGML_MOE_UNIFIED_DYNAMIC_VRAM_SCRATCH_SLOTS");
    size_t slots = env && env[0] ?
        (size_t)std::strtoull(env, nullptr, 10) :
        (cache == &g_bcaches[0] ? 16 : 32);
    if (slots < 1) {
        slots = 1;
    }
    if (slots >= (size_t)cache->n_slots) {
        slots = (size_t)cache->n_slots - 1;
    }
    return slots;
}

static bool unified_dynamic_invalidate_host_entry_locked(size_t entry_idx) {
    // A whole-expert RAM slot backs three adjacent VRAM role slots.  The
    // unified cache's role-granular promotion callback fires once per role;
    // invalidating the first role there would discard the shared host group
    // while the other two roles still refer to it.  Keep the group inclusive
    // and let its own group-level admission/aging policy choose the victim.
    if (g_expert_pack.ram_tier_dynamic_whole_expert) {
        return false;
    }
    if (unified_dynamic_host_inclusive_enabled()) {
        return false;
    }
    if (entry_idx >= g_expert_pack.ram_tier_index.size() ||
            g_expert_pack.ram_tier_dynamic_slot_bytes == 0) {
        return false;
    }
    const expert_pack_state::ram_tier_entry resident =
        g_expert_pack.ram_tier_index[entry_idx];
    if (resident.nbytes == 0 ||
            resident.offset %
                g_expert_pack.ram_tier_dynamic_slot_bytes != 0) {
        return false;
    }
    const size_t host_slot =
        resident.offset / g_expert_pack.ram_tier_dynamic_slot_bytes;
    if (host_slot >= g_expert_pack.ram_tier_dynamic_slot_entry.size() ||
            g_expert_pack.ram_tier_dynamic_slot_entry[host_slot] !=
                entry_idx) {
        return false;
    }
    g_expert_pack.ram_tier_index[entry_idx] = {};
    g_expert_pack.ram_tier_dynamic_slot_entry[host_slot] = SIZE_MAX;
    g_expert_pack.ram_tier_dynamic_slot_used[host_slot] = 0;
    ++g_expert_pack.unified_host_invalidations;
    return true;
}

static void unified_dynamic_vram_slot_cleared(
        batch_vram_cache *cache,
        int slot) {
    if (!unified_dynamic_cache_enabled() ||
            (cache != &g_bcaches[0] &&
             cache != &g_bcaches[1]) ||
            slot < 0 ||
            slot >= cache->n_slots ||
            !cache->slot_dynamic_admitted[slot]) {
        return;
    }
    const size_t entry_idx = cache->slot_pack_entry[slot];
    std::lock_guard<std::mutex> lk(
            g_expert_pack.ram_tier_dynamic_mu);
    if (entry_idx <
            g_expert_pack.ram_tier_dynamic_vram_slot.size() &&
            g_expert_pack.ram_tier_dynamic_vram_slot[entry_idx] ==
                slot) {
        g_expert_pack.ram_tier_dynamic_vram_slot[entry_idx] = -1;
    }
}





static bool unified_dynamic_consume_observed_miss_locked(
        size_t entry_idx) {
    if (entry_idx >=
            g_expert_pack.ram_tier_dynamic_observed_miss_pending.size()) {
        return false;
    }
    uint32_t &pending =
        g_expert_pack.ram_tier_dynamic_observed_miss_pending[entry_idx];
    if (pending == 0) {
        return false;
    }
    --pending;
    return true;
}



struct unified_dynamic_vram_plan {
    bool enabled = false;
    bool admit = false;
    int slot = -1;
    size_t entry_idx = SIZE_MAX;
};

static unified_dynamic_vram_plan unified_dynamic_plan_vram_insert(
        batch_vram_cache *cache,
        const char *tensor_name,
        int expert_idx,
        size_t expert_bytes,
        const int *avoid_slots,
        int n_avoid_slots) {
    unified_dynamic_vram_plan plan;
    if (!unified_dynamic_cache_enabled() ||
            (cache != &g_bcaches[0] &&
             cache != &g_bcaches[1])) {
        return plan;
    }
    plan.entry_idx = unified_dynamic_entry_index(
            tensor_name, expert_idx, expert_bytes);
    if (plan.entry_idx == SIZE_MAX) {
        return plan;
    }
    plan.enabled = true;

    std::lock_guard<std::mutex> lk(
            g_expert_pack.ram_tier_dynamic_mu);
    if (plan.entry_idx >=
            g_expert_pack.ram_tier_dynamic_frequency.size()) {
        plan.enabled = false;
        return plan;
    }

    const uint32_t incoming_frequency =
        unified_dynamic_effective_frequency_locked(plan.entry_idx);
    const size_t admitted_limit =
        (size_t)cache->n_slots -
        unified_dynamic_vram_scratch_slots(cache);
    size_t admitted = 0;
    uint64_t scratch_oldest = UINT64_MAX;
    int victim_slot = -1;
    uint32_t victim_frequency = UINT32_MAX;
    uint64_t victim_used = UINT64_MAX;

    for (int i = 0; i < cache->n_slots; ++i) {
        if (cache->slot_dynamic_admitted[i]) {
            ++admitted;
            if (batch_slot_is_avoided(
                        i, avoid_slots, n_avoid_slots) ||
                    cache->slot_filling[i] ||
                    cache->slot_pending[i] ||
                    cache->slot_state[i] ==
                        q4_colibri_slot_state::reserved ||
                    cache->slot_state[i] ==
                        q4_colibri_slot_state::reading ||
                    cache->slot_pinned[i]) {
                continue;
            }
            const size_t victim_entry =
                cache->slot_pack_entry[i];
            if (victim_entry >=
                    g_expert_pack.ram_tier_dynamic_frequency.size()) {
                continue;
            }
            const uint32_t frequency =
                unified_dynamic_effective_frequency_locked(victim_entry);
            if (victim_slot < 0 ||
                    frequency < victim_frequency ||
                    (frequency == victim_frequency &&
                     cache->slot_used[i] < victim_used)) {
                victim_slot = i;
                victim_frequency = frequency;
                victim_used = cache->slot_used[i];
            }
            continue;
        }
        if (batch_slot_is_avoided(i, avoid_slots, n_avoid_slots) ||
                cache->slot_filling[i] ||
                cache->slot_pending[i] ||
                cache->slot_state[i] ==
                    q4_colibri_slot_state::reserved ||
                cache->slot_state[i] ==
                    q4_colibri_slot_state::reading ||
                cache->slot_pinned[i]) {
            continue;
        }
        if (cache->slot_key[i] == 0) {
            plan.slot = i;
            scratch_oldest = 0;
            continue;
        }
        if (plan.slot < 0 ||
                cache->slot_used[i] < scratch_oldest) {
            plan.slot = i;
            scratch_oldest = cache->slot_used[i];
        }
    }
    if (plan.slot < 0) {
        return plan;
    }

    plan.admit =
        incoming_frequency >=
            RAM_TIER_DYNAMIC_ADMISSION_THRESHOLD &&
        (admitted < admitted_limit ||
         (victim_slot >= 0 &&
          incoming_frequency > victim_frequency));
    if (plan.admit && admitted >= admitted_limit) {
        const size_t victim_entry =
            cache->slot_pack_entry[victim_slot];
        cache->slot_dynamic_admitted[victim_slot] = false;
        if (victim_entry <
                g_expert_pack.ram_tier_dynamic_vram_slot.size() &&
                g_expert_pack.ram_tier_dynamic_vram_slot[victim_entry] ==
                    victim_slot) {
            g_expert_pack.ram_tier_dynamic_vram_slot[victim_entry] = -1;
        }
        ++g_expert_pack.unified_vram_evictions;
    }
    if (plan.admit) {
        ++g_expert_pack.unified_vram_admissions;
    } else {
        ++g_expert_pack.unified_vram_bypasses;
    }
    return plan;
}

static void unified_dynamic_register_vram_slot(
        batch_vram_cache *cache,
        int slot,
        const unified_dynamic_vram_plan &plan) {
    if (!plan.enabled ||
            (cache != &g_bcaches[0] &&
             cache != &g_bcaches[1]) ||
            slot < 0 ||
            slot >= cache->n_slots) {
        return;
    }
    cache->slot_pack_entry[slot] = plan.entry_idx;
    cache->slot_dynamic_admitted[slot] = plan.admit;
    if (!plan.admit) {
        return;
    }
    std::lock_guard<std::mutex> lk(
            g_expert_pack.ram_tier_dynamic_mu);
    if (plan.entry_idx <
            g_expert_pack.ram_tier_dynamic_vram_slot.size()) {
        g_expert_pack.ram_tier_dynamic_vram_slot[plan.entry_idx] =
            slot;
    }
}

static bool unified_dynamic_destination_owns_entry_locked(
        size_t entry_idx,
        const void *dst,
        size_t bytes) {
    if (!unified_dynamic_cache_enabled() ||
            entry_idx >=
                g_expert_pack.ram_tier_dynamic_vram_slot.size()) {
        return false;
    }
    const int slot =
        g_expert_pack.ram_tier_dynamic_vram_slot[entry_idx];
    const int cache_id = unified_dynamic_cache_id_for_tensor(
            g_expert_pack.entries[entry_idx].tensor);
    if (cache_id < 0) {
        return false;
    }
    batch_vram_cache *cache = &g_bcaches[cache_id];
    if (slot < 0 ||
            slot >= cache->n_slots ||
            !cache->pool ||
            !cache->slot_dynamic_admitted[slot] ||
            cache->slot_pack_entry[slot] != entry_idx ||
            bytes > cache->slot_sz) {
        return false;
    }
    const void *expected =
        (const char *)cache->pool +
        (size_t)slot * cache->slot_sz;
    return dst == expected;
}





static void ram_tier_init() {
    if (!g_expert_pack.enabled) return;
    const char *ram_tier_env = std::getenv("GGML_MOE_RAM_TIER_MIB");
    if (!ram_tier_env || !ram_tier_env[0] || ram_tier_env[0] == '0') return;
    const size_t budget = (size_t)std::atol(ram_tier_env) * 1024ULL * 1024ULL;
    if (budget == 0) return;

    // Request tracking can initialize this tier before model-shape dispatch.
    // Let common-adapter runs opt out without consuming a shape-based decision
    // in call_once before the local adapter can be selected.
    if (!expert_pack_env_bool("GGML_MOE_RAM_TIER_LOCAL", true)) {
        std::fprintf(stderr,
                "[moe_stream_batch] local RAM tier: disabled by GGML_MOE_RAM_TIER_LOCAL=0\n");
        return;
    }

    if (ram_tier_dynamic_requested()) {
        (void)ram_tier_dynamic_init(budget);
        return;
    }

    std::vector<profile_entry> ram_profile;
    const char *ram_profile_path = std::getenv("GGML_MOE_RAM_TIER_PROFILE");
    if (ram_profile_path && ram_profile_path[0]) {
        if (!load_profile_file(ram_profile_path, ram_profile, "RAM tier profile")) {
            std::fprintf(stderr, "[moe_stream_batch] RAM tier: no RAM tier profile loaded, skipping\n");
            return;
        }
    } else {
        load_profile_once();
        ram_profile = g_profile;
    }
    if (ram_profile.empty()) {
        std::fprintf(stderr, "[moe_stream_batch] RAM tier: no profile loaded, skipping\n");
        return;
    }

    // Skip the top entries that are already in the VRAM cache.
    // The VRAM cache preloads ~n_slots entries per tensor from the profile.
    // Default skip = 500 (approximate VRAM slot count); override with GGML_MOE_RAM_TIER_SKIP.
    size_t skip = 500;
    const char *skip_env = std::getenv("GGML_MOE_RAM_TIER_SKIP");
    if (skip_env && skip_env[0]) skip = (size_t)std::atol(skip_env);

    g_expert_pack.ram_tier_index.resize(g_expert_pack.entries.size());
    void *region = ::mmap(nullptr, budget, PROT_READ | PROT_WRITE,
                          MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (region == MAP_FAILED) {
        std::fprintf(stderr, "[moe_stream_batch] RAM tier: mmap %zu MiB failed\n", budget / (1024*1024));
        return;
    }
    g_expert_pack.ram_tier_base = region;
    g_expert_pack.ram_tier_bytes = budget;
    const char *pin_mib_env = std::getenv("GGML_MOE_RAM_TIER_PIN_MIB");
    const bool pin_budget_set = pin_mib_env && pin_mib_env[0];
    const size_t pin_budget = pin_budget_set ?
        (size_t)std::atol(pin_mib_env) * 1024ULL * 1024ULL : budget;

    size_t loaded = 0, n_loaded = 0, n_skipped = 0, pin_prefix_bytes = 0, pin_prefix_entries = 0;
    const bool direct_preload = expert_pack_env_bool("GGML_MOE_RAM_TIER_PRELOAD_DIRECT", false);
    int preload_threads = 1;
    const char *preload_threads_env = std::getenv("GGML_MOE_RAM_TIER_PRELOAD_THREADS");
    if (preload_threads_env && preload_threads_env[0]) {
        preload_threads = std::max(1, std::atoi(preload_threads_env));
    }

    struct ram_tier_load_job {
        size_t pack_index;
        size_t offset;
        const expert_pack_entry *entry;
        bool ok;
    };
    std::vector<ram_tier_load_job> parallel_jobs;

    for (const profile_entry &pe : ram_profile) {
        if (loaded >= budget) break;
        if (n_skipped < skip) { ++n_skipped; continue; }
        size_t lo2 = 0, hi2 = g_expert_pack.entries.size();
        while (lo2 < hi2) {
            size_t mid2 = lo2 + (hi2 - lo2) / 2;
            int cmp2 = expert_pack_entry_cmp(g_expert_pack.entries[mid2], pe.tensor, pe.expert_idx, pe.expert_bytes);
            if (cmp2 < 0) lo2 = mid2 + 1; else hi2 = mid2;
        }
        if (lo2 >= g_expert_pack.entries.size() ||
            expert_pack_entry_cmp(g_expert_pack.entries[lo2], pe.tensor, pe.expert_idx, pe.expert_bytes) != 0)
            continue;
        const expert_pack_entry &ent = g_expert_pack.entries[lo2];
        if (loaded + ent.nbytes > budget) break;
        char *dst_ptr = (char *)region + loaded;
        if (direct_preload && preload_threads > 1) {
            parallel_jobs.push_back({lo2, loaded, &ent, false});
            loaded += (size_t)ent.nbytes;
            continue;
        }
        {
            const expert_pack_source *source = expert_pack_source_for_entry(&ent);
            if (!source || !source->file) continue;
            bool loaded_direct = false;
            if (direct_preload) {
                loaded_direct = expert_pack_direct_read_entry_to_host(&ent, dst_ptr, (size_t)ent.nbytes);
                if (loaded_direct) {
                    g_expert_pack.ram_tier_direct_bytes.fetch_add((uint64_t)ent.nbytes);
                } else {
                    ++g_expert_pack.ram_tier_direct_fallbacks;
                }
            }
            if (!loaded_direct) {
                std::lock_guard<std::mutex> lk2(g_expert_pack.mu);
                if (::fseeko(source->file, (off_t)ent.offset, SEEK_SET) != 0) continue;
                if (!expert_pack_read_exact(source->file, dst_ptr, (size_t)ent.nbytes)) continue;
            }
        }
        g_expert_pack.ram_tier_index[lo2] = {loaded, (size_t)ent.nbytes};
        loaded += (size_t)ent.nbytes;
        ++n_loaded;
        if (pin_prefix_bytes + (size_t)ent.nbytes <= pin_budget) {
            pin_prefix_bytes += (size_t)ent.nbytes;
            ++pin_prefix_entries;
        }
    }

    if (!parallel_jobs.empty()) {
        std::atomic<size_t> next_job{0};
        const int n_threads = std::min<int>(preload_threads, (int)parallel_jobs.size());
        std::vector<std::thread> workers;
        workers.reserve((size_t)n_threads);
        for (int ti = 0; ti < n_threads; ++ti) {
            workers.emplace_back([&]() {
                for (;;) {
                    const size_t ji = next_job.fetch_add(1);
                    if (ji >= parallel_jobs.size()) break;
                    ram_tier_load_job &job = parallel_jobs[ji];
                    char *dst_ptr = (char *)region + job.offset;
                    const bool ok = expert_pack_direct_read_entry_to_host(job.entry, dst_ptr, (size_t)job.entry->nbytes);
                    job.ok = ok;
                    if (ok) {
                        g_expert_pack.ram_tier_direct_bytes.fetch_add((uint64_t)job.entry->nbytes);
                    } else {
                        ++g_expert_pack.ram_tier_direct_fallbacks;
                    }
                }
            });
        }
        for (std::thread &worker : workers) worker.join();
        for (const ram_tier_load_job &job : parallel_jobs) {
            if (!job.ok) continue;
            g_expert_pack.ram_tier_index[job.pack_index] = {job.offset, (size_t)job.entry->nbytes};
            ++n_loaded;
            if (pin_prefix_bytes + (size_t)job.entry->nbytes <= pin_budget) {
                pin_prefix_bytes += (size_t)job.entry->nbytes;
                ++pin_prefix_entries;
            }
        }
    }

    std::fprintf(stderr, "[moe_stream_batch] RAM tier: loaded %zu entries (skipped %zu), %.2f MiB into anonymous mmap\n",
                 n_loaded, skip, loaded / (1024.0 * 1024.0));
    if (loaded > 0 && expert_pack_env_bool("GGML_MOE_RAM_TIER_PIN", true)) {
        const size_t pin_bytes = std::min(loaded, pin_prefix_bytes);
        if (pin_bytes == 0) {
            std::fprintf(stderr, "[moe_stream_batch] RAM tier: cudaHostRegister prefix budget is 0, using unpinned path (%.2f MiB)\n",
                         loaded / (1024.0 * 1024.0));
            return;
        }
        cudaError_t err = cudaHostRegister(region, pin_bytes, cudaHostRegisterDefault);
        if (err == cudaSuccess) {
            g_expert_pack.ram_tier_pinned_bytes = pin_bytes;
            if (pin_budget_set) {
                std::fprintf(stderr,
                             "[moe_stream_batch] RAM tier: cudaHostRegister succeeded (%.2f MiB pinned prefix, %zu entries, %.2f MiB resident)\n",
                             pin_bytes / (1024.0 * 1024.0), pin_prefix_entries, loaded / (1024.0 * 1024.0));
            } else {
                std::fprintf(stderr, "[moe_stream_batch] RAM tier: cudaHostRegister succeeded (%.2f MiB pinned)\n",
                             pin_bytes / (1024.0 * 1024.0));
            }
        } else {
            std::fprintf(stderr, "[moe_stream_batch] RAM tier: cudaHostRegister failed (%s), using unpinned path\n",
                         cudaGetErrorString(err));
        }
    } else if (loaded > 0) {
        std::fprintf(stderr, "[moe_stream_batch] RAM tier: cudaHostRegister disabled, using unpinned path (%.2f MiB)\n",
                     loaded / (1024.0 * 1024.0));
    }
}

static bool expert_pack_read_entry_iouring(const expert_pack_entry *entry, void *dst, size_t sz) {
#if defined(GGML_MOE_HAS_LIBURING) && !defined(_WIN32)
    expert_pack_source *source = expert_pack_source_for_entry(entry);
    if (!entry || !source || source->fd_direct < 0 || entry->nbytes != sz) return false;
    const uint64_t alignment = expert_pack_direct_alignment();
    const bool aligned_alias = expert_pack_env_bool("GGML_MOE_IO_ALIGNED_ALIAS_BATCH", false) &&
        entry->alias_source && (entry->offset % alignment) != 0;
    const size_t payload_shift = (size_t)(entry->offset % alignment);
    const uint64_t read_offset = aligned_alias ? entry->offset - payload_shift : entry->offset;
    const size_t read_sz = aligned_alias ?
        (size_t)align_up_u64((uint64_t)payload_shift + (uint64_t)sz, alignment) :
        (size_t)align_up_u64((uint64_t)sz, alignment);
    void *read_dst = dst;
    if (aligned_alias) {
        if (posix_memalign(&read_dst, (size_t)alignment, read_sz) != 0 || !read_dst) {
            ++g_expert_pack.iouring_fallbacks;
            return false;
        }
    } else if ((entry->offset % alignment) != 0 ||
            ((uintptr_t)dst % alignment) != 0 ||
            read_sz < sz) {
        ++g_expert_pack.iouring_fallbacks;
        return false;
    }

    io_uring ring_io;
    const unsigned int flags = expert_pack_env_bool("GGML_MOE_IO_SQPOLL", false) ? IORING_SETUP_SQPOLL : 0;
    if (io_uring_queue_init(1, &ring_io, flags) != 0) {
        if (read_dst != dst) std::free(read_dst);
        ++g_expert_pack.iouring_fallbacks;
        return false;
    }

    io_uring_sqe *sqe = io_uring_get_sqe(&ring_io);
    if (!sqe) {
        io_uring_queue_exit(&ring_io);
        if (read_dst != dst) std::free(read_dst);
        ++g_expert_pack.iouring_fallbacks;
        return false;
    }

    io_uring_prep_read(sqe, source->fd_direct, read_dst, (unsigned)read_sz, (off_t)read_offset);
    io_uring_sqe_set_data64(sqe, 1);

    const auto submit_start = std::chrono::steady_clock::now();
    const int submit_rc = io_uring_submit(&ring_io);
    const auto submit_end = std::chrono::steady_clock::now();
    g_expert_pack.iouring_submit_us.fetch_add(
            (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(submit_end - submit_start).count());
    if (submit_rc < 0) {
        io_uring_queue_exit(&ring_io);
        if (read_dst != dst) std::free(read_dst);
        ++g_expert_pack.iouring_fallbacks;
        return false;
    }

    io_uring_cqe *cqe = nullptr;
    const auto wait_start = std::chrono::steady_clock::now();
    const int wait_rc = io_uring_wait_cqe(&ring_io, &cqe);
    const auto wait_end = std::chrono::steady_clock::now();
    g_expert_pack.iouring_wait_us.fetch_add(
            (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(wait_end - wait_start).count());
    bool ok = false;
    if (wait_rc == 0 && cqe && cqe->res == (int)read_sz) {
        ok = true;
    }
    if (cqe) io_uring_cqe_seen(&ring_io, cqe);
    io_uring_queue_exit(&ring_io);

    if (ok) {
        if (read_dst != dst) {
            std::memcpy(dst, (const char *)read_dst + payload_shift, sz);
            std::free(read_dst);
        }
        ++g_expert_pack.iouring_reads;
        g_expert_pack.iouring_bytes.fetch_add(sz);
        return true;
    }

    if (read_dst != dst) std::free(read_dst);
    ++g_expert_pack.iouring_fallbacks;
    return false;
#else
    (void)entry;
    (void)dst;
    (void)sz;
    return false;
#endif
}

static bool expert_pack_direct_pread_all(int fd, void *dst, size_t sz, uint64_t offset) {
#if !defined(_WIN32)
    char *out = (char *)dst;
    size_t done = 0;
    while (done < sz) {
        const size_t chunk = std::min(sz - done, (size_t)64 * 1024 * 1024);
        const ssize_t got = ::pread(fd, out + done, chunk, (off_t)(offset + done));
        if (got <= 0) {
            return false;
        }
        done += (size_t)got;
    }
    return true;
#else
    (void)fd;
    (void)dst;
    (void)sz;
    (void)offset;
    return false;
#endif
}

static bool expert_pack_direct_read_entry_to_host(const expert_pack_entry *entry, void *dst, size_t sz) {
#if !defined(_WIN32)
    expert_pack_source *source = expert_pack_source_for_entry(entry);
    if (!entry || !source || source->fd_direct < 0 || entry->nbytes != sz) return false;
    const uint64_t alignment = expert_pack_direct_alignment();
    const uint64_t aligned_offset = (entry->offset / alignment) * alignment;
    const size_t prefix = (size_t)(entry->offset - aligned_offset);
    const size_t read_sz = (size_t)align_up_u64((uint64_t)prefix + (uint64_t)sz, alignment);
    if ((entry->offset % alignment) == 0 &&
            ((uintptr_t)dst % alignment) == 0 &&
            read_sz == (size_t)align_up_u64((uint64_t)sz, alignment)) {
        return expert_pack_direct_pread_all(source->fd_direct, dst, read_sz, entry->offset);
    }
    if (source->direct_required) {
        return false;
    }

    void *bounce = nullptr;
    if (posix_memalign(&bounce, alignment, read_sz) != 0 || !bounce) {
        return false;
    }
    const bool ok = expert_pack_direct_pread_all(source->fd_direct, bounce, read_sz, aligned_offset);
    if (ok) {
        std::memcpy(dst, (const char *)bounce + prefix, sz);
    }
    free(bounce);
    return ok;
#else
    (void)entry;
    (void)dst;
    (void)sz;
    return false;
#endif
}

static bool expert_pack_read_entry(const expert_pack_entry *entry, void *dst, size_t sz) {
    expert_pack_source *source = expert_pack_source_for_entry(entry);
    if (!entry || !source || !source->file || entry->nbytes != sz) return false;

    std::call_once(g_ram_tier_once, ram_tier_init);

    if (source->page_cache) {
        expert_pack_source *mmap_source = expert_pack_mmap_ensure(entry);
        if (mmap_source && entry->offset <= mmap_source->mmap_size &&
                entry->offset + entry->nbytes <= mmap_source->mmap_size) {
            std::memcpy(dst, (const char *)mmap_source->mmap_base + entry->offset, sz);
            ++g_expert_pack.page_cache_reads;
            g_expert_pack.page_cache_bytes.fetch_add((uint64_t)sz);
            return true;
        }
        std::lock_guard<std::mutex> lk(g_expert_pack.mu);
#if defined(_WIN32)
        if (_fseeki64(source->file, (int64_t)entry->offset, SEEK_SET) != 0) {
#else
        if (::fseeko(source->file, (off_t)entry->offset, SEEK_SET) != 0) {
#endif
            ++g_expert_pack.read_failures;
            return false;
        }
        if (!expert_pack_read_exact(source->file, dst, sz)) {
            ++g_expert_pack.read_failures;
            return false;
        }
        ++g_expert_pack.page_cache_reads;
        g_expert_pack.page_cache_bytes.fetch_add((uint64_t)sz);
        return true;
    }

#if !defined(_WIN32)
    if (g_expert_pack.io_backend == 2 && source->fd_direct >= 0 &&
            expert_pack_env_bool("GGML_MOE_IO_URING_SINGLE", false)) {
        if (expert_pack_read_entry_iouring(entry, dst, sz)) {
            return true;
        }
    }
    if ((g_expert_pack.io_backend == 1 || g_expert_pack.io_backend == 2) && source->fd_direct >= 0) {
        const bool profile_direct = direct_read_site_profile_path() != nullptr;
        const auto direct_start = profile_direct ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
        const bool direct_ok = expert_pack_direct_read_entry_to_host(entry, dst, sz);
        if (profile_direct) {
            const auto direct_end = std::chrono::steady_clock::now();
            direct_read_site_profile_record(
                    g_direct_read_site_op ? g_direct_read_site_op : "expert_pack_read_entry",
                    g_direct_read_site_tensor ? g_direct_read_site_tensor : entry->tensor,
                    sz,
                    direct_ok,
                    std::chrono::duration<double, std::milli>(direct_end - direct_start).count());
        }
        if (direct_ok) {
            ++g_expert_pack.direct_reads;
            return true;
        }
        ++g_expert_pack.direct_fallbacks;
        if (source->direct_required) {
            ++g_expert_pack.read_failures;
            return false;
        }
    }
#endif

    if (source->direct_required) {
        ++g_expert_pack.read_failures;
        return false;
    }

    std::lock_guard<std::mutex> lk(g_expert_pack.mu);
#if defined(_WIN32)
    if (_fseeki64(source->file, (int64_t)entry->offset, SEEK_SET) != 0) {
#else
    if (::fseeko(source->file, (off_t)entry->offset, SEEK_SET) != 0) {
#endif
        ++g_expert_pack.read_failures;
        return false;
    }
    if (!expert_pack_read_exact(source->file, dst, sz)) {
        ++g_expert_pack.read_failures;
        return false;
    }
    return true;
}

// CPU sink resolver. n_experts is the routed-expert tensor's ne[2]; nbytes is
// one logical role slice. A v1 pack may serve that slice with a page-padded
// physical read; the K3-local adapter (validated 896-expert Q2_K/IQ1_S slices)
// has no CPU sink transport and is refused.
extern "C" bool ggml_cuda_moe_expert_pack_resolve_raw_direct_shape(
        const char * tensor_name, int expert_idx, size_t nbytes, int64_t n_experts,
        int * fd_direct, uint64_t * offset, size_t * logical_nbytes) {
    if (!tensor_name || expert_idx < 0 || n_experts <= 0 || expert_idx >= n_experts || !nbytes) { return false; }
    ggml_moe::adapter_select_model_shape(n_experts, nbytes, "cpu-sink-raw-range");
    return ggml_moe::adapter_uses_common() && ggml_cuda_moe_common_expert_pack_resolve_raw_direct(
        tensor_name, expert_idx, nbytes, fd_direct, offset, logical_nbytes);
}

extern "C" bool ggml_cuda_moe_expert_pack_resolve_direct_shape(
        const char * tensor_name,
        int expert_idx,
        size_t nbytes,
        int64_t n_experts,
        int * fd_direct,
        uint64_t * offset,
        size_t * direct_nbytes) {
    if (fd_direct) *fd_direct = -1;
    if (offset) *offset = 0;
    if (direct_nbytes) *direct_nbytes = 0;
    if (!tensor_name || expert_idx < 0 || n_experts <= 0 || expert_idx >= n_experts ||
            nbytes == 0 || !direct_nbytes) {
        return false;
    }
    ggml_moe::adapter_select_model_shape(n_experts, nbytes, "cpu-sink");
    return ggml_moe::adapter_uses_common() &&
        ggml_cuda_moe_common_expert_pack_resolve_direct(
            tensor_name, expert_idx, nbytes, fd_direct, offset, direct_nbytes);
}

extern "C" bool ggml_cuda_moe_expert_pack_resolve_direct(
        const char * tensor_name,
        int expert_idx,
        size_t nbytes,
        int * fd_direct,
        uint64_t * offset) {
    if (fd_direct) *fd_direct = -1;
    if (offset) *offset = 0;
    // Legacy entry: only the Kimi-K3 Q3_K role slice. Shape-aware callers use
    // ggml_cuda_moe_expert_pack_resolve_direct_shape.
    if (nbytes != 4730880) return false;
    size_t direct_nbytes = 0;
    return ggml_cuda_moe_expert_pack_resolve_direct_shape(
        tensor_name, expert_idx, nbytes, 896, fd_direct, offset, &direct_nbytes) &&
        direct_nbytes == nbytes;
}

extern "C" bool ggml_cuda_moe_expert_pack_read_to_host(
        const char *tensor_name,
        int expert_idx,
        size_t nbytes,
        void *dst,
        size_t dst_capacity,
        size_t *nread,
        int *source_is_gguf) {
    if (ggml_moe::adapter_uses_common()) {
        return ggml_cuda_moe_common_expert_pack_read_to_host(
            tensor_name, expert_idx, nbytes, dst, dst_capacity, nread,
            source_is_gguf);
    }
    if (nread) {
        *nread = 0;
    }
    if (source_is_gguf) {
        *source_is_gguf = 0;
    }
    if (!tensor_name || !tensor_name[0] || expert_idx < 0 ||
            nbytes == 0 || !dst || dst_capacity < nbytes) {
        return false;
    }
    const expert_pack_entry *entry = expert_pack_lookup(tensor_name, expert_idx, nbytes);
    if (!entry) {
        return false;
    }
    const expert_pack_source *source = expert_pack_source_for_entry(entry);
    if (source_is_gguf && source && std::strstr(source->path, ".gguf")) {
        *source_is_gguf = 1;
    }
    if (!expert_pack_read_entry(entry, dst, nbytes)) {
        return false;
    }
    if (nread) {
        *nread = nbytes;
    }
    return true;
}

