struct q4_colibri_object_batch {
    std::vector<q4_colibri_object_job> jobs;
    q4_colibri_pipe_completion *completion = nullptr;
    std::chrono::steady_clock::time_point queued_at;
    bool heap_owned = false;
    bool pilot_prefetch = false;
    uint64_t pilot_role_count = 0;
    uint64_t pilot_bytes = 0;
    q4_scheduler_readiness_timing readiness;
};

static bool q4_layer_io_profile_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_LAYER_IO_PROFILE", false);
}

static void q4_layer_io_add(std::atomic<uint64_t> (&counters)[128], int layer, uint64_t value) {
    if (!q4_layer_io_profile_enabled() || value == 0 || layer < 0 || layer >= 128) return;
    counters[layer].fetch_add(value, std::memory_order_relaxed);
}

static int q4_colibri_object_batch_common_layer(const q4_colibri_object_batch &batch) {
    int layer = -1;
    for (const q4_colibri_object_job &job : batch.jobs) {
        const int job_layer = (int)job.marker.layer_idx;
        if (job_layer < 0 || job_layer >= 128) continue;
        if (layer < 0) {
            layer = job_layer;
        } else if (layer != job_layer) {
            return -1;
        }
    }
    return layer;
}

struct q4_colibri_pipe_state {
    bool inited = false;
    bool enabled = false;
    bool started = false;
    bool stop = false;
    bool failed = false;
    size_t max_jobs = 64;
    cudaStream_t stream = nullptr;
    pinned_stage_ring ring;
    pinned_stage_ring coalesce_ring;
    std::deque<q4_colibri_pipe_job> jobs;
    std::deque<q4_colibri_object_batch *> object_batches;
    std::mutex mu;
    std::condition_variable cv;
    std::thread worker;
    uint64_t object_clock = 1;
};

static q4_colibri_pipe_state g_q4_colibri_pipe;

