    bool pending_d2h = false;
    bool delete_after_h2d = false;
    cudaEvent_t h2d_done = nullptr;
    cudaEvent_t d2h_done = nullptr;
    uint64_t used = 0;
    uint64_t read_us = 0;
    uint64_t score = 0;
    uint32_t freq = 0;
    uint8_t origin = Q4_HOST_OBJECT_ORIGIN_UNKNOWN;
