};

struct q4_colibri_host_object_prefetch_state {
    bool inited = false;
    bool enabled = false;
    bool stop = false;
    bool failed = false;
    size_t max_slots = 0;
    size_t max_resident_bytes = 0;
    size_t resident_capacity_bytes = 0;
    size_t resident_capacity_peak_bytes = 0;
    uint64_t clock = 1;
    std::vector<q4_colibri_host_object_slot> slots;
    std::deque<q4_colibri_host_object_request> queue;
    std::unordered_map<std::string, size_t> ready;
    std::unordered_set<std::string> queued;
    std::unordered_map<std::string, uint32_t> request_freq;
    std::mutex mu;
    std::condition_variable cv;
    std::thread worker;
