};

static q4_object_tier_trace_state g_q4_object_tier_trace;

static const char *q4_object_tier_trace_path() {
    static const char *path = std::getenv("GGML_MOE_Q4_OBJECT_TIER_TRACE_OUT");
    return path && path[0] ? path : nullptr;
}

static bool q4_object_tier_trace_enabled() {
    return g_expert_pack.q4_colibri && q4_object_tier_trace_path();
}

static uint64_t q4_colibri_host_object_score(
        const q4_colibri_object_marker &marker,
        int current_layer,
        uint32_t freq);

static bool q4_object_tier_trace_score_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_OBJECT_TIER_TRACE_SCORE", false);
}

struct q4_object_tier_trace_ram_slot_snapshot {
    bool present = false;
    bool ready = false;
    bool loading = false;
    bool delete_after_h2d = false;
    uint64_t score = 0;
    uint32_t freq = 0;
    uint64_t used = 0;
};

static q4_object_tier_trace_ram_slot_snapshot q4_object_tier_trace_get_ram_snapshot(
        const q4_colibri_object_marker &marker) {
    q4_object_tier_trace_ram_slot_snapshot out;
    if (!q4_colibri_host_object_prefetch_enabled()) return out;
    std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
    if (!g_q4_host_object_prefetch.inited || !g_q4_host_object_prefetch.enabled) return out;
    const std::string key = q4_colibri_host_object_key(marker);
    auto it = g_q4_host_object_prefetch.ready.find(key);
    if (it == g_q4_host_object_prefetch.ready.end() ||
            it->second >= g_q4_host_object_prefetch.slots.size()) {
        return out;
    }
    const q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[it->second];
    if (!q4_colibri_object_marker_matches(slot.marker, marker)) return out;
    out.present = true;
    out.ready = slot.ready;
    out.loading = slot.loading;
    out.delete_after_h2d = slot.delete_after_h2d;
    out.score = slot.score;
    out.freq = slot.freq;
    out.used = slot.used;
    return out;
}

static bool q4_tier_diag_vram_evicted_age_snapshot(
        const q4_colibri_object_marker &marker,
        uint64_t *age_out) {
    std::lock_guard<std::mutex> lock(g_q4_tier_overlap_diag.mu);
    const std::string key = q4_tier_diag_object_key(marker);
    auto it = g_q4_tier_overlap_diag.vram_evicted_epoch.find(key);
    if (it == g_q4_tier_overlap_diag.vram_evicted_epoch.end()) return false;
    const uint64_t epoch = g_q4_tier_overlap_diag.token_epoch;
    if (age_out) {
        *age_out = epoch >= it->second ? epoch - it->second : 0;
    }
    return true;
}

static void q4_object_tier_trace_record(
        const q4_colibri_object_marker &marker,
        int64_t active_rows,
        uint64_t vram_present_roles,
        uint64_t vram_ready_roles,
        bool ram_ready,
        uint64_t missing_roles,
        uint64_t scheduled_roles,
        uint64_t object_bytes,
        uint64_t logical_role_bytes,
        bool ram_lookup_allowed,
        bool ram_admit_allowed,
        bool ram_net_allowed) {
    if (!q4_object_tier_trace_enabled()) return;

    const char *demand_tier = "ssd";
    const char *provider_path = "ssd_read_h2d";
    if (vram_present_roles >= 3) {
        demand_tier = vram_ready_roles >= 3 ? "vram_full_ready" : "vram_full_pending";
        provider_path = vram_ready_roles >= 3 ? "none" : "wait_vram";
    } else if (vram_present_roles > 0) {
        demand_tier = ram_ready ? "vram_partial_ram" : "vram_partial_ssd";
        provider_path = ram_ready ? "ram_h2d" : "ssd_read_h2d";
    } else if (ram_ready) {
        demand_tier = "ram";
        provider_path = "ram_h2d";
    }

    const uint64_t epoch =
        g_q4_tier_overlap_diag.token_epoch_public.load(std::memory_order_acquire);
    uint64_t vram_eviction_age = 0;
    const bool after_vram_eviction =
        q4_tier_diag_vram_evicted_age_snapshot(marker, &vram_eviction_age);
    const bool score_trace = q4_object_tier_trace_score_enabled();
    const int current_layer = score_trace ? q4_tier_diag_current_layer_snapshot() : -1;
    const int layer_distance =
        score_trace && current_layer >= 0 && marker.layer_idx >= 0 ?
        (int)marker.layer_idx - current_layer : 0;
    const uint32_t score_freq = 1;
    const uint64_t object_score = score_trace ?
        q4_colibri_host_object_score(marker, current_layer, score_freq) : 0;
    const q4_object_tier_trace_ram_slot_snapshot ram_snapshot =
        score_trace ? q4_object_tier_trace_get_ram_snapshot(marker) : q4_object_tier_trace_ram_slot_snapshot{};

    std::lock_guard<std::mutex> lock(g_q4_object_tier_trace.mu);
    const char *path = q4_object_tier_trace_path();
    if (!path) return;
    FILE *f = std::fopen(path, "a");
    if (!f) return;
    if (!g_q4_object_tier_trace.header_written) {
        std::fprintf(f,
            "seq,epoch,layer,expert,source_idx,offset,object_bytes,active_rows,"
            "vram_present_roles,vram_ready_roles,ram_ready,missing_roles,scheduled_roles,"
            "logical_role_bytes,demand_tier,provider_path,ram_lookup_allowed,"
            "ram_admit_allowed,ram_net_allowed,after_vram_eviction,vram_eviction_age,"
            "current_layer,layer_distance,score_freq,object_score,"
            "ram_slot_present,ram_slot_ready,ram_slot_loading,ram_slot_delete_after_h2d,"
            "ram_slot_freq,ram_slot_score,ram_slot_used\n");
        g_q4_object_tier_trace.header_written = true;
    }
    std::fprintf(f,
        "%llu,%llu,%d,%d,%d,%llu,%llu,%lld,%llu,%llu,%d,%llu,%llu,%llu,%s,%s,%d,%d,%d,%d,%llu,%d,%d,%u,%llu,%d,%d,%d,%d,%u,%llu,%llu\n",
        (unsigned long long)++g_q4_object_tier_trace.seq,
        (unsigned long long)epoch,
        (int)marker.layer_idx,
        (int)marker.expert_idx,
        (int)marker.source_idx,
        (unsigned long long)marker.offset,
        (unsigned long long)object_bytes,
        (long long)active_rows,
        (unsigned long long)vram_present_roles,
        (unsigned long long)vram_ready_roles,
        ram_ready ? 1 : 0,
        (unsigned long long)missing_roles,
        (unsigned long long)scheduled_roles,
        (unsigned long long)logical_role_bytes,
        demand_tier,
        provider_path,
        ram_lookup_allowed ? 1 : 0,
        ram_admit_allowed ? 1 : 0,
        ram_net_allowed ? 1 : 0,
        after_vram_eviction ? 1 : 0,
        (unsigned long long)vram_eviction_age,
        current_layer,
        layer_distance,
        (unsigned)score_freq,
        (unsigned long long)object_score,
        ram_snapshot.present ? 1 : 0,
        ram_snapshot.ready ? 1 : 0,
        ram_snapshot.loading ? 1 : 0,
        ram_snapshot.delete_after_h2d ? 1 : 0,
        (unsigned)ram_snapshot.freq,
        (unsigned long long)ram_snapshot.score,
        (unsigned long long)ram_snapshot.used);
    std::fclose(f);
}

static q4_graph_slot_status q4_graph_vram_slot_status(const batch_vram_cache *cache, uintptr_t key) {
    q4_graph_slot_status status;
    if (!cache || !cache->pool || cache->n_slots <= 0 || key == 0) return status;
    for (int slot = 0; slot < cache->n_slots; ++slot) {
        if (cache->slot_key[slot] != key) continue;
        if (cache->slot_state[slot] == q4_colibri_slot_state::failed ||
                cache->slot_state[slot] == q4_colibri_slot_state::free ||
                cache->slot_state[slot] == q4_colibri_slot_state::reserved ||
                cache->slot_filling[slot] ||
                cache->slot_payload_bytes[slot] == 0) {
            return status;
        }
        status.present = true;
        status.pending = cache->slot_pending[slot];
        status.ready = !status.pending;
        status.slot = slot;
        status.device_ptr = (uint64_t)(uintptr_t)((const char *)cache->pool + (size_t)slot * cache->slot_sz);
        return status;
    }
    return status;
}



static const char *q4_graph_role_name(int role) {
    switch (role) {
        case 0: return "up";
        case 1: return "gate";
        case 2: return "down";
        default: return "unknown";
    }
}

static void q4_graph_report_role_line(const char *prefix, int layer, int role, uint64_t active, uint64_t ready, uint64_t full_hit) {
    if (active == 0 && ready == 0 && full_hit == 0) return;
    if (layer >= 0) {
        std::fprintf(stderr,
            "[moe_stream_batch] %s: layer=%d role=%s active_roles=%lu ready_roles=%lu "
            "miss_roles=%lu ready_rate=%.1f%% full_hit_calls=%lu\n",
            prefix, layer, q4_graph_role_name(role),
            (unsigned long)active,
            (unsigned long)ready,
            (unsigned long)(active > ready ? active - ready : 0),
            active > 0 ? 100.0 * (double)ready / (double)active : 0.0,
            (unsigned long)full_hit);
    } else {
        std::fprintf(stderr,
            "[moe_stream_batch] %s: role=%s active_roles=%lu ready_roles=%lu "
            "miss_roles=%lu ready_rate=%.1f%% full_hit_calls=%lu\n",
            prefix, q4_graph_role_name(role),
            (unsigned long)active,
            (unsigned long)ready,
            (unsigned long)(active > ready ? active - ready : 0),
            active > 0 ? 100.0 * (double)ready / (double)active : 0.0,
            (unsigned long)full_hit);
    }
}

static void q4_graph_report_miss_hist_line(const char *prefix, const std::atomic<uint64_t> *hist, int count) {
    uint64_t total = 0;
    for (int i = 0; i < count; ++i) {
        total += hist[i].load(std::memory_order_relaxed);
    }
    if (total == 0) return;
    std::fprintf(stderr, "[moe_stream_batch] %s: total=%lu", prefix, (unsigned long)total);
    for (int i = 0; i < count; ++i) {
        const uint64_t value = hist[i].load(std::memory_order_relaxed);
        if (value == 0) continue;
        if (i == count - 1) {
            std::fprintf(stderr, " miss_ge_%d=%lu", i, (unsigned long)value);
        } else {
            std::fprintf(stderr, " miss_%d=%lu", i, (unsigned long)value);
        }
    }
    std::fprintf(stderr, "\n");
}

static void q4_graph_hit_profile_report() {
    const uint64_t upgate_calls = g_q4_graph_hit_profile.upgate_calls.load(std::memory_order_relaxed);
    const uint64_t down_calls = g_q4_graph_hit_profile.down_calls.load(std::memory_order_relaxed);
    if (upgate_calls + down_calls == 0 && !q4_graph_profile_requested()) return;
    const uint64_t active_roles = g_q4_graph_hit_profile.active_roles.load(std::memory_order_relaxed);
    const uint64_t ready_roles = g_q4_graph_hit_profile.vram_ready_roles.load(std::memory_order_relaxed);
    const uint64_t miss_roles = g_q4_graph_hit_profile.vram_miss_roles.load(std::memory_order_relaxed);
    std::fprintf(stderr,
        "[moe_stream_batch] q4 graph hit-path: enabled=%d profile=%d upgate_calls=%lu down_calls=%lu "
        "prompt_skips=%lu layer_skips=%lu descriptor_overflow=%lu active_roles=%lu "
        "vram_ready_roles=%lu vram_miss_roles=%lu role_ready_rate=%.1f%% full_hit_calls=%lu "
        "upgate_full_hit_calls=%lu down_full_hit_calls=%lu blocked_host_expanded_slots=%lu "
        "would_replay_calls=%lu note=fixed-slot-device-descriptor-required\n",
        q4_graph_hit_path_requested() ? 1 : 0,
        q4_graph_profile_requested() ? 1 : 0,
        (unsigned long)upgate_calls,
        (unsigned long)down_calls,
        (unsigned long)g_q4_graph_hit_profile.prompt_skips.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.layer_skips.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.descriptor_overflow.load(std::memory_order_relaxed),
        (unsigned long)active_roles,
        (unsigned long)ready_roles,
        (unsigned long)miss_roles,
        active_roles > 0 ? 100.0 * (double)ready_roles / (double)active_roles : 0.0,
        (unsigned long)g_q4_graph_hit_profile.full_hit_calls.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.upgate_full_hit_calls.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.down_full_hit_calls.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.blocked_host_expanded_slots.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.would_replay_calls.load(std::memory_order_relaxed));
    q4_graph_report_role_line("q4 graph role", -1, 0,
        g_q4_graph_hit_profile.role_active_roles[0].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.role_ready_roles[0].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.upgate_full_hit_calls.load(std::memory_order_relaxed));
    q4_graph_report_role_line("q4 graph role", -1, 1,
        g_q4_graph_hit_profile.role_active_roles[1].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.role_ready_roles[1].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.upgate_full_hit_calls.load(std::memory_order_relaxed));
    q4_graph_report_role_line("q4 graph role", -1, 2,
        g_q4_graph_hit_profile.role_active_roles[2].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.role_ready_roles[2].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.down_full_hit_calls.load(std::memory_order_relaxed));
    const uint64_t post_calls = g_q4_graph_hit_profile.post_provider_calls.load(std::memory_order_relaxed);
    if (post_calls > 0) {
        const uint64_t post_objects = g_q4_graph_hit_profile.post_provider_active_objects.load(std::memory_order_relaxed);
        const uint64_t post_active_roles = post_objects * 3;
        const uint64_t post_present = g_q4_graph_hit_profile.post_provider_present_roles.load(std::memory_order_relaxed);
        const uint64_t post_pending = g_q4_graph_hit_profile.post_provider_pending_roles.load(std::memory_order_relaxed);
        const uint64_t post_ready = g_q4_graph_hit_profile.post_provider_ready_roles.load(std::memory_order_relaxed);
        std::fprintf(stderr,
            "[moe_stream_batch] q4 graph post-provider: calls=%lu active_objects=%lu "
            "active_roles=%lu present_roles=%lu pending_roles=%lu ready_roles=%lu "
            "missing_roles=%lu present_rate=%.1f%% ready_rate=%.1f%% "
            "full_present_calls=%lu full_ready_calls=%lu "
            "note=provider-complete-fixed-slot-eligibility\n",
            (unsigned long)post_calls,
            (unsigned long)post_objects,
            (unsigned long)post_active_roles,
            (unsigned long)post_present,
            (unsigned long)post_pending,
            (unsigned long)post_ready,
            (unsigned long)(post_active_roles > post_present ? post_active_roles - post_present : 0),
            post_active_roles > 0 ? 100.0 * (double)post_present / (double)post_active_roles : 0.0,
            post_active_roles > 0 ? 100.0 * (double)post_ready / (double)post_active_roles : 0.0,
            (unsigned long)g_q4_graph_hit_profile.post_provider_full_present_calls.load(std::memory_order_relaxed),
            (unsigned long)g_q4_graph_hit_profile.post_provider_full_ready_calls.load(std::memory_order_relaxed));
    }
    const uint64_t post_wait_calls = g_q4_graph_hit_profile.post_wait_calls.load(std::memory_order_relaxed);
    if (post_wait_calls > 0) {
        const uint64_t post_wait_objects = g_q4_graph_hit_profile.post_wait_active_objects.load(std::memory_order_relaxed);
        const uint64_t post_wait_active_roles = post_wait_objects * 3;
        const uint64_t post_wait_present = g_q4_graph_hit_profile.post_wait_present_roles.load(std::memory_order_relaxed);
        const uint64_t post_wait_pending = g_q4_graph_hit_profile.post_wait_pending_roles.load(std::memory_order_relaxed);
        const uint64_t post_wait_ready = g_q4_graph_hit_profile.post_wait_ready_roles.load(std::memory_order_relaxed);
        std::fprintf(stderr,
            "[moe_stream_batch] q4 graph post-wait: calls=%lu active_objects=%lu "
            "active_roles=%lu present_roles=%lu pending_roles=%lu ready_roles=%lu "
            "missing_roles=%lu present_rate=%.1f%% ready_rate=%.1f%% "
            "full_present_calls=%lu full_ready_calls=%lu "
            "note=after-active-slot-wait-before-compute\n",
