            (unsigned long)post_wait_objects,
            (unsigned long)post_wait_active_roles,
            (unsigned long)post_wait_present,
            (unsigned long)post_wait_pending,
            (unsigned long)post_wait_ready,
            (unsigned long)(post_wait_active_roles > post_wait_present ? post_wait_active_roles - post_wait_present : 0),
            post_wait_active_roles > 0 ? 100.0 * (double)post_wait_present / (double)post_wait_active_roles : 0.0,
            post_wait_active_roles > 0 ? 100.0 * (double)post_wait_ready / (double)post_wait_active_roles : 0.0,
            (unsigned long)g_q4_graph_hit_profile.post_wait_full_present_calls.load(std::memory_order_relaxed),
            (unsigned long)g_q4_graph_hit_profile.post_wait_full_ready_calls.load(std::memory_order_relaxed));
    }
    const uint64_t desc_calls = g_q4_graph_hit_profile.descriptor_dry_run_calls.load(std::memory_order_relaxed);
    const uint64_t desc_failures = g_q4_graph_hit_profile.descriptor_dry_run_failures.load(std::memory_order_relaxed);
    if (desc_calls > 0 || desc_failures > 0) {
        const uint64_t desc_objects = g_q4_graph_hit_profile.descriptor_dry_run_objects.load(std::memory_order_relaxed);
        const uint64_t desc_bytes = g_q4_graph_hit_profile.descriptor_dry_run_bytes.load(std::memory_order_relaxed);
        const uint64_t desc_copy_us = g_q4_graph_hit_profile.descriptor_dry_run_copy_us.load(std::memory_order_relaxed);
