    q4_graph_report_miss_hist_line("q4 graph miss hist upgate", g_q4_graph_hit_profile.upgate_miss_hist, 17);
    q4_graph_report_miss_hist_line("q4 graph miss hist down", g_q4_graph_hit_profile.down_miss_hist, 9);
    for (int layer = 0; layer < 128; ++layer) {
        const uint64_t layer_upgate = g_q4_graph_hit_profile.layer_upgate_calls[layer].load(std::memory_order_relaxed);
        const uint64_t layer_down = g_q4_graph_hit_profile.layer_down_calls[layer].load(std::memory_order_relaxed);
        const uint64_t layer_post_calls = g_q4_graph_hit_profile.layer_post_provider_calls[layer].load(std::memory_order_relaxed);
