        q4_graph_report_role_line("q4 graph role layer", layer, 1,
            g_q4_graph_hit_profile.layer_gate_active_roles[layer].load(std::memory_order_relaxed),
            g_q4_graph_hit_profile.layer_gate_ready_roles[layer].load(std::memory_order_relaxed),
            g_q4_graph_hit_profile.layer_upgate_full_hit_calls[layer].load(std::memory_order_relaxed));
        q4_graph_report_role_line("q4 graph role layer", layer, 2,
