            g_q4_graph_hit_profile.layer_down_ready_roles[layer].load(std::memory_order_relaxed),
            g_q4_graph_hit_profile.layer_down_full_hit_calls[layer].load(std::memory_order_relaxed));
        if (layer_post_calls > 0) {
            const uint64_t layer_post_objects = g_q4_graph_hit_profile.layer_post_provider_active_objects[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_active_roles = layer_post_objects * 3;
            const uint64_t layer_post_present = g_q4_graph_hit_profile.layer_post_provider_present_roles[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_pending = g_q4_graph_hit_profile.layer_post_provider_pending_roles[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_ready = g_q4_graph_hit_profile.layer_post_provider_ready_roles[layer].load(std::memory_order_relaxed);
            std::fprintf(stderr,
                "[moe_stream_batch] q4 graph post-provider layer: layer=%d calls=%lu "
                "active_objects=%lu active_roles=%lu present_roles=%lu pending_roles=%lu ready_roles=%lu "
                "missing_roles=%lu present_rate=%.1f%% ready_rate=%.1f%% "
                "full_present_calls=%lu full_ready_calls=%lu\n",
                layer,
                (unsigned long)layer_post_calls,
                (unsigned long)layer_post_objects,
                (unsigned long)layer_post_active_roles,
                (unsigned long)layer_post_present,
                (unsigned long)layer_post_pending,
                (unsigned long)layer_post_ready,
                (unsigned long)(layer_post_active_roles > layer_post_present ? layer_post_active_roles - layer_post_present : 0),
                layer_post_active_roles > 0 ? 100.0 * (double)layer_post_present / (double)layer_post_active_roles : 0.0,
                layer_post_active_roles > 0 ? 100.0 * (double)layer_post_ready / (double)layer_post_active_roles : 0.0,
                (unsigned long)g_q4_graph_hit_profile.layer_post_provider_full_present_calls[layer].load(std::memory_order_relaxed),
                (unsigned long)g_q4_graph_hit_profile.layer_post_provider_full_ready_calls[layer].load(std::memory_order_relaxed));
        }
        const uint64_t layer_post_wait_calls = g_q4_graph_hit_profile.layer_post_wait_calls[layer].load(std::memory_order_relaxed);
        if (layer_post_wait_calls > 0) {
            const uint64_t layer_post_wait_objects = g_q4_graph_hit_profile.layer_post_wait_active_objects[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_wait_active_roles = layer_post_wait_objects * 3;
            const uint64_t layer_post_wait_present = g_q4_graph_hit_profile.layer_post_wait_present_roles[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_wait_pending = g_q4_graph_hit_profile.layer_post_wait_pending_roles[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_wait_ready = g_q4_graph_hit_profile.layer_post_wait_ready_roles[layer].load(std::memory_order_relaxed);
            std::fprintf(stderr,
                "[moe_stream_batch] q4 graph post-wait layer: layer=%d calls=%lu "
                "active_objects=%lu active_roles=%lu present_roles=%lu pending_roles=%lu ready_roles=%lu "
                "missing_roles=%lu present_rate=%.1f%% ready_rate=%.1f%% "
                "full_present_calls=%lu full_ready_calls=%lu\n",
                layer,
                (unsigned long)layer_post_wait_calls,
                (unsigned long)layer_post_wait_objects,
                (unsigned long)layer_post_wait_active_roles,
                (unsigned long)layer_post_wait_present,
                (unsigned long)layer_post_wait_pending,
                (unsigned long)layer_post_wait_ready,
                (unsigned long)(layer_post_wait_active_roles > layer_post_wait_present ? layer_post_wait_active_roles - layer_post_wait_present : 0),
                layer_post_wait_active_roles > 0 ? 100.0 * (double)layer_post_wait_present / (double)layer_post_wait_active_roles : 0.0,
                layer_post_wait_active_roles > 0 ? 100.0 * (double)layer_post_wait_ready / (double)layer_post_wait_active_roles : 0.0,
                (unsigned long)g_q4_graph_hit_profile.layer_post_wait_full_present_calls[layer].load(std::memory_order_relaxed),
                (unsigned long)g_q4_graph_hit_profile.layer_post_wait_full_ready_calls[layer].load(std::memory_order_relaxed));
        }
    }
}

static void q4_graph_hit_profile_register_once() {
    std::lock_guard<std::mutex> lk(g_q4_graph_hit_profile.mu);
    if (g_q4_graph_hit_profile.report_registered) return;
    std::atexit(q4_graph_hit_profile_report);
    g_q4_graph_hit_profile.report_registered = true;
}





static bool q4_graph_descriptor_dry_run_copy(
        int layer,
        const std::vector<q4_graph_descriptor_entry> &entries) {
    if (!q4_graph_descriptor_dry_run_enabled()) return true;
    if (entries.empty()) return true;
    const size_t bytes = entries.size() * sizeof(q4_graph_descriptor_entry);
    if (g_batch.d_q4_graph_desc_sz < bytes) {
        if (g_batch.d_q4_graph_desc) {
            cudaFree(g_batch.d_q4_graph_desc);
            g_batch.d_q4_graph_desc = nullptr;
            g_batch.d_q4_graph_desc_sz = 0;
        }
        if (cudaMalloc(&g_batch.d_q4_graph_desc, bytes) != cudaSuccess) {
            ++g_q4_graph_hit_profile.descriptor_dry_run_failures;
            return false;
        }
        g_batch.d_q4_graph_desc_sz = bytes;
    }
    const auto copy_start = std::chrono::steady_clock::now();
    char label[160];
    std::snprintf(label, sizeof(label),
            "q4_graph_descriptor_dry_run layer=%d objects=%zu bytes=%zu",
            layer, entries.size(), bytes);
    {
        moe_nvtx_range nvtx(label);
        if (cudaMemcpyAsync(g_batch.d_q4_graph_desc, entries.data(), bytes,
                    cudaMemcpyHostToDevice, g_batch.stream) != cudaSuccess) {
            ++g_q4_graph_hit_profile.descriptor_dry_run_failures;
            return false;
        }
    }
    const uint64_t copy_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - copy_start).count();
    ++g_q4_graph_hit_profile.descriptor_dry_run_calls;
    g_q4_graph_hit_profile.descriptor_dry_run_objects.fetch_add(entries.size(), std::memory_order_relaxed);
    g_q4_graph_hit_profile.descriptor_dry_run_bytes.fetch_add(bytes, std::memory_order_relaxed);
    g_q4_graph_hit_profile.descriptor_dry_run_copy_us.fetch_add(copy_us, std::memory_order_relaxed);
    return true;
}

static void q4_graph_record_same_layer_boundary(
        const char *gate_name,
        const char *const role_names[3],
        batch_vram_cache *cache,
        int64_t n_as,
        const int64_t *matrix_row_counts,
        bool post_wait) {
    if (!q4_graph_profile_requested() || !gate_name || !role_names || !cache ||
            n_as <= 0 || !matrix_row_counts) {
        return;
    }
    q4_graph_hit_profile_register_once();
    const int layer = q4_graph_layer_from_tensor(gate_name);
    if (!q4_graph_layer_allowed(gate_name)) {
        ++g_q4_graph_hit_profile.layer_skips;
        return;
    }

    uint64_t objects = 0;
    uint64_t present_roles = 0;
    uint64_t pending_roles = 0;
    uint64_t ready_roles = 0;
    std::vector<q4_graph_descriptor_entry> descriptors;
    if (q4_graph_descriptor_dry_run_enabled()) {
        descriptors.reserve((size_t)std::min<int64_t>(n_as, 512));
    }
    for (int64_t expert = 0; expert < n_as; ++expert) {
        if (matrix_row_counts[expert] <= 0) continue;
        ++objects;
        q4_graph_slot_status role_status[3];
        for (size_t role_idx = 0; role_idx < 3; ++role_idx) {
            const char *role_name = role_names[role_idx];
            if (!role_name || !role_name[0]) continue;
            const q4_graph_slot_status status =
                q4_graph_vram_slot_status(cache, batch_key_hash(role_name, (int)expert));
            role_status[role_idx] = status;
            if (status.present) ++present_roles;
            if (status.pending) ++pending_roles;
            if (status.ready) ++ready_roles;
        }
        if (q4_graph_descriptor_dry_run_enabled() &&
                role_status[0].present && role_status[1].present && role_status[2].present) {
            q4_graph_descriptor_entry desc;
            desc.gate_ptr = role_status[0].device_ptr;
            desc.up_ptr = role_status[1].device_ptr;
            desc.down_ptr = role_status[2].device_ptr;
            desc.expert = (int32_t)expert;
            desc.layer = (int32_t)layer;
            desc.gate_slot = (int32_t)role_status[0].slot;
            desc.up_slot = (int32_t)role_status[1].slot;
            desc.down_slot = (int32_t)role_status[2].slot;
            desc.flags =
                (role_status[0].pending ? 1 : 0) |
                (role_status[1].pending ? 2 : 0) |
                (role_status[2].pending ? 4 : 0);
            descriptors.push_back(desc);
        }
    }
    if (objects == 0) return;
    const uint64_t active_roles = objects * 3;
    std::atomic<uint64_t> &calls = post_wait ?
        g_q4_graph_hit_profile.post_wait_calls :
        g_q4_graph_hit_profile.post_provider_calls;
    std::atomic<uint64_t> &active_objects_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_active_objects :
        g_q4_graph_hit_profile.post_provider_active_objects;
    std::atomic<uint64_t> &present_roles_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_present_roles :
        g_q4_graph_hit_profile.post_provider_present_roles;
    std::atomic<uint64_t> &pending_roles_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_pending_roles :
        g_q4_graph_hit_profile.post_provider_pending_roles;
    std::atomic<uint64_t> &ready_roles_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_ready_roles :
        g_q4_graph_hit_profile.post_provider_ready_roles;
    std::atomic<uint64_t> &full_present_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_full_present_calls :
        g_q4_graph_hit_profile.post_provider_full_present_calls;
    std::atomic<uint64_t> &full_ready_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_full_ready_calls :
        g_q4_graph_hit_profile.post_provider_full_ready_calls;
    ++calls;
    active_objects_ctr.fetch_add(objects, std::memory_order_relaxed);
    present_roles_ctr.fetch_add(present_roles, std::memory_order_relaxed);
    pending_roles_ctr.fetch_add(pending_roles, std::memory_order_relaxed);
    ready_roles_ctr.fetch_add(ready_roles, std::memory_order_relaxed);
    if (present_roles == active_roles) ++full_present_ctr;
    if (ready_roles == active_roles) ++full_ready_ctr;
    if (layer >= 0 && layer < 128) {
        std::atomic<uint64_t> *layer_calls = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_calls :
            g_q4_graph_hit_profile.layer_post_provider_calls;
        std::atomic<uint64_t> *layer_active_objects = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_active_objects :
            g_q4_graph_hit_profile.layer_post_provider_active_objects;
        std::atomic<uint64_t> *layer_present_roles = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_present_roles :
            g_q4_graph_hit_profile.layer_post_provider_present_roles;
        std::atomic<uint64_t> *layer_pending_roles = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_pending_roles :
            g_q4_graph_hit_profile.layer_post_provider_pending_roles;
        std::atomic<uint64_t> *layer_ready_roles = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_ready_roles :
            g_q4_graph_hit_profile.layer_post_provider_ready_roles;
        std::atomic<uint64_t> *layer_full_present = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_full_present_calls :
            g_q4_graph_hit_profile.layer_post_provider_full_present_calls;
        std::atomic<uint64_t> *layer_full_ready = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_full_ready_calls :
            g_q4_graph_hit_profile.layer_post_provider_full_ready_calls;
        ++layer_calls[layer];
        layer_active_objects[layer].fetch_add(objects, std::memory_order_relaxed);
        layer_present_roles[layer].fetch_add(present_roles, std::memory_order_relaxed);
        layer_pending_roles[layer].fetch_add(pending_roles, std::memory_order_relaxed);
        layer_ready_roles[layer].fetch_add(ready_roles, std::memory_order_relaxed);
        if (present_roles == active_roles) ++layer_full_present[layer];
        if (ready_roles == active_roles) ++layer_full_ready[layer];
    }
    if (!post_wait && !descriptors.empty() && descriptors.size() == objects) {
        (void)q4_graph_descriptor_dry_run_copy(layer, descriptors);
    } else if (!post_wait && q4_graph_descriptor_dry_run_enabled()) {
        ++g_q4_graph_hit_profile.descriptor_dry_run_failures;
    }
    char label[192];
    std::snprintf(label, sizeof(label),
            "%s layer=%d present=%llu/%llu pending=%llu ready=%llu",
            post_wait ? "q4_graph_post_wait" : "q4_graph_post_provider",
            layer,
            (unsigned long long)present_roles,
            (unsigned long long)active_roles,
            (unsigned long long)pending_roles,
            (unsigned long long)ready_roles);
    moe_nvtx_range nvtx(label);
}

