    return expert_pack_env_bool("GGML_MOE_Q4_HOST_OBJECT_PREFETCH", false);
}

static size_t q4_colibri_host_object_prefetch_slots() {
    // Keep the default small, but allow explicit RAM-cache A/B runs above the
    // original 512-slot cap under the 16GB cgroup gate.
    return expert_pack_env_size("GGML_MOE_Q4_HOST_OBJECT_PREFETCH_SLOTS", 64, 1, 4096);
}

static size_t q4_colibri_host_object_prefetch_queue_limit() {
    return expert_pack_env_size("GGML_MOE_Q4_HOST_OBJECT_PREFETCH_QUEUE", 256, 1, 4096);
}

static bool q4_colibri_host_object_defer_h2d_enabled() {
    if (!g_expert_pack.q4_colibri) return false;
    return expert_pack_env_bool("GGML_MOE_Q4_HOST_OBJECT_DEFER_H2D", false);
}

static size_t q4_colibri_host_object_prefetch_max_bytes() {
    const size_t mib = expert_pack_env_size("GGML_MOE_Q4_HOST_OBJECT_PREFETCH_MAX_MIB", 0, 0, 15360);
    return mib * 1024ULL * 1024ULL;
}

static bool q4_colibri_host_object_pageable_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_HOST_OBJECT_PAGEABLE", false);
}

static size_t q4_colibri_host_object_pinned_prefix_slots() {
    return expert_pack_env_size("GGML_MOE_Q4_HOST_OBJECT_PINNED_PREFIX_SLOTS", 0, 0, 4096);
}

static size_t q4_colibri_host_object_register_pageable_after_read_limit() {
    return expert_pack_env_size(
        "GGML_MOE_Q4_HOST_OBJECT_REGISTER_PAGEABLE_AFTER_READ", 0, 0, 4096);
}

static bool q4_colibri_host_object_slot_should_be_pageable(
        const q4_colibri_host_object_slot &slot) {
    if (q4_colibri_host_object_pageable_enabled()) return true;
    const size_t pinned_prefix = q4_colibri_host_object_pinned_prefix_slots();
    if (pinned_prefix == 0 || g_q4_host_object_prefetch.slots.empty()) return false;
    const ptrdiff_t slot_idx = &slot - g_q4_host_object_prefetch.slots.data();
    return slot_idx >= 0 && (size_t)slot_idx >= pinned_prefix;
}

static void q4_colibri_host_object_free(q4_colibri_host_object_slot &slot) {
    if (!slot.host) return;
    if (slot.host_registered) {
        (void)cudaHostUnregister(slot.host);
        slot.host_registered = false;
    }
    if (slot.pageable) {
        std::free(slot.host);
    } else {
        cudaFreeHost(slot.host);
    }
    slot.host = nullptr;
    slot.capacity = 0;
    slot.pageable = false;
    slot.host_registered = false;
    slot.host_register_attempted = false;
}

static bool q4_colibri_host_object_alloc(q4_colibri_host_object_slot &slot, size_t bytes) {
    if (q4_colibri_host_object_slot_should_be_pageable(slot)) {
        void *ptr = nullptr;
        if (posix_memalign(&ptr, 4096, bytes) != 0) return false;
        slot.host = ptr;
        slot.pageable = true;
        slot.host_registered = false;
        slot.host_register_attempted = false;
        return true;
    }
    if (cudaHostAlloc(&slot.host, bytes, cudaHostAllocDefault) != cudaSuccess) return false;
    slot.pageable = false;
    slot.host_registered = false;
    slot.host_register_attempted = false;
    return true;
}

static void q4_colibri_host_object_try_register_pageable(
        q4_colibri_host_object_slot &slot) {
    const size_t limit = q4_colibri_host_object_register_pageable_after_read_limit();
    if (limit == 0 || !slot.pageable || slot.host_registered || slot.host_register_attempted ||
            !slot.host || slot.capacity == 0) return;
    if (g_q4_host_object_prefetch.register_pageable_successes.load(std::memory_order_relaxed) >= limit) return;

    slot.host_register_attempted = true;
    ++g_q4_host_object_prefetch.register_pageable_attempts;
    const auto start = std::chrono::steady_clock::now();
    const cudaError_t status = cudaHostRegister(slot.host, slot.capacity, cudaHostRegisterDefault);
    const uint64_t elapsed_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
        std::chrono::steady_clock::now() - start).count();
    g_q4_host_object_prefetch.register_pageable_us.fetch_add(elapsed_us, std::memory_order_relaxed);
    if (status == cudaSuccess) {
        slot.host_registered = true;
        ++g_q4_host_object_prefetch.register_pageable_successes;
        g_q4_host_object_prefetch.register_pageable_bytes.fetch_add(slot.capacity, std::memory_order_relaxed);
    } else {
        ++g_q4_host_object_prefetch.register_pageable_failures;
    }
}

static bool q4_colibri_host_object_budget_enabled_locked() {
    return g_q4_host_object_prefetch.max_resident_bytes > 0;
}

static bool q4_colibri_host_object_budget_fits_locked(const q4_colibri_host_object_slot &slot, size_t bytes) {
    const size_t limit = g_q4_host_object_prefetch.max_resident_bytes;
    if (limit == 0) return true;
    const size_t old_capacity = slot.capacity;
    const size_t resident_without_slot =
        g_q4_host_object_prefetch.resident_capacity_bytes >= old_capacity ?
        g_q4_host_object_prefetch.resident_capacity_bytes - old_capacity : 0;
    return resident_without_slot <= limit && bytes <= limit - resident_without_slot;
}

static void q4_colibri_host_object_account_free_locked(q4_colibri_host_object_slot &slot) {
    if (slot.capacity > 0) {
        if (g_q4_host_object_prefetch.resident_capacity_bytes >= slot.capacity) {
            g_q4_host_object_prefetch.resident_capacity_bytes -= slot.capacity;
        } else {
            g_q4_host_object_prefetch.resident_capacity_bytes = 0;
        }
    }
}

static void q4_colibri_host_object_account_alloc_locked(q4_colibri_host_object_slot &slot, size_t bytes) {
    slot.capacity = bytes;
    g_q4_host_object_prefetch.resident_capacity_bytes += bytes;
    g_q4_host_object_prefetch.resident_capacity_peak_bytes = std::max(
        g_q4_host_object_prefetch.resident_capacity_peak_bytes,
        g_q4_host_object_prefetch.resident_capacity_bytes);
}

