static bool q4_colibri_ram_net_layer_allowed(int layer) {
    if (!q4_colibri_ram_net_admission_enabled()) return true;
    const q4_colibri_layer_set_config &cfg = q4_colibri_ram_net_layer_set_config();
    if (!cfg.enabled) return true;
    return layer >= 0 && layer < 128 && cfg.allowed[layer];
}

