static bool q4_colibri_host_object_slot_occupied(const q4_colibri_host_object_slot &slot) {
    return slot.ready || slot.loading || slot.in_use || slot.pending_h2d || slot.pending_d2h;
}

static size_t q4_colibri_host_object_layer_occupancy_locked(int layer) {
    if (layer < 0 || layer >= 128) return 0;
    size_t count = 0;
    for (const q4_colibri_host_object_slot &slot : g_q4_host_object_prefetch.slots) {
        if (q4_colibri_host_object_slot_occupied(slot) && slot.marker.layer_idx == layer) {
            ++count;
        }
    }
    return count;
}

static bool q4_colibri_host_object_quota_victim_allowed_locked(
        const q4_colibri_host_object_slot &slot,
        int incoming_layer,
        size_t incoming_occupancy,
        size_t incoming_quota) {
    if (!q4_colibri_host_object_layer_quota_enabled()) return true;
    if (!q4_colibri_host_object_slot_occupied(slot)) {
        return incoming_occupancy < incoming_quota;
    }
    if (incoming_quota == 0) return false;
    if (incoming_occupancy >= incoming_quota) {
        return slot.ready && slot.marker.layer_idx == incoming_layer;
    }
    const size_t victim_quota = q4_colibri_host_object_layer_quota(slot.marker.layer_idx);
    if (victim_quota == 0) return true;
    const size_t victim_occupancy = q4_colibri_host_object_layer_occupancy_locked(slot.marker.layer_idx);
    return victim_occupancy > victim_quota;
}

static std::string q4_colibri_host_object_key(const q4_colibri_object_marker &marker) {
    char buf[160];
    std::snprintf(buf, sizeof(buf), "%d:%d:%d:%016lx:%lu:%zu",
            marker.source_idx, marker.layer_idx, marker.expert_idx,
            (unsigned long)marker.manifest_generation,
            (unsigned long)marker.offset, marker.bytes);
    return std::string(buf);
}

