        (unsigned long)g_q4_host_object_prefetch.alloc_failures.load(),
        (unsigned long)g_q4_host_object_prefetch.read_failures.load(),
        (unsigned long)g_q4_host_object_prefetch.budget_skips.load(),
        (unsigned long)g_q4_host_object_prefetch.budget_pressure_evictions.load(),
        resident_capacity_at_shutdown,
        g_q4_host_object_prefetch.resident_capacity_peak_bytes,
        g_q4_host_object_prefetch.max_resident_bytes,
        (unsigned long)g_q4_host_object_prefetch.bytes_read.load(),
        (unsigned long)g_q4_host_object_prefetch.bytes_avoided.load(),
        (unsigned long)g_q4_host_object_prefetch.h2d_roles.load(),
        (unsigned long)g_q4_host_object_prefetch.h2d_bytes.load(),
        (unsigned long)g_q4_host_object_prefetch.h2d_us.load(),
        g_q4_host_object_prefetch.queue.size(),
        g_q4_host_object_prefetch.ready.size(),
        q4_colibri_eligible_layer_profile_enabled() ? 1 : 0,
        (unsigned long)g_q4_host_object_prefetch.eligible_layer_demands.load(),
        (unsigned long)g_q4_host_object_prefetch.eligible_layer_hits.load(),
        (unsigned long)g_q4_host_object_prefetch.eligible_layer_misses.load(),
        (unsigned long)g_q4_host_object_prefetch.ineligible_layer_demands.load(),
        (unsigned long)g_q4_host_object_prefetch.ineligible_layer_hits.load(),
        (unsigned long)g_q4_host_object_prefetch.ineligible_layer_misses.load(),
        (unsigned long)g_q4_host_object_prefetch.eligible_layer_read_admits.load(),
        (unsigned long)g_q4_host_object_prefetch.ineligible_layer_read_rejects.load(),
        (unsigned long)q4_colibri_host_object_admit_min_read_us(),
        (unsigned long)g_q4_host_object_prefetch.read_admit_min_read_us_skips.load(),
        (unsigned long)(g_q4_host_object_prefetch.read_admit_min_read_us_skips.load() > 0 ?
            g_q4_host_object_prefetch.read_admit_min_read_us_skip_sum.load() /
                g_q4_host_object_prefetch.read_admit_min_read_us_skips.load() : 0),
        (unsigned long)g_q4_host_object_prefetch.preload_candidates.load(),
        (unsigned long)g_q4_host_object_prefetch.preload_submitted.load(),
        (unsigned long)g_q4_host_object_prefetch.preload_missing.load(),
        (unsigned long)g_q4_host_object_prefetch.preload_bad_lines.load(),
        (unsigned long)g_q4_host_object_prefetch.preload_us.load(),
        q4_colibri_host_object_admit_on_read_enabled() ? 1 : 0,
        (unsigned long)g_expert_pack.q4_host_object_read_admissions.load(),
        (unsigned long)g_expert_pack.q4_host_object_read_admit_bytes.load(),
        (unsigned long)g_expert_pack.q4_host_object_read_admit_evictions.load(),
        (unsigned long)g_expert_pack.q4_host_object_read_admit_alloc_failures.load(),
        q4_colibri_host_object_score_policy_enabled() ? 1 : 0,
        (unsigned long)q4_colibri_host_object_score_admit_margin(),
        q4_colibri_host_object_score_admit_margin_layer_spec_enabled() ? 1 : 0,
        (unsigned long)g_q4_host_object_prefetch.score_admit_skips.load(),
        (unsigned long)g_q4_host_object_prefetch.score_admissions.load(),
        (unsigned long)g_q4_host_object_prefetch.score_evictions.load(),
        (unsigned long)g_q4_host_object_prefetch.score_protected_victims.load(),
        (unsigned long)g_q4_host_object_prefetch.score_read_empty_admissions.load(),
        (unsigned long)g_q4_host_object_prefetch.score_read_eviction_candidates.load(),
        (unsigned long)g_q4_host_object_prefetch.score_read_candidate_gt_victim.load(),
        (unsigned long)g_q4_host_object_prefetch.score_read_candidate_eq_victim.load(),
        (unsigned long)g_q4_host_object_prefetch.score_read_candidate_lt_victim.load(),
        g_q4_host_object_prefetch.request_freq.size(),
        q4_colibri_host_object_score_dynamic_current_enabled() ? 1 : 0,
        q4_colibri_host_object_score_dynamic_victims_only_enabled() ? 1 : 0,
        q4_colibri_host_object_score_protect_victims_only_enabled() ? 1 : 0,
        q4_colibri_flow_score_cache_enabled() ? 1 : 0,
        (unsigned long)expert_pack_env_size("GGML_MOE_Q4_FLOW_SCORE_LAYER_WINDOW", 8, 1, 128),
        q4_colibri_flow_score_dynamic_hotness_enabled() ? 1 : 0,
        (unsigned long)q4_colibri_flow_score_min_admit(),
        expert_pack_env_bool("GGML_MOE_Q4_FLOW_SCORE_DUP_PENALTY", false) ? 1 : 0,
        q4_full_distance_score_enabled() ? 1 : 0,
        (unsigned long)expert_pack_env_size("GGML_MOE_Q4_FULL_DISTANCE_PAST_PENALTY", 2000, 0, 1000000000ULL),
        q4_colibri_layer_score_bonus_enabled() ? 1 : 0,
        q4_colibri_host_object_layer_quota_enabled() ? 1 : 0,
        q4_colibri_host_object_layer_quota_configured() ? 1 : 0,
        (unsigned long)q4_colibri_host_object_layer_quota_max_demands(),
        q4_colibri_host_object_layer_quota_expired() ? 1 : 0,
        q4_colibri_host_object_layer_quota_apply_demote_enabled() ? 1 : 0,
        (unsigned long)g_q4_host_object_prefetch.layer_quota_rejects.load(),
        (unsigned long)g_q4_host_object_prefetch.layer_quota_evictions.load(),
        (unsigned long)g_q4_host_object_prefetch.layer_quota_protected.load(),
        q4_colibri_host_object_refresh_score_on_hit_enabled() ? 1 : 0,
        (unsigned long)g_q4_host_object_prefetch.score_hit_refreshes.load(),
        q4_colibri_static_hotness_enabled() ? 1 : 0,
        q4_colibri_static_hotness_entries(),
        (unsigned long)g_q4_host_object_prefetch.static_hotness_score_hits.load(),
        (unsigned long)g_q4_host_object_prefetch.static_hotness_score_bonus.load(),
        q4_colibri_ram_near_victim_enabled() ? 1 : 0,
        q4_colibri_ram_near_victim_forward_window(),
